window.DATA_PART=window.DATA_PART||{};window.DATA_PART["bure"]={"lectures":[{"id":"bure-v1","nr":"1","title":"Modul 1: Wertebenen, Bilanz, Eigenkapital","date":"2026-10-14","summary":["Gebucht wird nur, was finanzielle Folgen hat: <b class=\"term\">Relevantes Ereignis</b>.","Jede <b class=\"term\">Wertebene</b> misst anders: Zahlungsmittel, Geldvermögen oder Reinvermögen.","<b class=\"fx\" data-f=\"bure-f1\">Bilanzgleichung</b>: <b class=\"term\">Vermögensgüter</b> − <b class=\"term\">Fremdkapital</b> = <b class=\"term\">Eigenkapital</b>.","<b class=\"term\">Einkommen</b> = <b class=\"term\">Ertrag</b> − <b class=\"term\">Aufwand</b>. <b class=\"term\">Einlage</b> und <b class=\"term\">Entnahme</b> zählen nicht dazu.","Zeitpunkt: <b class=\"term\">Marktleistungsabgabekonzept</b>, <b class=\"term\">Periodisierungskonzept</b> oder <b class=\"term\">Einkommensvorwegnahmekonzept</b>."],"formulas":["bure-f1","bure-f2","bure-f3","bure-f4","bure-f5","bure-f6","bure-f7","bure-f8","bure-f9","bure-f10","bure-f11","bure-f28"],"visuals":[{"title":"Bilanz als Waage","svg":"<svg viewBox=\"0 0 360 210\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"90\" y=\"26\" fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">Aktiva (Verwendung)</text><text x=\"270\" y=\"26\" fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">Passiva (Herkunft)</text><rect x=\"15\" y=\"36\" width=\"150\" height=\"108\" rx=\"6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"195\" y=\"36\" width=\"150\" height=\"108\" rx=\"6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"22\" y=\"56\" fill=\"currentColor\" font-size=\"11\">Zahlungsmittel</text><text x=\"158\" y=\"56\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">119.500</text><text x=\"22\" y=\"74\" fill=\"currentColor\" font-size=\"11\">Forderungen</text><text x=\"158\" y=\"74\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">5.000</text><text x=\"22\" y=\"92\" fill=\"currentColor\" font-size=\"11\">Büromaterial</text><text x=\"158\" y=\"92\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">7.000</text><text x=\"22\" y=\"110\" fill=\"currentColor\" font-size=\"11\">Grundstücke</text><text x=\"158\" y=\"110\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">30.000</text><text x=\"202\" y=\"56\" fill=\"currentColor\" font-size=\"11\">Eigenkapital</text><text x=\"338\" y=\"56\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">159.500</text><text x=\"202\" y=\"74\" fill=\"currentColor\" font-size=\"11\">Fremdkapital</text><text x=\"338\" y=\"74\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">2.000</text><line x1=\"22\" y1=\"122\" x2=\"158\" y2=\"122\" stroke=\"currentColor\"/><line x1=\"202\" y1=\"122\" x2=\"338\" y2=\"122\" stroke=\"currentColor\"/><text x=\"22\" y=\"138\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Summe</text><text x=\"158\" y=\"138\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"end\" font-weight=\"700\">161.500</text><text x=\"202\" y=\"138\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Summe</text><text x=\"338\" y=\"138\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"end\" font-weight=\"700\">161.500</text><line x1=\"10\" y1=\"150\" x2=\"350\" y2=\"150\" stroke=\"currentColor\" stroke-width=\"3\"/><polygon points=\"180,152 166,178 194,178\" fill=\"var(--acc)\" stroke=\"currentColor\"/><line x1=\"150\" y1=\"178\" x2=\"210\" y2=\"178\" stroke=\"currentColor\"/><text x=\"180\" y=\"196\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\">161.500 = 161.500 → Waage im Gleichgewicht</text></svg>","caption":"Karl Gross 31.12.20X1 (Folie 62): Aktiva = Passiva, das EK ist der Rest."},{"title":"Vier Bilanzveränderungen","svg":"<svg viewBox=\"0 0 360 258\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"169\" y=\"20\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">vorher</text><text x=\"257\" y=\"20\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">nachher</text><text x=\"313\" y=\"20\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">Summe</text><text x=\"10\" y=\"50\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Aktivtausch</text><text x=\"10\" y=\"67\" fill=\"currentColor\" font-size=\"11\">Grundstück 20 bar</text><rect x=\"150\" y=\"56.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"150\" y=\"42\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"70.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"63.6\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"42\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><line x1=\"196\" y1=\"60\" x2=\"224\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"230,60 222,55 222,65\" fill=\"currentColor\"/><rect x=\"238\" y=\"63.6\" width=\"18\" height=\"14.4\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"238\" y=\"42\" width=\"18\" height=\"21.6\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"70.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"63.6\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"42\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"286\" y=\"64\" fill=\"currentColor\" font-size=\"11\">100 → 100</text><text x=\"10\" y=\"102\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Passivtausch</text><text x=\"10\" y=\"119\" fill=\"currentColor\" font-size=\"11\">Schuld 10 → Darlehen</text><rect x=\"150\" y=\"108.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"150\" y=\"94\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"122.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"115.6\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"94\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><line x1=\"196\" y1=\"112\" x2=\"224\" y2=\"112\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"230,112 222,107 222,117\" fill=\"currentColor\"/><rect x=\"238\" y=\"108.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"238\" y=\"94\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"126.4\" width=\"18\" height=\"3.6\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"115.6\" width=\"18\" height=\"10.8\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"94\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"286\" y=\"116\" fill=\"currentColor\" font-size=\"11\">100 → 100</text><text x=\"10\" y=\"154\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Bilanzverlängerung</text><text x=\"10\" y=\"171\" fill=\"currentColor\" font-size=\"11\">Material 20 auf Ziel</text><rect x=\"150\" y=\"160.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"150\" y=\"146\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"174.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"167.6\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"146\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><line x1=\"196\" y1=\"164\" x2=\"224\" y2=\"164\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"230,164 222,159 222,169\" fill=\"currentColor\"/><rect x=\"238\" y=\"160.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"238\" y=\"146\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"238\" y=\"138.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"167.6\" width=\"18\" height=\"14.4\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"160.4\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"138.8\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"286\" y=\"168\" fill=\"currentColor\" font-size=\"11\">100 → 120</text><text x=\"10\" y=\"206\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Bilanzverkürzung</text><text x=\"10\" y=\"223\" fill=\"currentColor\" font-size=\"11\">Schuld 10 bar getilgt</text><rect x=\"150\" y=\"212.4\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"150\" y=\"198\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"226.8\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"219.6\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"171\" y=\"198\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><line x1=\"196\" y1=\"216\" x2=\"224\" y2=\"216\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"230,216 222,211 222,221\" fill=\"currentColor\"/><rect x=\"238\" y=\"216\" width=\"18\" height=\"18\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"238\" y=\"201.6\" width=\"18\" height=\"14.4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"230.4\" width=\"18\" height=\"3.6\" fill=\"var(--acc)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"223.2\" width=\"18\" height=\"7.2\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"259\" y=\"201.6\" width=\"18\" height=\"21.6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"286\" y=\"220\" fill=\"currentColor\" font-size=\"11\">100 → 90</text><text x=\"159\" y=\"248\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">A</text><text x=\"180\" y=\"248\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">P</text><text x=\"247\" y=\"248\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">A</text><text x=\"268\" y=\"248\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">P</text></svg>","caption":"Dunkel = geänderter Posten. Start: ZM 60 + Grundstück 40 | Lief.-Schuld 20 + Darlehen 20 + EK 60."},{"title":"Vom EK am Anfang zum EK am Ende","svg":"<svg viewBox=\"0 0 340 212\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"15\" y1=\"170\" x2=\"325\" y2=\"170\" stroke=\"currentColor\"/><rect x=\"25\" y=\"74.65\" width=\"42\" height=\"95.35\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"46\" y=\"68.65\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">+150.000</text><text x=\"46\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Einlagen</text><rect x=\"87\" y=\"74.65\" width=\"42\" height=\"9.54\" fill=\"none\" stroke=\"currentColor\" stroke-dasharray=\"4 3\"/><text x=\"108\" y=\"68.65\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">−15.000</text><text x=\"108\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Entnahmen</text><line x1=\"67\" y1=\"74.65\" x2=\"87\" y2=\"74.65\" stroke=\"currentColor\" stroke-dasharray=\"2 2\"/><rect x=\"149\" y=\"40\" width=\"42\" height=\"44.18\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"170\" y=\"34\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">+69.500</text><text x=\"170\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Erträge</text><line x1=\"129\" y1=\"84.18\" x2=\"149\" y2=\"84.18\" stroke=\"currentColor\" stroke-dasharray=\"2 2\"/><rect x=\"211\" y=\"40\" width=\"42\" height=\"28.61\" fill=\"none\" stroke=\"currentColor\" stroke-dasharray=\"4 3\"/><text x=\"232\" y=\"34\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">−45.000</text><text x=\"232\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Aufwand</text><line x1=\"191\" y1=\"40\" x2=\"211\" y2=\"40\" stroke=\"currentColor\" stroke-dasharray=\"2 2\"/><line x1=\"253\" y1=\"68.61\" x2=\"273\" y2=\"68.61\" stroke=\"currentColor\" stroke-dasharray=\"2 2\"/><rect x=\"273\" y=\"68.61\" width=\"42\" height=\"101.39\" fill=\"var(--acc)\" stroke=\"currentColor\"/><text x=\"294\" y=\"62.61\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">159.500</text><text x=\"294\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">EK Ende</text><text x=\"170\" y=\"202\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">0 + 150.000 − 15.000 + 69.500 − 45.000 = 159.500</text></svg>","caption":"Karl Gross (Folien 59–61): Transfers und Einkommen erklären die ganze EK-Änderung."}],"examples":[{"title":"Eigenkapital als Rest","steps":["Vermögen: 119.500 + 5.000 + 7.000 + 30.000 = 161.500","Fremdkapital: 2.000","EK: \\(161.500 - 2.000 = 159.500\\)"]},{"title":"EK-Veränderung Karl Gross","steps":["Transfer: 150.000 − 15.000 = 135.000","Einkommen: 69.500 − 45.000 = 24.500","EK Ende: 0 + 135.000 + 24.500 = 159.500"]},{"title":"Verkauf auf Ziel 1.000 auf drei Ebenen","steps":["Zahlungsmittel unverändert: keine Einzahlung","Forderung +1.000: Einnahme 1.000","Leistung abgegeben: Ertrag 1.000"]}],"terms":[{"t":"Buchführung","sym":"","d":"Schreibt die finanziellen Folgen von Ereignissen geordnet auf.","ex":"Kauf eines Grundstücks: Zahlungsmittel sinken, Grundstücke steigen.","topic":"bure-zwecke"},{"t":"Internes Rechnungswesen","sym":"","d":"Berichte für Leute im Unternehmen.","ex":"Kalkulation, was ein Fertigteil kostet, für die Geschäftsleitung.","topic":"bure-zwecke"},{"t":"Externes Rechnungswesen","sym":"","d":"Berichte für Leute außerhalb.","ex":"Bilanz für Bank, Finanzamt, Investoren.","topic":"bure-zwecke"},{"t":"Relevantes Ereignis","sym":"","d":"Ein Ereignis mit finanziellen Folgen. Nur das wird gebucht.","ex":"Bareinkauf ja. Steigende Rohstoffpreise allein nein.","topic":"bure-zwecke"},{"t":"Vermögensgüter","sym":"Aktiva","d":"Alles, was dem Unternehmen gehört und Wert hat.","ex":"Karl Gross: 119.500 + 5.000 + 7.000 + 30.000 = 161.500.","topic":"bure-ek"},{"t":"Fremdkapital","sym":"FK","d":"Ansprüche Fremder auf die Ressourcen, also Schulden.","ex":"Karl Gross: Verbindlichkeiten 2.000 (Folie 62).","topic":"bure-ek"},{"t":"Eigenkapital","sym":"EK","d":"Der Teil, der dem Unternehmer gehört. Ergibt sich als Rest.","ex":"Vermögen 116.500, Fremdkapital 2.000, also EK 114.500 (Folie 51).","topic":"bure-ek"},{"t":"Passiva","sym":"","d":"Rechte Bilanzseite: Fremdkapital und Eigenkapital. Zeigt, woher die Mittel kommen.","ex":"Karl Gross: EK 159.500 + FK 2.000 = 161.500.","topic":"bure-ek"},{"t":"Bilanz","sym":"","d":"Gegenüberstellung von Vermögen und Kapital zu einem Stichtag.","ex":"Karl Gross 31.12.20X1: Aktiva 161.500 = Passiva 161.500 (Folie 62).","topic":"bure-ek"},{"t":"Mittelverwendung / Mittelherkunft","sym":"","d":"Aktiva zeigen, wofür das Geld steckt. Passiva zeigen, woher es kommt.","ex":"Grundstück (Verwendung), Darlehen (Herkunft).","topic":"bure-ek"},{"t":"Forderung","sym":"","d":"Anspruch auf künftiges Geld von jemand anderem.","ex":"Gutachten auf Ziel verkauft: Forderung 10.000.","topic":"bure-ek"},{"t":"Verbindlichkeit","sym":"","d":"Pflicht, künftig zu zahlen. Gehört zum Fremdkapital.","ex":"Büromaterial auf Ziel gekauft: Verbindlichkeit 3.000.","topic":"bure-ek"},{"t":"auf Ziel","sym":"","d":"Zahlung erst später.","ex":"Tesla gekauft, Rechnung in 30 Tagen fällig.","topic":"bure-ek"},{"t":"Einkommen","sym":"","d":"Eigenkapitaländerung durch die Geschäftstätigkeit: Ertrag minus Aufwand.","ex":"Erträge 69.500, Aufwand 45.000, Einkommen 24.500 (Folie 60).","topic":"bure-ek"},{"t":"Ertrag","sym":"","d":"Erhöht das Eigenkapital durch die Tätigkeit.","ex":"Gutachten für 12.000 abgeliefert.","topic":"bure-ek"},{"t":"Aufwand","sym":"","d":"Senkt das Eigenkapital durch die Tätigkeit.","ex":"Miete 4.000, verbrauchtes Büromaterial 600.","topic":"bure-ek"},{"t":"Eigenkapital-Transfer","sym":"","d":"Eigenkapitaländerung, die der Unternehmer selbst auslöst.","ex":"Einlage oder Entnahme.","topic":"bure-ek"},{"t":"Einlage","sym":"","d":"Der Eigentümer gibt Geld oder Sachen ins Unternehmen.","ex":"Gründung mit 100.000 bar.","topic":"bure-ek"},{"t":"Entnahme","sym":"","d":"Der Eigentümer nimmt Geld oder Sachen für sich heraus.","ex":"15.000 bar für private Zwecke.","topic":"bure-ek"},{"t":"Einzahlung / Auszahlung","sym":"","d":"Zahlungsmittel kommen herein oder gehen hinaus.","ex":"Kunde zahlt 1.000 bar: Einzahlung 1.000.","topic":"bure-zwecke"},{"t":"Einnahme / Ausgabe","sym":"","d":"Geldvermögen (Zahlungsmittel plus Forderungen minus Verbindlichkeiten) steigt oder sinkt.","ex":"Verkauf auf Ziel: Einnahme, aber keine Einzahlung.","topic":"bure-zwecke"},{"t":"Wertebene","sym":"","d":"Womit man misst: Zahlungsmittel, Geldvermögen oder Reinvermögen.","ex":"Die Buchführung arbeitet reinvermögensorientiert.","topic":"bure-zwecke"},{"t":"Totalbetrachtung","sym":"","d":"Blick auf die ganze Lebensdauer des Unternehmens.","ex":"A 1.3: Zahlungssaldo −550.000 = Einkommen −390.000 + Transfers −160.000.","topic":"bure-zwecke"},{"t":"Partialbetrachtung","sym":"","d":"Blick auf einen einzelnen Abrechnungszeitraum.","ex":"Geschäftsjahr 20X1.","topic":"bure-zwecke"},{"t":"Intratemporale Bilanzgleichung","sym":"","d":"Zu einem Zeitpunkt: Vermögensgüter minus Fremdkapital gleich Eigenkapital.","ex":"161.500 − 2.000 = 159.500.","topic":"bure-ek","viz":"<svg viewBox=\"0 0 200 110\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"40\" y=\"12\" width=\"36\" height=\"70\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"58\" y=\"98\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">VG 100</text><text x=\"93\" y=\"52\" fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">=</text><rect x=\"110\" y=\"12\" width=\"36\" height=\"42\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"110\" y=\"54\" width=\"36\" height=\"28\" fill=\"var(--acc)\" stroke=\"currentColor\"/><text x=\"152\" y=\"38\" fill=\"currentColor\" font-size=\"11\">EK 60</text><text x=\"152\" y=\"71\" fill=\"currentColor\" font-size=\"11\">FK 40</text></svg>"},{"t":"Intertemporale Bilanzgleichung","sym":"","d":"Über einen Zeitraum: Anfangsbestand plus Zunahmen minus Abnahmen gleich Endbestand.","ex":"EK 0 + Einlagen 150.000 + Erträge 69.500 − Entnahmen 15.000 − Aufwand 45.000 = 159.500.","topic":"bure-zwecke"},{"t":"Bestandsrechnung","sym":"","d":"Zeigt Werte an einem Zeitpunkt.","ex":"Bilanz: „Schnappschuss“.","topic":"bure-zwecke"},{"t":"Bewegungsrechnung","sym":"","d":"Zeigt Veränderungen während eines Zeitraums.","ex":"Einkommensrechnung: „Videoaufnahme“.","topic":"bure-zwecke"},{"t":"Einkommensrechnung","sym":"","d":"Listet Erträge und Aufwendungen eines Zeitraums. Saldo ist das Einkommen.","ex":"Erträge 69.500 − Aufwand 45.000 = Einkommen 24.500 (Folie 60).","topic":"bure-ek"},{"t":"Eigenkapitaltransferrechnung","sym":"","d":"Listet Einlagen und Entnahmen eines Zeitraums.","ex":"150.000 − 15.000 = 135.000 (Folie 59).","topic":"bure-ek"},{"t":"Eigenkapitalveränderungsrechnung","sym":"","d":"EK am Anfang plus Transfers plus Einkommen gleich EK am Ende.","ex":"0 + 135.000 + 24.500 = 159.500 (Folie 61).","topic":"bure-ek"},{"t":"Marktleistungsabgabekonzept","sym":"","d":"Einkommen aus Verkäufen entsteht erst beim Verkauf. Bis dahin bleibt alles einkommensneutral.","ex":"Produkte für 3.000 hergestellt, für 5.000 verkauft: Umsatzertrag 5.000, Umsatzaufwand 3.000.","topic":"bure-konzepte"},{"t":"Periodisierungskonzept","sym":"","d":"Einnahmen und Ausgaben ohne Bezug zum Verkauf wirken sofort, wenn sie anfallen.","ex":"Miete 4.000 bar: sofort Aufwand 4.000.","topic":"bure-konzepte"},{"t":"Einkommensvorwegnahmekonzept","sym":"","d":"Absehbare künftige Einnahmen oder Ausgaben wirken schon jetzt.","ex":"Absehbarer Schadensersatz 12.000: Aufwand 12.000 schon jetzt.","topic":"bure-konzepte"},{"t":"Marginalprinzip","sym":"","d":"Einem Erzeugnis werden nur direkt zurechenbare Ausgaben zugeordnet.","ex":"Material 12.000 (direkt), Hallenlicht 3.000 (indirekt): nur 12.000 ins Lager.","topic":"bure-konzepte"},{"t":"Finalprinzip","sym":"","d":"Einem Erzeugnis werden direkte und indirekte Ausgaben zugeordnet.","ex":"Material 12.000 + Hallenlicht 3.000 = 15.000 ins Lager.","topic":"bure-konzepte"},{"t":"Wirtschaftseinheit","sym":"","d":"Unternehmen und Privatperson sind getrennt. Private Vorgänge bucht das Unternehmen nicht.","ex":"Renovierung der Privatwohnung vom Privatkonto: keine Buchung (Folie 52).","topic":"bure-zwecke"},{"t":"HGB / IFRS","sym":"","d":"Deutsches Handelsgesetzbuch und internationale Rechnungslegungsstandards.","ex":"Gleiche Posten können je nach Standard anders heißen (Modul 2, Folie 8).","topic":"bure-zwecke"},{"t":"Aktivtausch","sym":"","d":"Ein Vermögensgut steigt, ein anderes sinkt. Bilanzsumme bleibt gleich.","ex":"Grundstück 60.000 bar: Grundstück +60.000, Zahlungsmittel −60.000.","topic":"bure-ek"},{"t":"Passivtausch","sym":"","d":"Ein Kapitalposten steigt, ein anderer sinkt. Bilanzsumme bleibt gleich.","ex":"Lieferantenschuld 10.000 wird Bankdarlehen: Verb. Einkauf −10.000, Verb. Bank +10.000.","topic":"bure-ek"},{"t":"Bilanzverlängerung","sym":"","d":"Vermögen und Kapital steigen gleich stark. Bilanzsumme steigt.","ex":"Material 3.000 auf Ziel: Material +3.000, FK +3.000.","topic":"bure-ek"},{"t":"Bilanzverkürzung","sym":"","d":"Vermögen und Kapital sinken gleich stark. Bilanzsumme sinkt.","ex":"Schuld 1.000 bar bezahlt: Zahlungsmittel −1.000, FK −1.000.","topic":"bure-ek"}],"time":"10:30–12:00","story":[{"h":"Worum geht es überhaupt?"},{"p":"Stell dir vor, Karl Gross gründet eine Unternehmensberatung. Am Jahresende will er zwei Dinge wissen. Erstens: Wie viel von der Firma gehört mir? Zweitens: Bin ich durch die Arbeit reicher geworden? Genau diese zwei Fragen beantwortet die <b class=\"term\">Buchführung</b>. Sie schreibt die finanziellen Folgen von Ereignissen geordnet auf."},{"p":"Die Berichte daraus gehen an zwei Gruppen. Leute im Unternehmen, etwa die Geschäftsleitung, bekommen das <b class=\"term\">Internes Rechnungswesen</b>. Leute außerhalb, etwa Bank, Finanzamt und Investoren, bekommen das <b class=\"term\">Externes Rechnungswesen</b>. Die Buchführung ist die gemeinsame „Sprache“ für beide."},{"p":"Gebucht wird nur ein <b class=\"term\">Relevantes Ereignis</b>, also eines mit finanziellen Folgen. Kauft Karl ein Grundstück für 60.000 €, wird gebucht. Steigen die Rohstoffpreise oder ändert sich die politische Lage, passiert in der Buchführung nichts. Erst wenn Geld fließt oder sich ein Wert messbar ändert, gibt es eine Buchung."},{"tip":"Merksatz: Kein Betrag, keine Buchung. Die Buchführung beschränkt sich auf den Einkommensaspekt."},{"h":"Die zwei Zielgrößen: Eigenkapital und Einkommen"},{"p":"Das <b class=\"term\">Eigenkapital</b> (EK) ist der Teil des Unternehmens, der Karl selbst gehört. Es ändert sich auf genau zwei Arten. Erstens durch Karl selbst: Er legt Geld ein oder nimmt Geld heraus. Das heißt <b class=\"term\">Eigenkapital-Transfer</b>, also <b class=\"term\">Einlage</b> oder <b class=\"term\">Entnahme</b>. Zweitens durch die Geschäftstätigkeit: Das ist das <b class=\"term\">Einkommen</b>, also <b class=\"term\">Ertrag</b> minus <b class=\"term\">Aufwand</b>."},{"p":"Mit Zahlen: Karl legt 100.000 € ein. Das ist ein Transfer, kein Einkommen. Er liefert ein Gutachten für 12.000 € ab: Ertrag. Dafür verbraucht er Büromaterial für 600 €: Aufwand. Einkommen aus diesem Auftrag: 12.000 − 600 = 11.400 €. Die 100.000 € Einlage erhöhen zwar das EK, zählen aber nicht zum Einkommen."},{"f":"bure-f5"},{"tip":"Typischer Fehler: Eine Einlage als Ertrag zählen. Nein. Einlage und Entnahme sind Transfers. Ertrag und Aufwand kommen aus der Tätigkeit."},{"h":"Drei Wertebenen: Womit messen wir „reicher“?"},{"p":"Bevor du buchst, musst du entscheiden, womit du Reichtum misst. Das ist die <b class=\"term\">Wertebene</b>. Es gibt drei. Ebene 1: nur Zahlungsmittel, also Kasse und Bank. Änderungen heißen <b class=\"term\">Einzahlung / Auszahlung</b>. Ebene 2: Geldvermögen, also Zahlungsmittel plus Forderungen minus Verbindlichkeiten. Änderungen heißen <b class=\"term\">Einnahme / Ausgabe</b>. Ebene 3: Reinvermögen, also alle Vermögensgüter minus Fremdkapital. Das ist das Eigenkapital. Änderungen heißen Ertrag und Aufwand bzw. Einlage und Entnahme."},{"f":"bure-f7"},{"p":"<table class=\"tt\"><tr><th>Ebene</th><th>Bestand</th><th>Plus</th><th>Minus</th><th>Saldo</th></tr><tr><td>1</td><td>Zahlungsmittel</td><td>Einzahlung</td><td>Auszahlung</td><td><b class=\"fx\" data-f=\"bure-f8\">Einzahlungsüberschuss</b></td></tr><tr><td>2</td><td>Geldvermögen</td><td>Einnahme</td><td>Ausgabe</td><td><b class=\"fx\" data-f=\"bure-f9\">Einnahmenüberschuss</b></td></tr><tr><td>3</td><td>Reinvermögen = EK</td><td>Ertrag, Einlage</td><td>Aufwand, Entnahme</td><td>Einkommen und Transfer</td></tr></table>"},{"p":"Das Tesla-Beispiel der Folien: Das Unternehmen kauft einen Tesla <b class=\"term\">auf Ziel</b>, zahlt also erst später. Ebene 1: nichts passiert, kein Geld fließt. Ebene 2: Die Verbindlichkeiten steigen, das Geldvermögen sinkt. Das ist eine Ausgabe. Ebene 3: Es gibt eine Schuld, aber auch ein neues Auto als Vermögensgut. Das Reinvermögen bleibt gleich. Dasselbe Ereignis sieht auf jeder Ebene anders aus."},{"ex":2},{"p":"Die Buchführung arbeitet auf Ebene 3, reinvermögensorientiert. Deshalb heißt ihr Ergebnis Einkommen und nicht Einzahlungsüberschuss."},{"h":"Total- und Partialbetrachtung"},{"p":"Welche Ebene du brauchst, hängt vom Zeitraum ab. Bei der <b class=\"term\">Totalbetrachtung</b> schaust du auf die ganze Lebensdauer des Unternehmens, von der Gründung bis zur Auflösung. Am Ende sind alle Forderungen bezahlt und alle Güter verkauft. Dann sind alle Ebenen gleich: Die Summe der Zahlungssalden ist gleich Einkommen plus Transfers (<b class=\"fx\" data-f=\"bure-f10\">Totalbetrachtung</b>). In A 1.3 der Übung: −550.000 = −390.000 + (−160.000)."},{"p":"Bei der <b class=\"term\">Partialbetrachtung</b> schaust du nur auf ein Jahr. Da unterscheiden sich die Ebenen, weil Forderungen offen sind oder Material noch im Lager liegt. Beispiel aus der Übung: Eine Maschine für 400.000 € hält 4 Jahre. Auszahlung im Jahr 1: 400.000 €. Aufwand aber jedes Jahr nur 400.000 / 4 = 100.000 € (<b class=\"fx\" data-f=\"bure-f11\">gleichmäßige Abschreibung</b>). Genau deshalb braucht die Buchführung Regeln, wann etwas Einkommen ist. Die kommen weiter unten."},{"h":"Bestand und Bewegung: die intertemporale Bilanzgleichung"},{"p":"Für jede Ebene gilt dieselbe Rechnung: Anfangsbestand + Zunahmen − Abnahmen = Endbestand. Das ist die <b class=\"term\">Intertemporale Bilanzgleichung</b>. „Intertemporal“ heißt: zwischen zwei Zeitpunkten."},{"f":"bure-f3"},{"p":"Beispiel Zahlungsmittel: Am 1.1. hast du 3.000 €. Im Jahr kommen 3.700 € herein und 3.000 € gehen hinaus. Ende: 3.000 + 3.700 − 3.000 = 3.700 €. Beim Eigenkapital sind die Zunahmen Einlagen und Erträge, die Abnahmen Entnahmen und Aufwendungen."},{"p":"Dazu zwei Begriffe. Eine <b class=\"term\">Bestandsrechnung</b> zeigt Werte an einem Zeitpunkt, wie ein Foto. Eine <b class=\"term\">Bewegungsrechnung</b> zeigt Veränderungen in einem Zeitraum, wie ein Video. Die <b class=\"term\">Bilanz</b> ist die Bestandsrechnung für das EK. Die <b class=\"term\">Eigenkapitaltransferrechnung</b> (Einlagen und Entnahmen) und die <b class=\"term\">Einkommensrechnung</b> (Erträge und Aufwendungen) sind die beiden Bewegungsrechnungen."},{"tip":"Foto = Bilanz. Video = Einkommensrechnung und Eigenkapitaltransferrechnung."},{"h":"Anforderungen an die Buchführung"},{"p":"In Deutschland gibt es zwei Regelwerke: <b class=\"term\">HGB / IFRS</b>. Beide verlangen Relevanz (aktuell und aussagekräftig) und Verlässlichkeit (ein Dritter kann es nachprüfen). Je schneller du berichtest, desto unsicherer sind die Zahlen. Dazu kommen Annahmen: Das Unternehmen ist eine eigene <b class=\"term\">Wirtschaftseinheit</b>, es wird fortgeführt, die Währung ist stabil. Karls private Wohnung gehört also nicht in die Bücher der Firma."},{"h":"Die Bilanz: intratemporale Bilanzgleichung"},{"p":"Jetzt zum Kern. Das Unternehmen besitzt <b class=\"term\">Vermögensgüter</b> (Aktiva): Zahlungsmittel, Forderungen, Material, Grundstücke. Andere haben Ansprüche darauf, das <b class=\"term\">Fremdkapital</b>, also die Schulden. Was übrig bleibt, gehört Karl: das Eigenkapital. Diese Rechnung zu einem Stichtag heißt <b class=\"term\">Intratemporale Bilanzgleichung</b>."},{"f":"bure-f1"},{"p":"Die Bilanz zeigt das als zwei Seiten. Links die Aktiva, rechts die <b class=\"term\">Passiva</b>, also Fremdkapital plus Eigenkapital. Beide Seiten sind immer gleich groß, weil das EK als Rest definiert ist. Die Seiten beantworten verschiedene Fragen (<b class=\"term\">Mittelverwendung / Mittelherkunft</b>): links „Wofür steckt das Geld?“, rechts „Woher kommt es?“."},{"f":"bure-f2"},{"v":0},{"ex":0},{"p":"Eine <b class=\"term\">Forderung</b> ist ein Vermögensgut: Jemand schuldet dir Geld, zum Beispiel 10.000 € für ein Gutachten auf Ziel. Eine <b class=\"term\">Verbindlichkeit</b> ist Fremdkapital: Du schuldest jemandem Geld, zum Beispiel 3.000 € für Büromaterial auf Ziel."},{"h":"Vier Fälle ohne Eigenkapital-Wirkung"},{"p":"Nicht jedes Ereignis ändert das Eigenkapital. Vier Fälle lassen es in Ruhe. <b class=\"term\">Aktivtausch</b>: Grundstück für 60.000 € bar, Grundstück +60.000, Zahlungsmittel −60.000. <b class=\"term\">Passivtausch</b>: Lieferantenschuld 10.000 € wird zum Bankdarlehen. <b class=\"term\">Bilanzverlängerung</b> ohne EK-Wirkung: Material für 3.000 € auf Ziel, Material +3.000, Verbindlichkeit +3.000. <b class=\"term\">Bilanzverkürzung</b> ohne EK-Wirkung: Schuld von 1.000 € bar bezahlt, Zahlungsmittel −1.000, Verbindlichkeit −1.000."},{"v":1},{"tip":"Prüffrage: Ändert sich nur die Aktivseite, nur das Fremdkapital, oder beides gleich stark? Dann kein Einkommen. Erst wenn das EK betroffen ist, gibt es Ertrag, Aufwand, Einlage oder Entnahme."},{"h":"Wann entsteht Einkommen? Drei Konzepte"},{"p":"Jetzt die Regeln von D. Schneider. Sie sagen, WANN ein Betrag Einkommen wird. Erstens das <b class=\"term\">Marktleistungsabgabekonzept</b>: Alles, was mit dem Verkauf von Gütern zu tun hat, wird erst beim Verkauf Einkommen. Beispiel: Du stellst Produkte für 3.000 € her. Bis zum Verkauf stehen sie zu 3.000 € als Fertigerzeugnisse in der Bilanz, einkommensneutral. Beim Verkauf für 5.000 € buchst du Umsatzertrag 5.000 € und Umsatzaufwand 3.000 €. Einkommen: 2.000 €."},{"p":"Zweitens das <b class=\"term\">Periodisierungskonzept</b>: Einnahmen und Ausgaben OHNE Bezug zu einem Verkauf wirken sofort, wenn sie anfallen. Miete 4.000 € bar: sofort Aufwand 4.000 €. Zinsen an die Bank, Werbung, ein Lottogewinn: ebenso sofort."},{"p":"Drittens das <b class=\"term\">Einkommensvorwegnahmekonzept</b>: Was absehbar ist, wirkt schon jetzt, auch wenn noch kein Geld geflossen ist. Ein laufendes Gerichtsverfahren mit absehbaren 12.000 € Schadensersatz: schon jetzt Aufwand 12.000 €. Eine Aktie, die sicher mit Gewinn verkauft wird: schon jetzt Ertrag."},{"tip":"Faustregel: Hat es mit einem Verkauf zu tun? Warten bis zum Verkauf. Nicht? Sofort. Nur absehbar? Schon vorweg."},{"h":"Marginal- oder Finalprinzip"},{"p":"Bleibt die Frage: Was „hat mit dem Verkauf zu tun“? Dafür gibt es zwei Zuordnungsprinzipien. Beim <b class=\"term\">Marginalprinzip</b> ordnest du dem Erzeugnis nur direkte Ausgaben zu, etwa Rohstoffe. Beim <b class=\"term\">Finalprinzip</b> auch indirekte, etwa das Licht in der Fertigungshalle oder Personal. Indirekte Ausgaben sind beim Marginalprinzip sofort Aufwand (Periodisierung). Beim Finalprinzip wandern sie ins Lager und werden erst beim Verkauf Aufwand."},{"p":"Das ändert das Einkommen, sobald nicht alles verkauft wird. Beispiel aus Übung 10: Material 12.000 € (direkt), Hallenlicht 3.000 € (indirekt), 1.000 Stück hergestellt, 800 verkauft. Marginalprinzip: 12.000 € ins Lager, davon 80 % = 9.600 € Umsatzaufwand, plus 3.000 € sofort. Aufwand 12.600 €. Finalprinzip: 15.000 € ins Lager, davon 80 % = 12.000 € Aufwand. Unterschied: 600 €. Das sind genau die 20 % der 3.000 € indirekten Ausgaben, die beim Finalprinzip noch im Lager stecken."},{"p":"<table class=\"tt\"><tr><th></th><th>Marginalprinzip</th><th>Finalprinzip</th></tr><tr><td>ins Lager</td><td>12.000</td><td>12.000 + 3.000 = 15.000</td></tr><tr><td>Aufwand bei 80 % Verkauf</td><td>9.600 + 3.000 = 12.600</td><td>12.000</td></tr><tr><td>noch im Lager</td><td>2.400</td><td>3.000</td></tr><tr><td>Einkommen</td><td>um 600 niedriger</td><td>um 600 höher</td></tr></table>"},{"f":"bure-f28"},{"tip":"Finalprinzip bedeutet Ermessen: Wie viel Hallenlicht gehört zu einem Stück? Das verschiebt den Zeitpunkt, wann Ausgaben Aufwand werden, und damit das Einkommen des Jahres."},{"h":"Alles zusammen: Karl Gross in 20X1"},{"p":"Jetzt das große Folienbeispiel: 13 Ereignisse, am Ende drei Berichte. ZM steht für Zahlungsmittel, FK für Fremdkapital."},{"p":"<table class=\"tt\"><tr><th>Nr.</th><th>Ereignis</th><th>Buchung</th><th>EK-Wirkung</th></tr><tr><td>1</td><td>Gründung bar 100.000</td><td>ZM +100.000, EK +100.000</td><td>Einlage +100.000</td></tr><tr><td>2</td><td>Grundstück bar 60.000</td><td>ZM −60.000, Grundstück +60.000</td><td>0 (Aktivtausch)</td></tr><tr><td>3</td><td>Büromaterial auf Ziel 3.000</td><td>Material +3.000, FK +3.000</td><td>0</td></tr><tr><td>4</td><td>Gutachten bar 12.000, Material 600 verbraucht</td><td>ZM +12.000, Material −600</td><td>Ertrag +12.000, Aufwand −600</td></tr><tr><td>5</td><td>Dienstleistung auf Ziel 10.000, Material 400</td><td>Forderung +10.000, Material −400</td><td>Ertrag +10.000, Aufwand −400</td></tr><tr><td>6</td><td>Material bar 10.000, Hälfte verkauft für 7.500</td><td>ZM −10.000, Material +10.000; ZM +7.500, Material −5.000</td><td>Ertrag +7.500, Aufwand −5.000</td></tr><tr><td>7</td><td>Miete 4.000, Gehalt 3.000, Sonstiges 2.000 bar</td><td>ZM −9.000</td><td>Aufwand −9.000</td></tr><tr><td>8</td><td>Schuld bar bezahlt 1.000</td><td>ZM −1.000, FK −1.000</td><td>0</td></tr><tr><td>9</td><td>Private Renovierung 30.000</td><td>keine Buchung</td><td>0</td></tr><tr><td>10</td><td>Kunde zahlt 5.000</td><td>ZM +5.000, Forderung −5.000</td><td>0 (Aktivtausch)</td></tr><tr><td>11</td><td>Grundstücksteil (Kauf 30.000) für 40.000 verkauft</td><td>ZM +40.000, Grundstück −30.000</td><td>Ertrag +40.000, Aufwand −30.000</td></tr><tr><td>12</td><td>Darlehen 50.000</td><td>ZM +50.000, FK +50.000</td><td>0</td></tr><tr><td>13</td><td>Darlehen zurück 50.000; Gesellschafter 50.000; Entnahme 15.000</td><td>ZM −50.000, FK −50.000; ZM +50.000; ZM −15.000</td><td>Einlage +50.000, Entnahme −15.000</td></tr></table>"},{"p":"Schau dir Ereignis 6 genau an. Du kaufst Material für 10.000 € und verkaufst die Hälfte für 7.500 €. Der Kauf ist ein Aktivtausch. Beim Verkauf buchst du Ertrag 7.500 € und Aufwand 5.000 €, denn nur die verkaufte Hälfte gehört laut Marktleistungsabgabekonzept zum Verkauf. Die andere Hälfte bleibt mit 5.000 € im Lager. Einkommen aus Ereignis 6: 2.500 €."},{"p":"Ereignis 7 ist das Gegenstück: Miete, Gehalt und Sonstiges haben nichts mit zu verkaufendem Material zu tun. Periodisierungskonzept, also sofort Aufwand 9.000 €. Ereignis 9 wird gar nicht gebucht: Karls Wohnung gehört zur Wirtschaftseinheit „Privatperson Karl Gross“, nicht zur Firma."},{"h":"Die drei Finanzberichte"},{"p":"Am 31.12.20X1 fasst Karl zusammen. Zuerst die Eigenkapitaltransferrechnung: Einlagen 100.000 + 50.000 = 150.000 €, Entnahme 15.000 €, Transfer 135.000 €."},{"f":"bure-f6"},{"p":"Dann die Einkommensrechnung: alle Erträge des Jahres minus alle Aufwendungen. Erträge 69.500 €, Aufwand 45.000 €, Einkommen 24.500 €. Die Dienstleistungen aus Ereignis 4 und 5 ergeben zusammen 22.000 € Ertrag, das Büromaterial daraus 600 + 400 = 1.000 € Aufwand."},{"p":"<table class=\"tt\"><tr><th colspan=\"2\">Einkommensrechnung 20X1</th></tr><tr><td>Ertrag Dienstleistungen</td><td>22.000</td></tr><tr><td>Ertrag Materialverkauf</td><td>7.500</td></tr><tr><td>Ertrag Grundstücksverkauf</td><td>40.000</td></tr><tr><td><b>Erträge</b></td><td><b>69.500</b></td></tr><tr><td>Aufwand Büromaterial</td><td>1.000</td></tr><tr><td>Aufwand Materialverkauf</td><td>5.000</td></tr><tr><td>Aufwand Grundstücksverkauf</td><td>30.000</td></tr><tr><td>Aufwand Miete, Gehalt, Sonstiges</td><td>9.000</td></tr><tr><td><b>Aufwendungen</b></td><td><b>45.000</b></td></tr><tr><td><b>Einkommen</b></td><td><b>24.500</b></td></tr></table>"},{"p":"Zuletzt die <b class=\"term\">Eigenkapitalveränderungsrechnung</b>. Sie verbindet alles: EK am 1.1.20X1: 0 €. Plus Transfer 135.000 €. Plus Einkommen 24.500 €. EK am 31.12.20X1: 159.500 €."},{"f":"bure-f4"},{"v":2},{"ex":1},{"h":"Die Probe: zwei Wege zum Eigenkapital"},{"p":"Kontrolle über die Bilanz: Zahlungsmittel 119.500 + Forderungen 5.000 + Büromaterial 7.000 + Grundstücke 30.000 = 161.500 €. Minus Verbindlichkeiten 2.000 € = 159.500 €. Beide Wege geben dasselbe EK. Genau das ist der Sinn des Systems: Das Foto (Bilanz) und das Video (Bewegungsrechnungen) müssen zusammenpassen."},{"tip":"Klausurtipp: EK kannst du immer auf zwei Wegen rechnen: als Rest in der Bilanz (VG − FK) oder als EK-Anfang + Transfers + Einkommen. Stimmen beide überein, hast du richtig gebucht."}]},{"id":"bure-v2","nr":"2","title":"Modul 2: Doppelte Buchführung","date":"2026-10-28","summary":["<b class=\"term\">Doppelte Buchführung</b>: jedes Ereignis mindestens einmal im <b class=\"term\">Soll</b> und im <b class=\"term\">Haben</b>.","<b class=\"term\">Buchungssatz</b> „Soll an Haben“ kommt ins <b class=\"term\">Journal / Grundbuch</b>, dann ins <b class=\"term\">Hauptbuch</b>.","<b class=\"term\">Saldo</b> = Differenz der Seiten. <b class=\"term\">Vorläufige Saldenaufstellung</b>: Summe Soll = Summe Haben.","<b class=\"term\">Umsatzkostenverfahren</b> und <b class=\"term\">Gesamtkostenverfahren</b>: gleiches Einkommen bei gleichem Zuordnungsprinzip.","<b class=\"fx\" data-f=\"bure-f19\">Zahllast</b> = MwSt − <b class=\"term\">Vorsteuer</b>. <b class=\"term\">Personalausgaben</b> = Brutto + AG-Anteil + Unfallversicherung."],"formulas":["bure-f12","bure-f13","bure-f14","bure-f15","bure-f16","bure-f17","bure-f18","bure-f19","bure-f20","bure-f21","bure-f22","bure-f23","bure-f24","bure-f25","bure-f26","bure-f27"],"visuals":[{"title":"T-Konto mit Saldo","svg":"<svg viewBox=\"0 0 320 184\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"22\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Soll</text><text x=\"160\" y=\"22\" fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">Zahlungsmittel</text><text x=\"300\" y=\"22\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"end\" font-weight=\"700\">Haben</text><line x1=\"15\" y1=\"30\" x2=\"305\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"160\" y1=\"30\" x2=\"160\" y2=\"146\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"20\" y=\"50\" fill=\"currentColor\" font-size=\"11\">Anfangsbestand</text><text x=\"152\" y=\"50\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">100</text><text x=\"20\" y=\"70\" fill=\"currentColor\" font-size=\"11\">20.4. Verkauf</text><text x=\"152\" y=\"70\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">200</text><text x=\"168\" y=\"50\" fill=\"currentColor\" font-size=\"11\">10.4. Einkauf</text><text x=\"300\" y=\"50\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">50</text><text x=\"168\" y=\"70\" fill=\"currentColor\" font-size=\"11\">30.4. Einkauf</text><text x=\"300\" y=\"70\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\">50</text><rect x=\"165\" y=\"77\" width=\"140\" height=\"19\" rx=\"3\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"170\" y=\"91\" fill=\"currentColor\" font-size=\"11\" font-weight=\"700\">Saldo (EB)</text><text x=\"300\" y=\"91\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"end\" font-weight=\"700\">200</text><line x1=\"20\" y1=\"118\" x2=\"152\" y2=\"118\" stroke=\"currentColor\"/><line x1=\"168\" y1=\"118\" x2=\"300\" y2=\"118\" stroke=\"currentColor\"/><text x=\"20\" y=\"136\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Summe</text><text x=\"152\" y=\"136\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"end\" font-weight=\"700\">300</text><text x=\"168\" y=\"136\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Summe</text><text x=\"300\" y=\"136\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"end\" font-weight=\"700\">300</text><text x=\"160\" y=\"170\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\">Saldo = 300 − 100 = 200 (Soll-Saldo)</text></svg>","caption":"Folien 13–15: Soll 300, Haben 100, Soll-Saldo 200 steht zum Ausgleich rechts."},{"title":"Kontenplan als Baum","svg":"<svg viewBox=\"0 0 360 224\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"140\" y=\"10\" width=\"80\" height=\"24\" rx=\"5\" fill=\"var(--acc-soft)\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"180\" y=\"27\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">Bilanz</text><path d=\"M180 34 V43 H85 V52 M180 43 H265 V52\" fill=\"none\" stroke=\"currentColor\"/><rect x=\"20\" y=\"52\" width=\"130\" height=\"24\" rx=\"5\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"85\" y=\"69\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">Vermögen (Aktiva)</text><rect x=\"200\" y=\"52\" width=\"130\" height=\"24\" rx=\"5\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"265\" y=\"69\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">Kapital (Passiva)</text><line x1=\"30\" y1=\"76\" x2=\"30\" y2=\"184\" stroke=\"currentColor\"/><line x1=\"30\" y1=\"94\" x2=\"36\" y2=\"94\" stroke=\"currentColor\"/><text x=\"40\" y=\"98\" fill=\"currentColor\" font-size=\"11\">Grundstücke</text><line x1=\"30\" y1=\"112\" x2=\"36\" y2=\"112\" stroke=\"currentColor\"/><text x=\"40\" y=\"116\" fill=\"currentColor\" font-size=\"11\">Gebäude</text><line x1=\"30\" y1=\"130\" x2=\"36\" y2=\"130\" stroke=\"currentColor\"/><text x=\"40\" y=\"134\" fill=\"currentColor\" font-size=\"11\">Maschinen</text><line x1=\"30\" y1=\"148\" x2=\"36\" y2=\"148\" stroke=\"currentColor\"/><text x=\"40\" y=\"152\" fill=\"currentColor\" font-size=\"11\">Waren, Material</text><line x1=\"30\" y1=\"166\" x2=\"36\" y2=\"166\" stroke=\"currentColor\"/><text x=\"40\" y=\"170\" fill=\"currentColor\" font-size=\"11\">Forderungen</text><line x1=\"30\" y1=\"184\" x2=\"36\" y2=\"184\" stroke=\"currentColor\"/><text x=\"40\" y=\"188\" fill=\"currentColor\" font-size=\"11\">Zahlungsmittel</text><path d=\"M265 76 V86 H212 V96 M265 86 H308 V96\" fill=\"none\" stroke=\"currentColor\"/><rect x=\"166\" y=\"96\" width=\"92\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"currentColor\"/><text x=\"212\" y=\"111\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">Fremdkapital</text><rect x=\"266\" y=\"96\" width=\"84\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"currentColor\"/><text x=\"308\" y=\"111\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">Eigenkapital</text><line x1=\"176\" y1=\"118\" x2=\"176\" y2=\"170\" stroke=\"currentColor\"/><line x1=\"176\" y1=\"134\" x2=\"182\" y2=\"134\" stroke=\"currentColor\"/><text x=\"184\" y=\"138\" fill=\"currentColor\" font-size=\"11\">Verb. (Einkauf)</text><line x1=\"176\" y1=\"152\" x2=\"182\" y2=\"152\" stroke=\"currentColor\"/><text x=\"184\" y=\"156\" fill=\"currentColor\" font-size=\"11\">Verb. (Bank)</text><line x1=\"176\" y1=\"170\" x2=\"182\" y2=\"170\" stroke=\"currentColor\"/><text x=\"184\" y=\"174\" fill=\"currentColor\" font-size=\"11\">Rückstellungen</text><rect x=\"272\" y=\"124\" width=\"78\" height=\"74\" rx=\"4\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><line x1=\"276\" y1=\"118\" x2=\"276\" y2=\"188\" stroke=\"currentColor\"/><line x1=\"276\" y1=\"134\" x2=\"282\" y2=\"134\" stroke=\"currentColor\"/><text x=\"286\" y=\"138\" fill=\"currentColor\" font-size=\"11\">Aufwand</text><line x1=\"276\" y1=\"152\" x2=\"282\" y2=\"152\" stroke=\"currentColor\"/><text x=\"286\" y=\"156\" fill=\"currentColor\" font-size=\"11\">Ertrag</text><line x1=\"276\" y1=\"170\" x2=\"282\" y2=\"170\" stroke=\"currentColor\"/><text x=\"286\" y=\"174\" fill=\"currentColor\" font-size=\"11\">Entnahme</text><line x1=\"276\" y1=\"188\" x2=\"282\" y2=\"188\" stroke=\"currentColor\"/><text x=\"286\" y=\"192\" fill=\"currentColor\" font-size=\"11\">Einlage</text><text x=\"311\" y=\"214\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Unterkonten</text></svg>","caption":"Aufwand, Ertrag, Entnahme und Einlage sind Unterkonten des Eigenkapitals (Folie 18)."},{"title":"Beleg → Buchungssatz → Konten","svg":"<svg viewBox=\"0 0 360 204\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"10\" y=\"30\" width=\"100\" height=\"120\" rx=\"6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"130\" y=\"30\" width=\"100\" height=\"120\" rx=\"6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><rect x=\"250\" y=\"30\" width=\"100\" height=\"120\" rx=\"6\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"60\" y=\"22\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">1 Beleg</text><text x=\"180\" y=\"22\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">2 Buchungssatz</text><text x=\"300\" y=\"22\" fill=\"currentColor\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">3 Konten</text><text x=\"60\" y=\"58\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Kaufvertrag</text><text x=\"60\" y=\"78\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Grundstück</text><text x=\"60\" y=\"98\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">60.000 bar</text><text x=\"60\" y=\"118\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Beleg Nr. 2</text><text x=\"180\" y=\"58\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Grundstücke</text><text x=\"180\" y=\"78\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">an</text><text x=\"180\" y=\"98\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Zahlungsmittel</text><text x=\"180\" y=\"118\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">60.000</text><line x1=\"112\" y1=\"90\" x2=\"122\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"128,90 120,85 120,95\" fill=\"currentColor\"/><line x1=\"232\" y1=\"90\" x2=\"242\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"2\"/><polygon points=\"248,90 240,85 240,95\" fill=\"currentColor\"/><text x=\"300\" y=\"48\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Grundstücke</text><line x1=\"258\" y1=\"53\" x2=\"342\" y2=\"53\" stroke=\"currentColor\"/><line x1=\"300\" y1=\"53\" x2=\"300\" y2=\"82\" stroke=\"currentColor\"/><text x=\"279\" y=\"72\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">60.000</text><text x=\"300\" y=\"102\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Zahlungsmittel</text><line x1=\"258\" y1=\"107\" x2=\"342\" y2=\"107\" stroke=\"currentColor\"/><line x1=\"300\" y1=\"107\" x2=\"300\" y2=\"136\" stroke=\"currentColor\"/><text x=\"321\" y=\"126\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">60.000</text><text x=\"60\" y=\"168\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">relevant?</text><text x=\"180\" y=\"168\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Soll an Haben</text><text x=\"300\" y=\"168\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Soll | Haben</text><text x=\"180\" y=\"192\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Journal: zeitlich · Hauptbuch: nach Konten</text></svg>","caption":"Arbeitsablauf Folie 25 am Beispiel Grundstückskauf 60.000 bar."}],"examples":[{"title":"Grundstück verkauft (Folie 54)","steps":["Verkauf 40.000 bar, Anschaffung 30.000","Zahlungsmittel an Ertrag (Verkauf) 40.000","Aufwand (Verkauf) an Grundstücke 30.000","Einkommen: 40.000 − 30.000 = +10.000"]},{"title":"Umsatzsteuer 10 % (Folie 75)","steps":["Einkauf: 50 + 5 Vorsteuer = 55","Verkauf: 70 + 7 MwSt = 77","Zahllast: \\(7 - 5 = 2\\)"]},{"title":"Personalausgaben (Folie 66)","steps":["Netto: 2.817,00 − 568,86 − 587,32 = 1.660,82","AG-Anteil: 587,32 − 0,9 % · 2.817 = 561,97","Personalausgaben: 2.817 + 561,97 + 20 = 3.398,97"]}],"terms":[{"t":"Konto","sym":"","d":"Hält die finanziellen Folgen aller Ereignisse zu einem Posten fest.","ex":"Zahlungsmittel: 100 + 200 − 50 − 50 = 200.","topic":"bure-konten"},{"t":"T-Konto","sym":"","d":"Konto in T-Form: links Soll, rechts Haben.","ex":"Zahlungsmittel: AB 100 und Zugang 200 links, Abgänge 50 und 50 rechts.","topic":"bure-konten","viz":"<svg viewBox=\"0 0 200 100\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"60\" y=\"18\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">Soll</text><text x=\"140\" y=\"18\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">Haben</text><line x1=\"15\" y1=\"26\" x2=\"185\" y2=\"26\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"100\" y1=\"26\" x2=\"100\" y2=\"90\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"60\" y=\"44\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">AB 100</text><text x=\"60\" y=\"62\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">+200</text><text x=\"140\" y=\"44\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">−50</text><text x=\"140\" y=\"62\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">−50</text><rect x=\"106\" y=\"70\" width=\"70\" height=\"18\" rx=\"3\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"140\" y=\"83\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">Saldo 200</text></svg>"},{"t":"Soll","sym":"","d":"Linke Kontoseite. Englisch Debit.","ex":"Zugang bei Vermögen, Abgang bei Kapital.","topic":"bure-konten"},{"t":"Haben","sym":"","d":"Rechte Kontoseite. Englisch Credit.","ex":"Abgang bei Vermögen, Zugang bei Kapital.","topic":"bure-konten"},{"t":"Doppelte Buchführung","sym":"","d":"Jedes Ereignis berührt mindestens zwei Konten: eins im Soll, eins im Haben.","ex":"Grundstück an Zahlungsmittel 60.000.","topic":"bure-konten"},{"t":"Buchungssatz","sym":"","d":"Anweisung, auf welchen Konten welcher Betrag steht. Form: „Soll an Haben“.","ex":"Zahlungsmittel an Eigenkapital K. Gross 100.000.","topic":"bure-konten"},{"t":"Journal / Grundbuch","sym":"","d":"Alle Buchungssätze in zeitlicher Reihenfolge.","ex":"Beleg a, 1. Mai, Einlage.","topic":"bure-konten"},{"t":"Hauptbuch","sym":"","d":"Alle Buchungen nach Konten sortiert.","ex":"Das T-Konto Zahlungsmittel mit allen Zahlungen.","topic":"bure-konten"},{"t":"Journaleintrag","sym":"","d":"Buchungssatz plus Belegnummer, Datum und Kurzbeschreibung.","ex":"„b, 2. Mai, Kauf Gebäude“.","topic":"bure-konten"},{"t":"Kontenplan","sym":"","d":"Die Konten, die ein bestimmtes Unternehmen führt.","ex":"Liste mit Namen und Gliederung.","topic":"bure-konten"},{"t":"Kontenrahmen","sym":"","d":"Empfehlung, etwa von Verbänden, wie man Konten benennt und ordnet.","ex":"Vorlage, aus der der Kontenplan entsteht.","topic":"bure-konten"},{"t":"Unterkonto","sym":"","d":"Teilkonto, das in ein Oberkonto aufsummiert wird.","ex":"Aufwand (Miete) unter Aufwand. Aufwand, Ertrag, Einlage, Entnahme sind Unterkonten des EK.","topic":"bure-konten"},{"t":"Geschäftsvorfall","sym":"","d":"Relevantes Ereignis mit physischem oder rechtlichem Vorgang. Gebucht mit Beleg.","ex":"Rechnung über Büromaterial 900 auf Ziel.","topic":"bure-konten"},{"t":"Anderes relevantes Ereignis","sym":"","d":"Relevantes Ereignis ohne physischen Vorgang. Beleglose Buchung, Kapitel 5.","ex":"Planmäßige Abschreibung am Jahresende.","topic":"bure-konten"},{"t":"Saldo","sym":"","d":"Differenz aus Soll-Seite und Haben-Seite eines Kontos.","ex":"Soll 100.000, Haben 60.000, Soll-Saldo 40.000.","topic":"bure-konten"},{"t":"Vorläufige Saldenaufstellung","sym":"","d":"Liste aller Kontostände nach den Geschäftsvorfällen. Summe Soll muss Summe Haben sein.","ex":"Karl Gross: 117.500 = 117.500 (Folie 32).","topic":"bure-konten"},{"t":"Korrigierte Saldenaufstellung","sym":"","d":"Vorläufige Liste plus Korrekturen und andere relevante Ereignisse.","ex":"Plus Abschreibung zum Jahresende.","topic":"bure-konten"},{"t":"Storno-Buchung","sym":"","d":"Buchung, die eine falsche Buchung aufhebt. Soll und Haben vertauscht.","ex":"Falsch: Rohstoffe an Verbindlichkeiten 500. Storno: Verbindlichkeiten an Rohstoffe 500.","topic":"bure-konten"},{"t":"Umsatzkostenverfahren","sym":"UKV","d":"Beim Verkauf zwei Buchungen: Ertrag und Aufwand der verkauften Menge.","ex":"Verkauf 7.500, Herstellung 5.000: Forderungen an Ertrag 7.500; Aufwand an Erzeugnisse 5.000.","topic":"bure-ukv"},{"t":"Gesamtkostenverfahren","sym":"GKV","d":"Alle Herstellungsausgaben sofort als Aufwand, beim Verkauf nur die Ertragsbuchung. Am Jahresende Bestandsänderung korrigieren.","ex":"Herstellung 5.000 sofort Aufwand; 80 % verkauft: Lagermehrung 1.000.","topic":"bure-ukv"},{"t":"Umsatzertrag / Umsatzaufwand","sym":"","d":"Ertrag aus dem Verkauf und Aufwand für die verkaufte Menge.","ex":"Verkauf für 2.500, Herstellung 1.699,49 (Folie 69).","topic":"bure-ukv"},{"t":"Lagermehrung / Lagerminderung","sym":"","d":"Mehr oder weniger Erzeugnisse auf Lager als am Anfang.","ex":"1.000 Stück hergestellt, 600 verkauft: 400 bleiben, Lagermehrung.","topic":"bure-ukv"},{"t":"Bruttolohn","sym":"","d":"Vereinbarter Lohn vor Abzügen.","ex":"2.817,00 im Folienbeispiel.","topic":"bure-sonder"},{"t":"Nettolohn","sym":"","d":"Brutto minus Steuern und Arbeitnehmeranteile zur Sozialversicherung.","ex":"1.660,82, ausgezahlt nach vermögenswirksamen Leistungen 1.627,82.","topic":"bure-sonder"},{"t":"Personalausgaben","sym":"","d":"Alles, was der Arbeitgeber zahlt: Brutto plus Arbeitgeberanteile plus Unfallversicherung.","ex":"2.817 + 561,97 + 20 = 3.398,97 (Folie 66).","topic":"bure-sonder"},{"t":"Umsatzsteuer / Mehrwertsteuer","sym":"USt","d":"Steuer auf Umsätze. Der Verkäufer berechnet sie dem Käufer und schuldet sie dem Fiskus.","ex":"Verkauf netto 100 plus 10 % = 110 brutto.","topic":"bure-sonder"},{"t":"Vorsteuer","sym":"VoSt","d":"Gezahlte Umsatzsteuer beim Einkauf. Forderung gegen den Fiskus.","ex":"Einkauf netto 50 plus 5 Vorsteuer.","topic":"bure-sonder"},{"t":"Zahllast","sym":"","d":"Eingenommene Mehrwertsteuer minus Vorsteuer. Geht an den Fiskus.","ex":"7 − 5 = 2 (Folie 75).","topic":"bure-sonder","viz":"<svg viewBox=\"0 0 200 100\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"10\" y1=\"76\" x2=\"190\" y2=\"76\" stroke=\"currentColor\"/><rect x=\"25\" y=\"27\" width=\"30\" height=\"49\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"40\" y=\"23\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">7</text><text x=\"40\" y=\"90\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">MwSt</text><rect x=\"85\" y=\"41\" width=\"30\" height=\"35\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"100\" y=\"37\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">5</text><text x=\"100\" y=\"90\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">VoSt</text><rect x=\"145\" y=\"62\" width=\"30\" height=\"14\" fill=\"var(--acc)\" stroke=\"currentColor\"/><text x=\"160\" y=\"58\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">2</text><text x=\"160\" y=\"90\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Zahllast</text></svg>"},{"t":"Skonto, Bonus, Rabatt","sym":"","d":"Nachlässe für schnelle Zahlung oder große Menge. Ändern den Anschaffungswert.","ex":"2 % Skonto auf 2.000 = 40.","topic":"bure-sonder"},{"t":"Eigenverbrauch","sym":"","d":"Der Unternehmer nimmt Ware für sich. Das ist eine Entnahme, meist mit Umsatzsteuer.","ex":"Inhaber eines Baumarkts nimmt Farbe für sein Haus.","topic":"bure-sonder"}],"time":"10:30–12:00","story":[{"h":"Vom großen Überblick zum Konto"},{"p":"In Modul 1 hast du Ereignisse in eine große Tabelle geschrieben: Vermögensgüter = Fremdkapital + Eigenkapital. Bei 13 Ereignissen geht das. Bei 13.000 nicht. Deshalb bekommt jeder Posten ein eigenes <b class=\"term\">Konto</b>. Es sammelt alle Änderungen zu diesem Posten. Zahlungsmittel, Grundstücke, Verbindlichkeiten, Eigenkapital: jedes ein Konto."},{"p":"Die Bilanz hat drei Postengruppen: links Vermögensgüter („Wofür ist das Geld verwendet worden?“), rechts Eigenkapital und Fremdkapital („Wer hat das Geld gegeben?“). Für die EK-Veränderung kommen vier Gruppen dazu: Aufwand, Ertrag, Entnahme, Einlage."},{"p":"Welche Konten ein Unternehmen genau führt, steht im <b class=\"term\">Kontenplan</b>. Als Vorlage dient ein <b class=\"term\">Kontenrahmen</b>, etwa von Verbänden. Konten bilden einen Baum: Ein <b class=\"term\">Unterkonto</b> wie „Aufwand (Abschreibung Maschine)“ summiert sich ins Oberkonto „Aufwand“. Ganz wichtig: Aufwand, Ertrag, Einlage und Entnahme sind selbst Unterkonten des Eigenkapitals."},{"v":1},{"p":"Relevante Ereignisse gibt es in zwei Arten. Ein <b class=\"term\">Geschäftsvorfall</b> löst einen physischen oder rechtlichen Vorgang aus: Eine Rechnung kommt, Geld fließt. Er wird mit Beleg gebucht. Ein <b class=\"term\">Anderes relevantes Ereignis</b> hat keinen solchen Vorgang, etwa die Abschreibung am Jahresende. Das ist eine beleglose Buchung (Kapitel 5). Modul 2 behandelt nur Geschäftsvorfälle."},{"h":"Das T-Konto und der Saldo"},{"p":"Das Standardkonto ist das <b class=\"term\">T-Konto</b>. Links steht <b class=\"term\">Soll</b> (englisch Debit), rechts <b class=\"term\">Haben</b> (Credit). Die Wörter bedeuten nichts, sie sind nur Namen für die Seiten. Folienbeispiel Zahlungsmittel: Anfangsbestand am 1.4. 100 €, Verkauf am 20.4. +200 €, Einkäufe am 10.4. und 30.4. je 50 €."},{"p":"<table class=\"tt\"><tr><th colspan=\"2\">Soll · Zahlungsmittel</th><th colspan=\"2\">Haben</th></tr><tr><td>1.4. Anfangsbestand</td><td>100</td><td>10.4. Einkauf</td><td>50</td></tr><tr><td>20.4. Verkauf</td><td>200</td><td>30.4. Einkauf</td><td>50</td></tr><tr><td></td><td></td><td><b>Saldo</b></td><td><b>200</b></td></tr><tr><td></td><td><b>300</b></td><td></td><td><b>300</b></td></tr></table>"},{"p":"Der <b class=\"term\">Saldo</b> ist die Differenz der beiden Seiten: 300 − 100 = 200 €. Die Soll-Seite ist größer, also ein Soll-Saldo. Zum Ausgleich schreibst du ihn auf die kleinere Seite, dann sind beide Summen 300. Der Saldo ist der Kontostand für den Finanzbericht."},{"f":"bure-f12"},{"v":0},{"p":"Regel für die Seiten: Vermögenskonten haben Anfangsbestand und Zugänge im Soll, Abgänge im Haben. Kapitalkonten (Fremd- und Eigenkapital) genau umgekehrt: Zugänge im Haben, Abgänge im Soll. Die Unterkonten des EK folgen dem Eigenkapital: Ertrag und Einlage erhöhen das EK, also Zugang im Haben. Aufwand und Entnahme senken das EK, also im Soll."},{"p":"<table class=\"tt\"><tr><th>Konto</th><th>Soll (links)</th><th>Haben (rechts)</th><th>Normaler Saldo</th></tr><tr><td>Vermögen</td><td>+ Zugang</td><td>− Abgang</td><td>Soll</td></tr><tr><td>Fremdkapital, Eigenkapital</td><td>− Abgang</td><td>+ Zugang</td><td>Haben</td></tr><tr><td>Ertrag, Einlage</td><td>−</td><td>+</td><td>Haben</td></tr><tr><td>Aufwand, Entnahme</td><td>+</td><td>−</td><td>Soll</td></tr></table>"},{"f":"bure-f13"},{"tip":"„Soll ist immer plus“ ist FALSCH. Soll ist nur bei Vermögen, Aufwand und Entnahme plus. Bei Kapital, Ertrag und Einlage ist Soll minus."},{"h":"Doppelte Buchführung und der Buchungssatz"},{"p":"Jedes Ereignis trifft mindestens zwei Konten: mindestens eins im Soll, mindestens eins im Haben. Das ist die <b class=\"term\">Doppelte Buchführung</b>. Der Betrag im Soll ist immer gleich dem Betrag im Haben. Die Anweisung dafür heißt <b class=\"term\">Buchungssatz</b>: „Soll-Konto an Haben-Konto Betrag“."},{"f":"bure-f15"},{"p":"Der Arbeitsablauf hat vier Schritte. 1. Analyse: Ist das ein relevantes Ereignis? 2. Kontenbestimmung: Welche Konten sind betroffen? 3. Bilanzgleichung: Zunahme oder Abnahme? 4. Journaleintrag. Ereignis 1: Karl gründet am 1.4. mit 100.000 € bar. Konten: Zahlungsmittel (Vermögen, Zugang, also Soll) und Eigenkapital K. Gross (Kapital, Zugang, also Haben). Buchungssatz: Zahlungsmittel an Eigenkapital K. Gross 100.000 €."},{"p":"Ereignis 2: Grundstück für 60.000 € bar am 2.4. Grundstücke nimmt zu (Soll), Zahlungsmittel nimmt ab (Haben). Buchungssatz: Grundstücke an Zahlungsmittel 60.000 €. Auf den Konten sieht das so aus:"},{"p":"<table class=\"tt\"><tr><th colspan=\"2\">Zahlungsmittel</th><th colspan=\"2\">Grundstücke</th><th colspan=\"2\">EK K. Gross</th></tr><tr><td>(1) 100.000</td><td>(2) 60.000</td><td>(2) 60.000</td><td></td><td></td><td>(1) 100.000</td></tr><tr><td colspan=\"2\">Saldo 40.000 (Soll)</td><td colspan=\"2\">Saldo 60.000 (Soll)</td><td colspan=\"2\">Saldo 100.000 (Haben)</td></tr></table>"},{"v":2},{"h":"Journal und Hauptbuch"},{"p":"Jeder Buchungssatz landet zuerst zeitlich sortiert im <b class=\"term\">Journal / Grundbuch</b>. Ein vollständiger <b class=\"term\">Journaleintrag</b> enthält zusätzlich Belegnummer, Datum und eine Kurzbeschreibung. Danach überträgst du die Beträge auf die Konten im <b class=\"term\">Hauptbuch</b>, dort sachlich nach Konten sortiert."},{"p":"<table class=\"tt\"><tr><th>Beleg</th><th>Datum</th><th>Ereignis und Konten</th><th>Soll</th><th>Haben</th></tr><tr><td>b</td><td>2.4.</td><td>Kauf Grundstück<br>Grundstücke<br>&nbsp;&nbsp;&nbsp;an Zahlungsmittel</td><td><br>60.000<br></td><td><br><br>60.000</td></tr></table>"},{"tip":"Reihenfolge im Buchungssatz: erst das Soll-Konto, dann „an“, dann das Haben-Konto. Nie umgekehrt."},{"h":"Die Saldenaufstellung"},{"p":"Nach allen Geschäftsvorfällen listest du alle Konten mit ihren Salden auf. Das ist die <b class=\"term\">Vorläufige Saldenaufstellung</b>. Zweck: Plausibilität prüfen und eine Checkliste für andere relevante Ereignisse haben. Die Summe aller Soll-Salden muss gleich der Summe aller Haben-Salden sein."},{"f":"bure-f14"},{"p":"<table class=\"tt\"><tr><th>Konto (Ereignisse 1–7)</th><th>Σ Soll</th><th>Σ Haben</th><th>Saldo Soll</th><th>Saldo Haben</th></tr><tr><td>Zahlungsmittel</td><td>119.500</td><td>79.000</td><td>40.500</td><td></td></tr><tr><td>Forderungen</td><td>10.000</td><td>0</td><td>10.000</td><td></td></tr><tr><td>Büromaterial</td><td>13.000</td><td>6.000</td><td>7.000</td><td></td></tr><tr><td>Grundstücke</td><td>60.000</td><td>0</td><td>60.000</td><td></td></tr><tr><td>Verbindlichkeiten</td><td>0</td><td>3.000</td><td></td><td>3.000</td></tr><tr><td>Eigenkapital</td><td>15.000</td><td>129.500</td><td></td><td>114.500</td></tr><tr><td><b>Summe</b></td><td><b>217.500</b></td><td><b>217.500</b></td><td><b>117.500</b></td><td><b>117.500</b></td></tr></table>"},{"p":"Prüfe: 40.500 + 10.000 + 7.000 + 60.000 = 117.500 € und 3.000 + 114.500 = 117.500 €. Passt. Beim Eigenkapital stehen 15.000 € im Soll: alle Aufwendungen bis Ereignis 7. Im Haben 129.500 €: Einlage 100.000 € plus Erträge 29.500 €."},{"h":"Fehler finden: Storno und Korrektur"},{"p":"Stimmen die Summen nicht, liegt ein Fehler auf einem Konto oder im Aufbau der Liste. Einen Fehler auf einem Konto korrigierst du mit einer <b class=\"term\">Storno-Buchung</b>: gleicher Betrag, Soll und Haben vertauscht. Beispiel aus der Verständniskontrolle: Rohstoffe für 50 € auf Ziel, aber gebucht „Rohstoffe an Verbindlichkeiten 500“. Die Saldenaufstellung deckt das nicht auf, denn beide Seiten sind gleich falsch. Storno: Verbindlichkeiten an Rohstoffe 500 €. Dann neu: Rohstoffe an Verbindlichkeiten 50 €."},{"p":"Am Jahresende prüfst du jedes Konto: Kann der Wert so in den Finanzbericht? Oder muss er wegen anderer relevanter Ereignisse geändert werden, etwa durch eine Abschreibung? Mit diesen Buchungen entsteht die <b class=\"term\">Korrigierte Saldenaufstellung</b>. Heute bucht die Software (SAP) solche Abschreibungen meist automatisch, wenn beim Kauf die Nutzungsdauer hinterlegt wurde."},{"tip":"Die Saldenaufstellung findet nur Fehler, bei denen Soll ≠ Haben. Ein falscher Betrag auf beiden Seiten oder ein falsches Konto bleibt unentdeckt."},{"h":"Verkauf buchen: Umsatz- und Gesamtkostenverfahren"},{"p":"Jetzt zu Einnahmen und Ausgaben MIT Eigenkapitalwirkung. Beim Verkauf gilt das Marktleistungsabgabekonzept aus Modul 1: Ertrag beim Verkauf, und der zugehörige Aufwand auch erst beim Verkauf. Bis dahin ist die Herstellung einkommensneutral: Die Erzeugnisse liegen als Vermögensgut im Lager."},{"ex":0},{"p":"Für die Einkommensrechnung gibt es zwei Verfahren. Beim <b class=\"term\">Umsatzkostenverfahren</b> (UKV) buchst du bei jedem Verkauf zwei Sätze: den Ertrag und den Aufwand der verkauften Menge. Die beiden Posten heißen <b class=\"term\">Umsatzertrag / Umsatzaufwand</b>. Beispiel: 100 Stück für 5.000 € hergestellt, 80 Stück für 6.000 € auf Ziel verkauft. Forderungen an Umsatzertrag 6.000 €. Umsatzaufwand an Erzeugnisse 4.000 € (80 % von 5.000). Einkommen 2.000 €. 1.000 € bleiben im Lager."},{"f":"bure-f26"},{"p":"Beim <b class=\"term\">Gesamtkostenverfahren</b> (GKV) buchst du alle Herstellungsausgaben sofort als Aufwand, gegliedert nach Ausgabenarten (Material, Personal). Beim Verkauf gibt es nur einen Satz: Forderungen an Umsatzertrag 6.000 €. Während des Jahres stimmt das Einkommen dann nicht, denn 1.000 € Aufwand gehören zu Erzeugnissen, die noch im Lager liegen. Am Jahresende korrigierst du mit der Bestandsänderung, der <b class=\"term\">Lagermehrung / Lagerminderung</b>. Lagermehrung wirkt wie Ertrag, Lagerminderung wie Aufwand."},{"h":"UKV und GKV im Vergleich"},{"p":"<table class=\"tt\"><tr><th></th><th><b class=\"fx\" data-f=\"bure-f24\">UKV</b></th><th><b class=\"fx\" data-f=\"bure-f25\">GKV</b></th></tr><tr><td>Umsatzertrag</td><td>6.000</td><td>6.000</td></tr><tr><td>Lagermehrung</td><td></td><td>+1.000</td></tr><tr><td>Aufwand</td><td>−4.000 (verkaufte Menge)</td><td>−5.000 (alle Herstellung)</td></tr><tr><td><b>Einkommen</b></td><td><b>2.000</b></td><td><b>2.000</b></td></tr><tr><td>Buchungen pro Verkauf</td><td>2</td><td>1 (+ Korrektur am Ende)</td></tr></table>"},{"f":"bure-f27"},{"p":"Beide Verfahren liefern dasselbe Einkommen. UKV braucht zwei Buchungen pro Verkauf, ist aber jederzeit aussagefähig. GKV braucht nur eine, dafür die Korrekturbuchung am Ende. In Deutschland ist GKV verbreitet (das HGB erlaubt beides), international eher UKV."},{"tip":"Die Höhe des Einkommens hängt NUR vom Zuordnungsprinzip (Marginal oder Final) ab, NICHT vom Verfahren (UKV oder GKV)."},{"h":"Zuordnungsprinzip: Die 60-Prozent-Folien"},{"p":"Die Folien rechnen mit 60 % verkaufter Menge. Direkte Herstellungsausgaben (DAH) gehen immer ins Lager, 60 % davon werden Umsatzaufwand. Beim Marginalprinzip werden die indirekten Herstellungsausgaben (IAH) sofort zu 100 % Aufwand. Beim Finalprinzip gehen auch die IAH ins Lager, nur 60 % davon werden Aufwand, 40 % bleiben liegen. Sonstige Ausgaben (DAS, IAS) sind immer sofort Aufwand."},{"p":"<table class=\"tt\"><tr><th>Lager</th><th>Einkommen Marginal vs. Final</th><th>Grund</th></tr><tr><td>Mehrung (hergestellt &gt; verkauft)</td><td>Marginal kleiner</td><td>40 % der IAH stecken beim Finalprinzip noch im Lager</td></tr><tr><td>Minderung (verkauft &gt; hergestellt)</td><td>Marginal größer</td><td>Finalprinzip holt alte IAH aus dem Lager in den Aufwand</td></tr><tr><td>konstant</td><td>gleich</td><td>alles Hergestellte ist verkauft</td></tr></table>"},{"h":"Exkurs: Personal"},{"p":"Aus Sicht des Arbeitnehmers: Er hat einen <b class=\"term\">Bruttolohn</b>. Der Arbeitgeber behält Lohnsteuer, Soli, Kirchensteuer und die AN-Anteile zur Renten-, Kranken-, Pflege- und Arbeitslosenversicherung ein und führt sie ab. Übrig bleibt der <b class=\"term\">Nettolohn</b>. Folienbeispiel: Brutto 2.817,00 €. An den Fiskus 568,86 € (Lohnsteuer, Soli, Kirchensteuer). An die Sozialversicherung 587,32 € (AN-Anteile). Netto 1.660,82 €. Nach 33,00 € vermögenswirksamen Leistungen werden 1.627,82 € ausgezahlt."},{"f":"bure-f20"},{"p":"Aus Sicht des Arbeitgebers kostet der Mitarbeiter mehr: Brutto plus AG-Anteil zur Sozialversicherung plus Unfallversicherung (Berufsgenossenschaft). Der AG-Anteil ist laut Folie um 0,9 % des Bruttos kleiner als der AN-Anteil: 587,32 − 0,009 · 2.817 = 587,32 − 25,35 = 561,97 € (<b class=\"fx\" data-f=\"bure-f21\">AG-Anteil</b>). Das ergibt die <b class=\"term\">Personalausgaben</b>: 2.817,00 + 561,97 + 20,00 = 3.398,97 €."},{"ex":2},{"f":"bure-f22"},{"p":"Die Buchung hängt wieder vom Zuordnungsprinzip ab. Variante 1, Personal gehört zur Herstellung: Erzeugnisse 3.398,97 € im Soll, im Haben fünf Verbindlichkeiten (Sozialversicherung 1.149,29 = 587,32 + 561,97). Einkommensneutral. Beim Verkauf der Hälfte am 15.9. für 2.500 € auf Ziel: Forderungen an Umsatzertrag 2.500 € und Umsatzaufwand an Erzeugnisse 1.699,49 € (die Hälfte von 3.398,97)."},{"p":"<table class=\"tt\"><tr><th>Datum</th><th>Variante 1 (Herstellung)</th><th>Soll</th><th>Haben</th></tr><tr><td>31.8.</td><td>Erzeugnisse<br>&nbsp;&nbsp;&nbsp;an Verb. Gehalt<br>&nbsp;&nbsp;&nbsp;an Verb. Fiskus<br>&nbsp;&nbsp;&nbsp;an Verb. Sozialvers.<br>&nbsp;&nbsp;&nbsp;an Verb. Berufsgen.<br>&nbsp;&nbsp;&nbsp;an Verb. Anlageinstitut</td><td>3.398,97</td><td><br>1.627,82<br>568,86<br>1.149,29<br>20,00<br>33,00</td></tr><tr><td>15.9.</td><td>Umsatzaufwand an Erzeugnisse</td><td>1.699,49</td><td>1.699,49</td></tr><tr><td>15.9.</td><td>Forderungen an Umsatzertrag</td><td>2.500,00</td><td>2.500,00</td></tr></table>"},{"p":"Variante 2, Personal hat nichts mit der Herstellung zu tun (Periodisierungskonzept): Statt „Erzeugnisse“ steht am 31.8. „Aufwand 3.398,97“ im Soll, sofort einkommenswirksam. Beim Verkauf bleibt nur Forderungen an Umsatzertrag 2.500 €. Das gilt für alle Produktionsfaktoren, nicht nur Personal."},{"h":"Umsatzsteuer"},{"p":"In Deutschland gibt es die <b class=\"term\">Umsatzsteuer / Mehrwertsteuer</b> mit 0 %, 7 % oder 19 %. Die Folien rechnen zur Vereinfachung mit 10 %. Der Verkäufer schlägt sie auf den Preis und schuldet sie dem Fiskus. Der Käufer zahlt sie mit, bekommt sie aber als <b class=\"term\">Vorsteuer</b> zurück, wenn er kein Endverbraucher ist. Schuld (MwSt) minus Forderung (Vorsteuer) ergibt die <b class=\"term\">Zahllast</b>, die du an den Fiskus überweist."},{"ex":1},{"f":"bure-f19"},{"p":"Die Kette: Der Lieferant verkauft Ware für 50 € + 5 € USt = 55 € an das Unternehmen. Das Unternehmen verkauft für 70 € + 7 € = 77 € an den Kunden. Eingenommen 7 €, gezahlt 5 €, Zahllast 2 €. Das sind 10 % auf den geschaffenen Mehrwert von 20 €. Am Ende trägt der Endverbraucher die ganzen 7 €."},{"h":"Umsatzsteuer buchen"},{"p":"Umrechnen: <b class=\"fx\" data-f=\"bure-f16\">Brutto = Netto · 1,1</b> und <b class=\"fx\" data-f=\"bure-f17\">Netto = Brutto / 1,1</b>. Aus 3.300 € brutto werden 3.000 € netto und 300 € <b class=\"fx\" data-f=\"bure-f18\">Steuer</b>. Buchung beim Verkauf (Folie 76): Schallplatten für 50 € hergestellt, auf Ziel für brutto 110 € verkauft, Fracht brutto 5,50 € an den Spediteur."},{"p":"<table class=\"tt\"><tr><th>Geschäftsvorfall und Konten</th><th>Soll</th><th>Haben</th></tr><tr><td>Forderungen (Verkauf)<br>&nbsp;&nbsp;&nbsp;an Ertrag (Verkauf)<br>&nbsp;&nbsp;&nbsp;an Verbindlichkeit (MwSt)</td><td>110,00</td><td><br>100,00<br>10,00</td></tr><tr><td>Aufwand (Schallplatten)<br>Aufwand (Fracht)<br>Forderung (USt)<br>&nbsp;&nbsp;&nbsp;an Ware (Schallplatten)<br>&nbsp;&nbsp;&nbsp;an Verbindlichkeit (Spediteur)</td><td>50,00<br>5,00<br>0,50</td><td><br><br><br>50,00<br>5,50</td></tr><tr><td>Überweisung an Fiskus: Verbindlichkeit (MwSt) an Zahlungsmittel</td><td>9,50</td><td>9,50</td></tr></table>"},{"p":"Die Überweisung an den Fiskus ist 10,00 − 0,50 = 9,50 €. Der Ertrag ist 100 €, nicht 110 €. Die 10 € sind eine Schuld gegenüber dem Fiskus. Ändert sich später der Warenwert, etwa durch eine Rücksendung oder einen Preisnachlass, musst du auch die Umsatzsteuer anpassen."},{"tip":"Der Ertrag ist immer netto. Umsatzsteuer ist nie Ertrag und nie Aufwand, sondern Verbindlichkeit (MwSt) oder Forderung (Vorsteuer) gegenüber dem Fiskus."},{"h":"Skonto, Rabatt, Eigenverbrauch"},{"p":"<b class=\"term\">Skonto, Bonus, Rabatt</b> sind Nachlässe für schnelle Zahlung oder große Mengen. Sie ändern nachträglich den Anschaffungswert der Ware. Beispiel aus der Verständniskontrolle: Ware für 1.000 € am 28.7. gekauft, 3 % Skonto bei Zahlung in 10 Tagen. Zahlung am 6.8.: 1.000 · 0,97 = 970 €. Zahlung am 9.8.: 1.000 €. Ist die Ware beim Nachlass schon verkauft, war der Aufwand schon gebucht. Dann wird der Nachlass einkommenswirksam."},{"f":"bure-f23"},{"p":"<b class=\"term\">Eigenverbrauch</b>: Der Unternehmer nimmt Ware für sich selbst. Das ist eine Entnahme. In der Regel buchst du den Warenwert plus Umsatzsteuer, weil der Unternehmer hier Endverbraucher ist und die Steuer nicht als Vorsteuer zurückbekommt."},{"tip":"Kurzfassung Modul 2: Beleg lesen, Konten bestimmen, Zunahme oder Abnahme klären, „Soll an Haben“ schreiben, ins Journal und auf die Konten. Am Ende Saldenaufstellung: Soll = Haben."}]}],"tasks":[{"id":"bure-t1","topic":"bure-ek","level":1,"type":"open","q":"Ordne zu: Aktiva oder Passiva? Bei Passiva: Fremdkapital oder Eigenkapital?<br/>Zahlungsmittel · Grundstück · Lieferantenschuld · Büromaterial · Forderung an einen Kunden · Kapital des Inhabers · Bankdarlehen · Fertigerzeugnisse","a":"<p class=\"goal\"><b>Ziel:</b> Jeden Posten der richtigen Bilanzseite zuordnen: Aktiva, Fremdkapital oder Eigenkapital.</p>\n<ol class=\"sol-steps\">\n<li>Stell dir zu jedem Posten eine Frage: „Gehört es dem Unternehmen?“ Dann Aktiva. „Schuldet das Unternehmen es jemandem?“ Dann Passiva.<span class=\"why\">Warum: Aktiva sind das Vermögen, also alles, was das Unternehmen hat oder noch bekommt. Passiva zeigen, woher das Geld dafür kam: von Fremden (Fremdkapital) oder vom Inhaber (Eigenkapital).</span></li>\n<li>Zahlungsmittel, Grundstück, Büromaterial, Fertigerzeugnisse → <b>Aktiva</b>.<span class=\"why\">Warum: Das sind Dinge, die dem Unternehmen gehören: Geld, Boden, Material im Schrank und fertige Produkte im Lager.</span></li>\n<li>Forderung an einen Kunden → <b>Aktiva</b>.<span class=\"why\">Warum: Eine Forderung ist ein Recht auf Geld: Der Kunde schuldet uns etwas. Das ist Vermögen, auch wenn das Geld noch nicht auf dem Konto ist.</span></li>\n<li>Lieferantenschuld, Bankdarlehen → <b>Passiva, Fremdkapital</b>.<span class=\"why\">Warum: Hier schuldet das Unternehmen Geld an Fremde (Lieferant, Bank). Fremdkapital heißt: Geld von außen, das zurückgezahlt werden muss.</span></li>\n<li>Kapital des Inhabers → <b>Passiva, Eigenkapital</b>.<span class=\"why\">Warum: Dieses Geld kommt vom Eigentümer selbst. Im Alltag ist das Eigenkapital der Teil, der dem Inhaber gehört: Vermögen minus Schulden.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Bilanzgleichung Aktiva = Fremdkapital + Eigenkapital. Jeder Posten steht genau auf einer Seite, keiner doppelt.</p>\n<p class=\"merke\"><b>Merke:</b> Forderung heißt „jemand schuldet uns etwas“ (Aktiva), Verbindlichkeit heißt „wir schulden jemandem etwas“ (Passiva). <i>(Skript: Folie 27, Modul 2 Folie 7)</i></p>","short":"Aktiva: ZM, Grundstück, Büromaterial, Forderung, Fertigerzeugnisse · FK: Lieferantenschuld, Bankdarlehen · EK: Kapital des Inhabers","diag":false,"src":"eigene"},{"id":"bure-t2","topic":"bure-ek","level":1,"type":"open","q":"Ein Bauunternehmen hat am 31.12.: Grundstück {{Gr}}, Fahrzeuge {{Fz}}, Material {{M}}, Forderungen {{Fo}}, Zahlungsmittel {{Z}}. Es schuldet der Bank {{B}} und Lieferanten {{L}}. Wie hoch ist das Eigenkapital? Stelle die Bilanz auf.","a":"<p class=\"goal\"><b>Ziel:</b> Aus Vermögen und Schulden das Eigenkapital berechnen und die Bilanz aufstellen.</p>\n<ol class=\"sol-steps\">\n<li>Bilanzgleichung: \\(\\text{Vermögen} = \\text{Fremdkapital} + \\text{Eigenkapital}\\). Umgestellt: \\(\\text{EK} = \\text{Vermögen} - \\text{FK}\\).<span class=\"why\">Warum: Alles Vermögen wurde entweder mit fremdem oder mit eigenem Geld bezahlt. Ziehst du auf beiden Seiten das FK ab, steht das EK allein da.</span></li>\n<li>Vermögen Schritt für Schritt addieren: {{Gr}} + {{Fz}} = {{Gr+Fz}}; + {{M}} = {{Gr+Fz+M}}; + {{Fo}} = {{Gr+Fz+M+Fo}}; + {{Z}} = <b>{{V}}</b>.<span class=\"why\">Warum: Zum Vermögen zählen Grundstück, Fahrzeuge, Material, Forderungen (Kunden schulden uns Geld) und Zahlungsmittel. Einzeln addieren, damit kein Posten verloren geht.</span></li>\n<li>Fremdkapital: {{B}} + {{L}} = <b>{{FK}}</b>.<span class=\"why\">Warum: Bank und Lieferanten sind Fremde, denen das Unternehmen Geld schuldet.</span></li>\n<li>Eigenkapital: {{V}} − {{FK}} = <b>{{EK}}</b>.<span class=\"why\">Warum: Im Alltag heißt das: Würde man alles verkaufen und alle Schulden bezahlen, blieben {{EK}} für den Inhaber übrig.</span></li>\n<li><table class=\"tt\"><tr><th colspan=\"2\">Aktiva</th><th colspan=\"2\">Passiva</th></tr><tr><td>Grundstück</td><td>{{Gr}}</td><td>Eigenkapital</td><td>{{EK}}</td></tr><tr><td>Fahrzeuge</td><td>{{Fz}}</td><td>Bankdarlehen</td><td>{{B}}</td></tr><tr><td>Material</td><td>{{M}}</td><td>Verbindlichkeiten Lieferanten</td><td>{{L}}</td></tr><tr><td>Forderungen</td><td>{{Fo}}</td><td></td><td></td></tr><tr><td>Zahlungsmittel</td><td>{{Z}}</td><td></td><td></td></tr><tr><th>Summe</th><th>{{V}}</th><th>Summe</th><th>{{V}}</th></tr></table><span class=\"why\">Warum: Links steht, was das Unternehmen hat (Aktiva). Rechts steht, woher das Geld kommt (Passiva). Die Summe heißt Bilanzsumme.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Passiva: {{EK}} + {{B}} = {{EK+B}}; + {{L}} = {{V}}. Das ist genau die Summe der Aktiva. Links = rechts, also stimmt es.</p>\n<p class=\"merke\"><b>Merke:</b> Die Bilanz geht immer auf, weil das Eigenkapital genau die Lücke zwischen Vermögen und Schulden ist.</p>","short":"EK {{EK}}; Bilanzsumme {{V}}","diag":false,"src":"eigene","gen":{"vars":{"Gr":{"min":80000,"max":200000,"step":5000},"Fz":{"min":20000,"max":60000,"step":1000},"M":{"min":2000,"max":8000,"step":100},"Fo":{"min":3000,"max":12000,"step":50},"Z":{"min":5000,"max":30000,"step":500},"B":{"min":50000,"max":150000,"step":5000},"L":{"min":5000,"max":20000,"step":250}},"let":{"V":"Gr+Fz+M+Fo+Z","FK":"B+L","EK":"V-FK"},"check":"EK >= 10000"}},{"id":"bure-t3","topic":"bure-zwecke","level":1,"type":"open","q":"Welcher Finanzbericht ist ein „Schnappschuss“, welche sind eine „Videoaufnahme“? Ordne Bilanz, Einkommensrechnung, Eigenkapitaltransferrechnung und Eigenkapitalveränderungsrechnung zu. Was ist Bestands-, was Bewegungsrechnung?","a":"<p class=\"goal\"><b>Ziel:</b> Die vier Finanzberichte nach Zeitpunkt oder Zeitraum sortieren.</p>\n<ol class=\"sol-steps\">\n<li><b>Bilanz</b>: Zeitpunkt, „Schnappschuss“, Bestandsrechnung.<span class=\"why\">Warum: Die Bilanz zeigt, was an einem Stichtag (z. B. 31.12.) da ist, wie ein Foto. „Bestand“ heißt: Wie viel liegt gerade vor?</span></li>\n<li><b>Einkommensrechnung</b>: Zeitraum, „Videoaufnahme“, Bewegungsrechnung.<span class=\"why\">Warum: Sie sammelt alle Erträge und Aufwendungen eines Jahres. „Bewegung“ heißt: Was hat sich in dieser Zeit verändert?</span></li>\n<li><b>Eigenkapitaltransferrechnung</b>: Zeitraum, Bewegungsrechnung.<span class=\"why\">Warum: Sie zählt Einlagen und Entnahmen des Inhabers im ganzen Jahr.</span></li>\n<li><b>Eigenkapitalveränderungsrechnung</b>: Zeitraum, Bewegungsrechnung.<span class=\"why\">Warum: Sie rechnet EK am Anfang + Einkommen + Transfers = EK am Ende. Sie verbindet also zwei Fotos durch das Video dazwischen.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Kannst du „am 31.12.“ davor setzen, ist es ein Bestand (Bilanz). Passt „im Jahr 20X1“, ist es eine Bewegung (die anderen drei).</p>\n<p class=\"merke\"><b>Merke:</b> Ein Foto (Bilanz), drei Videos (Einkommens-, Transfer- und Veränderungsrechnung). <i>(Skript: Folie 64, Frage 3; Folie 18)</i></p>","short":"Bilanz = Bestandsrechnung; die drei anderen = Bewegungsrechnungen","diag":false,"src":"eigene"},{"id":"bure-t4","topic":"bure-ek","level":1,"type":"open","q":"Bestimme für jedes Ereignis die Art der Bilanzveränderung und ob das Eigenkapital betroffen ist.<br/> a) Grundstück für {{A}} bar gekauft. b) Material für {{Mb}} auf Ziel. c) Lieferantenschuld {{Mc}} per Überweisung bezahlt. d) Lieferantenschuld {{Md}} wird in ein Bankdarlehen umgewandelt. e) Kunde zahlt Forderung {{Me}} bar. f) Inhaber legt {{Mf}} bar ein. g) Miete {{Mg}} bar. h) Inhaber entnimmt {{Mh}} bar.","a":"<p class=\"goal\"><b>Ziel:</b> Für jedes Ereignis die Art der Bilanzveränderung bestimmen und prüfen, ob sich das Eigenkapital ändert.</p>\n<ol class=\"sol-steps\">\n<li>Die vier Arten: <b>Aktivtausch</b> (ein Aktivposten +, ein anderer −), <b>Passivtausch</b> (ein Passivposten +, ein anderer −), <b>Bilanzverlängerung</b> (beide Seiten +), <b>Bilanzverkürzung</b> (beide Seiten −).<span class=\"why\">Warum: Jedes Ereignis ändert mindestens zwei Stellen, damit Aktiva = Passiva bleibt. Ändert sich dabei das EK, sagt man „mit EK-Wirkung“.</span></li>\n<li>a) Grundstück +{{A}}, Zahlungsmittel −{{A}} → Aktivtausch, Bilanzsumme gleich, EK nein.<span class=\"why\">Warum: Geld wird zu Boden. Beides ist Vermögen auf der Aktivseite, also wird nur getauscht.</span></li>\n<li>b) Material +{{Mb}}, Verbindlichkeiten +{{Mb}} → Bilanzverlängerung +{{Mb}}, EK nein.<span class=\"why\">Warum: „Auf Ziel“ heißt: später bezahlen. Es entsteht eine Schuld (Fremdkapital). Links und rechts kommt gleich viel dazu.</span></li>\n<li>c) Verbindlichkeiten −{{Mc}}, Zahlungsmittel −{{Mc}} → Bilanzverkürzung −{{Mc}}, EK nein.<span class=\"why\">Warum: Die Schuld wird bezahlt: Das Geld ist weg und die Schuld auch. Beide Seiten werden kleiner.</span></li>\n<li>d) Lieferantenschuld −{{Md}}, Bankdarlehen +{{Md}} → Passivtausch, Bilanzsumme gleich, EK nein.<span class=\"why\">Warum: Es wechselt nur, wem man das Geld schuldet. Beides ist Fremdkapital.</span></li>\n<li>e) Zahlungsmittel +{{Me}}, Forderungen −{{Me}} → Aktivtausch, EK nein.<span class=\"why\">Warum: Das Recht auf Geld (Forderung) wird zu echtem Geld. Beides ist Vermögen.</span></li>\n<li>f) Zahlungsmittel +{{Mf}}, EK +{{Mf}} → Bilanzverlängerung mit EK-Wirkung (Einlage).<span class=\"why\">Warum: Der Inhaber gibt eigenes Geld in die Firma. Das ist ein Transfer, kein Verdienst.</span></li>\n<li>g) Zahlungsmittel −{{Mg}}, EK −{{Mg}} → Bilanzverkürzung mit EK-Wirkung (Aufwand).<span class=\"why\">Warum: Die Miete ist verbraucht, dafür bleibt nichts im Vermögen. Aufwand macht die Firma ärmer und senkt so das EK.</span></li>\n<li>h) Zahlungsmittel −{{Mh}}, EK −{{Mh}} → Bilanzverkürzung mit EK-Wirkung (Entnahme).<span class=\"why\">Warum: Der Inhaber nimmt Geld für sich privat. Das ist ein Transfer, kein Aufwand.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>Art</th><th>Bilanzsumme</th><th>EK</th></tr><tr><td>a</td><td>Aktivtausch</td><td>gleich</td><td>nein</td></tr><tr><td>b</td><td>Bilanzverlängerung ohne EK-Wirkung</td><td>+{{Mb}}</td><td>nein</td></tr><tr><td>c</td><td>Bilanzverkürzung ohne EK-Wirkung</td><td>−{{Mc}}</td><td>nein</td></tr><tr><td>d</td><td>Passivtausch ohne EK-Wirkung</td><td>gleich</td><td>nein</td></tr><tr><td>e</td><td>Aktivtausch</td><td>gleich</td><td>nein</td></tr><tr><td>f</td><td>Bilanzverlängerung mit EK-Wirkung (Transfer: Einlage)</td><td>+{{Mf}}</td><td>+{{Mf}}</td></tr><tr><td>g</td><td>Bilanzverkürzung mit EK-Wirkung (Einkommen: Aufwand)</td><td>−{{Mg}}</td><td>−{{Mg}}</td></tr><tr><td>h</td><td>Bilanzverkürzung mit EK-Wirkung (Transfer: Entnahme)</td><td>−{{Mh}}</td><td>−{{Mh}}</td></tr></table><span class=\"why\">Warum: Die Tabelle fasst alles zusammen, so wie es in der Klausur verlangt wird.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> In jeder Zeile ändern sich Aktiva und Passiva um denselben Betrag, z. B. f): Aktiva +{{Mf}}, Passiva +{{Mf}}.</p>\n<p class=\"merke\"><b>Merke:</b> Das EK ändert sich nur durch Einkommen (Ertrag, Aufwand) oder Transfers (Einlage, Entnahme), nie durch Tausch, Kredit oder Tilgung. <i>(Übungsskript: Aufgabe 2.2 (S. 9) und 3.2 (S. 20))</i></p>","short":"a, e Aktivtausch · b Verlängerung · c Verkürzung · d Passivtausch · f +{{Mf}}, g −{{Mg}}, h −{{Mh}} EK","diag":false,"src":"eigene","gen":{"vars":{"A":{"min":20000,"max":90000,"step":5000},"Mb":{"min":1000,"max":6000,"step":500},"Mc":{"min":500,"max":4000,"step":100},"Md":{"min":5000,"max":20000,"step":1000},"Me":{"min":500,"max":3000,"step":100},"Mf":{"min":2000,"max":10000,"step":500},"Mg":{"min":400,"max":1500,"step":50},"Mh":{"min":500,"max":2500,"step":100}}}},{"id":"bure-t5","topic":"bure-zwecke","level":2,"type":"open","q":"Ist der Vorgang eine Einzahlung, eine Einnahme, ein Ertrag? Je Spalte ja oder nein.<br/> a) Barverkauf von Ware für {{V}} (Einkauf {{K}}). b) Verkauf einer Dienstleistung für {{D}} auf Ziel. c) Kunde aus b) zahlt {{D}}. d) Bankdarlehen {{Dar}} ausgezahlt. e) Inhaber legt {{Ein}} bar ein.","a":"<p class=\"goal\"><b>Ziel:</b> Für jeden Vorgang prüfen, ob er Einzahlung, Einnahme und Ertrag ist.</p>\n<ol class=\"sol-steps\">\n<li>Die drei Begriffe: <b>Einzahlung</b> = Zahlungsmittel steigen. <b>Einnahme</b> = Geldvermögen steigt, mit \\(\\text{Geldvermögen} = \\text{Zahlungsmittel} + \\text{Forderungen} - \\text{Verbindlichkeiten}\\). <b>Ertrag</b> = das EK steigt durch eine Leistung.<span class=\"why\">Warum: Einzahlung fragt: Ist mehr Bargeld da? Einnahme fragt: Bin ich unterm Strich geldmäßig reicher, auch wenn der Kunde erst später zahlt? Ertrag fragt: Habe ich etwas verdient?</span></li>\n<li>a) Barverkauf {{V}}: Zahlungsmittel +{{V}} → Einzahlung ja. Geldvermögen +{{V}} → Einnahme ja. Ware verkauft → Ertrag ja {{V}}. Dazu Aufwand {{K}} für die Ware, Einkommen {{V}} − {{K}} = {{V-K}}.<span class=\"why\">Warum: Geld fließt sofort, und die Leistung (Ware) geht an den Kunden. Die verkaufte Ware fehlt im Lager, das ist der Aufwand.</span></li>\n<li>b) Verkauf auf Ziel {{D}}: Zahlungsmittel 0 → Einzahlung nein. Forderung +{{D}} → Einnahme ja. Leistung erbracht → Ertrag ja.<span class=\"why\">Warum: Es kommt noch kein Geld, aber der Kunde schuldet uns {{D}}. Das erhöht das Geldvermögen.</span></li>\n<li>c) Kunde zahlt {{D}}: Zahlungsmittel +{{D}} → Einzahlung ja. Geldvermögen +{{D}} − {{D}} = 0 → Einnahme nein. Ertrag nein.<span class=\"why\">Warum: Die Forderung wird nur zu Geld. Verdient wurde schon in b), deshalb kein zweiter Ertrag.</span></li>\n<li>d) Darlehen {{Dar}}: Zahlungsmittel +{{Dar}} → Einzahlung ja. Geldvermögen +{{Dar}} − {{Dar}} = 0 → Einnahme nein. Ertrag nein.<span class=\"why\">Warum: Geliehenes Geld muss zurück. Die Schuld steigt genau so stark wie das Geld.</span></li>\n<li>e) Einlage {{Ein}}: Zahlungsmittel +{{Ein}} → Einzahlung ja. Geldvermögen +{{Ein}} → Einnahme ja. Ertrag nein.<span class=\"why\">Warum: Das Geld kommt vom Inhaber selbst. Es ist ein Transfer, kein Verdienst.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>Einzahlung</th><th>Einnahme</th><th>Ertrag</th></tr><tr><td>a</td><td>ja {{V}}</td><td>ja {{V}}</td><td>ja {{V}}</td></tr><tr><td>b</td><td>nein</td><td>ja {{D}}</td><td>ja {{D}}</td></tr><tr><td>c</td><td>ja {{D}}</td><td>nein</td><td>nein</td></tr><tr><td>d</td><td>ja {{Dar}}</td><td>nein</td><td>nein</td></tr><tr><td>e</td><td>ja {{Ein}}</td><td>ja {{Ein}}</td><td>nein</td></tr></table><span class=\"why\">Warum: So sieht die Lösung als Tabelle aus.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Rechne in jeder Zeile das Geldvermögen nach, z. B. c): Zahlungsmittel +{{D}}, Forderung −{{D}}, zusammen 0, also keine Einnahme.</p>\n<p class=\"merke\"><b>Merke:</b> Bargeld rein heißt noch nicht verdient: Kundenzahlung, Kredit und Einlage sind Einzahlungen, aber kein Ertrag. <i>(Skript: Folien 13–15; Übungsskript 1.4 (S. 5))</i></p>","short":"a ja/ja/ja · b nein/ja/ja · c ja/nein/nein · d ja/nein/nein · e ja/ja/nein","diag":false,"src":"eigene","gen":{"vars":{"V":{"min":500,"max":3000,"step":100},"K":{"min":300,"max":2000,"step":50},"D":{"min":1000,"max":5000,"step":100},"Dar":{"min":2000,"max":10000,"step":500},"Ein":{"min":1000,"max":5000,"step":500}},"check":"K < V"}},{"id":"bure-t6","topic":"bure-ek","level":2,"type":"open","q":"a) Eigenkapital am 1.1.: {{EK0}}. Im Jahr: Einlagen {{Ei}}, Entnahmen {{En}}, Erträge {{Er}}, Aufwendungen {{Au}}. Berechne Einkommen, Transfer-Saldo und EK am 31.12.<br/> b) Im Folgejahr sinkt das EK von {{EK1}} auf {{EK2}}. Es gab nur Entnahmen von {{En2}}. Wie hoch war das Einkommen?","a":"<p class=\"goal\"><b>Ziel:</b> Einkommen, Transfer und Eigenkapital am Jahresende berechnen und in b) das Einkommen rückwärts bestimmen.</p>\n<ol class=\"sol-steps\">\n<li>a) Einkommen = Erträge − Aufwendungen = {{Er}} − {{Au}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Einkommen ist im Alltag der Gewinn: um so viel ist die Firma durch ihre Arbeit reicher geworden.</span></li>\n<li>Transfer = Einlagen − Entnahmen = {{Ei}} − {{En}} = <b>{{Ts}}</b>.<span class=\"why\">Warum: Transfers sind Geldflüsse zwischen Inhaber und Firma. Sie ändern das EK, sind aber nicht verdient.</span></li>\n<li>EK am Ende = EK am Anfang + Einkommen + Transfer = {{EK0}} + {{Y}} + ({{Ts}}) = <b>{{EK1}}</b>.<span class=\"why\">Warum: Das ist die Eigenkapitalveränderungsrechnung. Das EK ändert sich nur durch diese zwei Dinge.</span></li>\n<li>Veränderung: {{EK1}} − {{EK0}} = {{dEs}}.<span class=\"why\">Warum: Endbestand minus Anfangsbestand zeigt, um wie viel das EK im Jahr gewachsen oder geschrumpft ist.</span></li>\n<li>b) Dieselbe Formel mit den neuen Zahlen: {{EK1}} + Einkommen − {{En2}} = {{EK2}}.<span class=\"why\">Warum: Es gab nur Entnahmen, also ist der Transfer −{{En2}}. Unbekannt ist nur das Einkommen.</span></li>\n<li>Umstellen: Einkommen = {{EK2}} − {{EK1}} + {{En2}}.<span class=\"why\">Warum: Was links mit + steht ({{EK1}}), kommt rechts mit − hin. Was links mit − steht ({{En2}}), kommt rechts mit + hin. So bleibt die Gleichung im Gleichgewicht.</span></li>\n<li>Rechnen: {{EK2}} − {{EK1}} = −{{Dr}}; −{{Dr}} + {{En2}} = <b>{{Y2}}</b>.<span class=\"why\">Warum: Das EK sank nur um {{Dr}}, obwohl {{En2}} entnommen wurden. Den Rest hat der Gewinn ausgeglichen.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> b) {{EK1}} + {{Y2}} − {{En2}} = {{EK1+Y2}} − {{En2}} = {{EK2}}. Passt.</p>\n<p class=\"merke\"><b>Merke:</b> Das EK kann sinken, obwohl die Firma Gewinn macht, wenn der Inhaber mehr entnimmt als verdient wird. <i>(Skript: Folie 17; Folien 59–61)</i></p>","short":"a) Einkommen {{Y}}, Transfer {{Ts}}, EK {{EK1}} · b) Einkommen {{Y2}}","diag":false,"src":"eigene","gen":{"vars":{"EK0":{"min":30000,"max":60000,"step":1000},"Ei":{"min":2000,"max":10000,"step":500},"En":{"min":3000,"max":15000,"step":500},"Er":{"min":50000,"max":90000,"step":100},"Au":{"min":40000,"max":80000,"step":100},"Dr":{"min":1000,"max":8000,"step":200},"En2":{"min":8000,"max":20000,"step":500}},"let":{"Y":"Er-Au","T":"Ei-En","EK1":"EK0+Ei+Er-En-Au","dE":"EK1-EK0","EK2":"EK1-Dr","Y2":"En2-Dr","Ts":"(T<0?'−':'+')+num(abs(T))","dEs":"(dE<0?'−':'+')+num(abs(dE))"},"check":"Y > 0 && T != 0 && dE != 0 && Y2 > 0"}},{"id":"bure-t7","topic":"bure-konzepte","level":2,"type":"open","q":"Welches Konzept bestimmt den Zeitpunkt der Einkommenswirkung? Marktleistungsabgabe, Periodisierung oder Einkommensvorwegnahme?<br/> a) {{n}} Betonfertigteile für {{V}} verkauft, direkte Herstellungsausgaben {{H}}. b) Zinsen für einen Überbrückungskredit überwiesen. c) Ein Gericht wird das Unternehmen absehbar zu {{S}} Schadensersatz verurteilen. d) Zeitungsanzeige bezahlt. e) Gehalt des Vertriebsleiters überwiesen. f) Fertigteile für {{F}} hergestellt, noch nicht verkauft.","a":"<p class=\"goal\"><b>Ziel:</b> Für jedes Ereignis bestimmen, welches Konzept festlegt, wann es das Einkommen ändert.</p>\n<ol class=\"sol-steps\">\n<li>Die drei Konzepte: <b>Marktleistungsabgabe</b> = Ertrag und zugehöriger Aufwand zählen, wenn die Leistung an den Kunden geht. <b>Periodisierung</b> = Aufwand ohne Bezug zu einem Produkt zählt in der Zeit, in der er anfällt. <b>Einkommensvorwegnahme</b> = absehbare Verluste zählen schon jetzt.<span class=\"why\">Warum: Faustregel: Gehört es zu einem verkauften Produkt? Dann Marktleistungsabgabe. Droht ein sicherer Verlust? Dann Vorwegnahme. Sonst Periodisierung.</span></li>\n<li>a) Marktleistungsabgabe: Ertrag {{V}}, Aufwand {{H}}, Einkommen {{V}} − {{H}} = <b>{{V-H}}</b>.<span class=\"why\">Warum: Die direkten Herstellungsausgaben gehören genau zu den verkauften Fertigteilen. Sie werden Aufwand, wenn die Teile verkauft sind.</span></li>\n<li>b) Periodisierung: Zinsen sofort Aufwand.<span class=\"why\">Warum: Zinsen gehören zu keinem bestimmten Produkt, sondern zur Zeit, in der der Kredit läuft.</span></li>\n<li>c) Einkommensvorwegnahme: Aufwand {{S}} schon jetzt.<span class=\"why\">Warum: Aus Vorsicht zeigt man einen absehbaren Verlust sofort und versteckt ihn nicht bis zur Zahlung.</span></li>\n<li>d) Periodisierung (Anzeige) und e) Periodisierung (Gehalt Vertriebsleiter).<span class=\"why\">Warum: Werbung und Vertrieb lassen sich keinem einzelnen Fertigteil zuordnen. Sie gehören zur laufenden Zeit.</span></li>\n<li>f) Noch keine Einkommenswirkung: Erzeugnisbestand {{F}} im Lager.<span class=\"why\">Warum: Herstellen allein macht nicht reicher. Geld wird nur zu Produkten (Aktivtausch). Erst beim Verkauf wirkt es (Marktleistungsabgabe).</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Zu jedem Fall die Faustregel aus Schritt 1 fragen. Jeder Fall passt zu genau einem Konzept.</p>\n<p class=\"merke\"><b>Merke:</b> Herstellen ist einkommensneutral; einkommenswirksam wird es erst beim Verkauf. <i>(Skript: Folien 28–32; Übungsskript 2.1 Teil 2 (S. 7))</i></p>","short":"a Marktleistungsabgabe · b, d, e Periodisierung · c Vorwegnahme · f noch keine Wirkung","diag":false,"src":"eigene","gen":{"vars":{"n":[100,150,200,250,300],"V":{"min":10000,"max":50000,"step":1000},"H":{"min":5000,"max":40000,"step":1000},"S":{"min":5000,"max":20000,"step":1000},"F":{"min":2000,"max":10000,"step":500}},"check":"H < V"}},{"id":"bure-t8","topic":"bure-ek","level":2,"type":"open","q":"Anfangsbestand: Zahlungsmittel {{Z0}}, Material {{M0}}, Fremdkapital {{F0}}, Eigenkapital {{E0}}. Bilde in einer Übersicht wie auf den Folien ab:<br/> (1) Material für {{m}} bar. (2) Fremdkapital {{r}} bar zurückgezahlt. (3) Dienstleistung für {{s}} bar, dabei Material {{u}} verbraucht. (4) Einlage {{e}} bar.","a":"<p class=\"goal\"><b>Ziel:</b> Die Ereignisse in der Bilanzgleichung abbilden und die Endbestände berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Anfangs-EK: {{Z0}} + {{M0}} − {{F0}} = <b>{{E0}}</b>.<span class=\"why\">Warum: EK = Vermögen − Schulden. Vermögen sind Zahlungsmittel und Material.</span></li>\n<li>(1) Zahlungsmittel −{{m}}, Material +{{m}} → Aktivtausch.<span class=\"why\">Warum: Geld wird zu Material, beides ist Vermögen. Das EK bleibt gleich.</span></li>\n<li>(2) Zahlungsmittel −{{r}}, FK −{{r}} → Verkürzung ohne EK.<span class=\"why\">Warum: Schuld zurückzahlen macht nicht ärmer: Geld und Schuld sinken gleich stark.</span></li>\n<li>(3a) Zahlungsmittel +{{s}}, EK +{{s}} → Ertrag. (3b) Material −{{u}}, EK −{{u}} → Aufwand.<span class=\"why\">Warum: Die Dienstleistung bringt Geld, das ist verdient (Ertrag). Das verbrauchte Material ist weg, das macht ärmer (Aufwand).</span></li>\n<li>(4) Zahlungsmittel +{{e}}, EK +{{e}} → Einlage.<span class=\"why\">Warum: Der Inhaber gibt eigenes Geld dazu, ein Transfer.</span></li>\n<li>Endbestände Spalte für Spalte: ZM {{Z0}} − {{m}} − {{r}} + {{s}} + {{e}} = <b>{{Z1}}</b>. Material {{M0}} + {{m}} − {{u}} = <b>{{M1}}</b>. FK {{F0}} − {{r}} = <b>{{F1}}</b>. EK {{E0}} + {{s}} − {{u}} + {{e}} = <b>{{E1}}</b>.<span class=\"why\">Warum: Endbestand = Anfangsbestand + alle Zugänge − alle Abgänge in dieser Spalte.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>ZM</th><th>Material</th><th>=</th><th>FK</th><th>EK</th><th>Art</th></tr><tr><td>AB</td><td>{{Z0}}</td><td>{{M0}}</td><td>=</td><td>{{F0}}</td><td>{{E0}}</td><td></td></tr><tr><td>(1)</td><td>−{{m}}</td><td>+{{m}}</td><td></td><td></td><td></td><td>Aktivtausch</td></tr><tr><td>(2)</td><td>−{{r}}</td><td></td><td></td><td>−{{r}}</td><td></td><td>Verkürzung ohne EK</td></tr><tr><td>(3a)</td><td>+{{s}}</td><td></td><td></td><td></td><td>+{{s}}</td><td>Ertrag</td></tr><tr><td>(3b)</td><td></td><td>−{{u}}</td><td></td><td></td><td>−{{u}}</td><td>Aufwand</td></tr><tr><td>(4)</td><td>+{{e}}</td><td></td><td></td><td></td><td>+{{e}}</td><td>Einlage</td></tr><tr><th>EB</th><th>{{Z1}}</th><th>{{M1}}</th><th>=</th><th>{{F1}}</th><th>{{E1}}</th><th></th></tr></table><span class=\"why\">Warum: So sieht die Übersicht wie auf den Folien aus.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Links: {{Z1}} + {{M1}} = {{Z1+M1}}. Rechts: {{F1}} + {{E1}} = {{F1+E1}}. Gleich. Außerdem: Einkommen {{s}} − {{u}} = {{s-u}} plus Transfer {{e}} ergibt die EK-Änderung {{E1-E0}}.</p>\n<p class=\"merke\"><b>Merke:</b> In jeder Zeile muss die linke Seite um genauso viel wachsen oder schrumpfen wie die rechte. <i>(Skript: Folien 39–58; Übungsskript 2.1 Teil 1 (S. 7))</i></p>","short":"EB: ZM {{Z1}} + Material {{M1}} = FK {{F1}} + EK {{E1}}","diag":false,"src":"eigene","gen":{"vars":{"Z0":{"min":5000,"max":15000,"step":500},"M0":{"min":1000,"max":4000,"step":500},"F0":{"min":1000,"max":5000,"step":500},"m":{"min":500,"max":2500,"step":100},"r":{"min":500,"max":3000,"step":100},"s":{"min":2000,"max":6000,"step":100},"u":{"min":200,"max":1000,"step":100},"e":{"min":1000,"max":4000,"step":500}},"let":{"E0":"Z0+M0-F0","Z1":"Z0-m-r+s+e","M1":"M0+m-u","F1":"F0-r","E1":"E0+s-u+e"},"check":"E0 > 0 && r < F0 && s > u && Z0-m-r > 0"}},{"id":"bure-t9","topic":"bure-zwecke","level":2,"type":"open","q":"Eine Maschine kostet {{P}}. Die Hälfte wird Ende Jahr 1 bezahlt, die andere Hälfte Ende Jahr 2. Nutzung 4 Jahre gleichmäßig. Jährlich: Umsatz {{U}} bar, Material und Löhne {{K}} bar. Werbung {{W}} einmal in Jahr 1, Wirkung über 4 Jahre. Alle Zahlungen am Jahresende.<br/> a) Berechne den Zahlungssaldo je Jahr und gesamt. b) Stelle die periodengerechte Rechnung wie im Übungsskript 2.4 auf. c) Vergleiche die Summen.","a":"<p class=\"goal\"><b>Ziel:</b> Zahlungssaldo und periodengerechtes Ergebnis für vier Jahre berechnen und vergleichen.</p>\n<ol class=\"sol-steps\">\n<li>Hälfte des Kaufpreises: {{P}} / 2 = {{H}}.<span class=\"why\">Warum: Die Maschine wird in zwei gleichen Raten bezahlt: Ende Jahr 1 und Ende Jahr 2.</span></li>\n<li>a) Jahr 1: {{U}} − {{K}} − {{H}} − {{W}} = <b>{{S1m}}</b>.<span class=\"why\">Warum: Zahlungssaldo = was in dem Jahr auf dem Konto rein- und rausgeht. In Jahr 1 fließen Umsatz, Kosten, die erste Rate und die ganze Werbung.</span></li>\n<li>Jahr 2: {{U}} − {{K}} − {{H}} = <b>{{S2m}}</b>. Jahr 3 und 4: {{U}} − {{K}} = <b>{{S3}}</b>.<span class=\"why\">Warum: In Jahr 2 kommt die zweite Rate dazu. Danach gibt es nur noch Umsatz und laufende Kosten.</span></li>\n<li>Summe: 4 · ({{U}} − {{K}}) − {{P}} − {{W}} = 4 · {{S3}} − {{P}} − {{W}} = {{4*S3}} − {{P+W}} = <b>{{Sum}}</b>.<span class=\"why\">Warum: Über vier Jahre fließt viermal Umsatz minus Kosten. Maschine und Werbung werden je einmal ganz bezahlt.</span></li>\n<li>b) Verteilen: Maschine {{P}} / 4 = {{Pa}} pro Jahr, Werbung {{W}} / 4 = {{Wa}} pro Jahr.<span class=\"why\">Warum: Periodengerecht heißt: Eine Ausgabe wird auf die Jahre verteilt, in denen sie nützt. Bei der Maschine nennt man das Abschreibung.</span></li>\n<li>Jedes Jahr: {{U}} − {{K}} − {{Pa}} − {{Wa}} = <b>{{Pg}}</b>. Summe 4 · {{Pg}} = <b>{{Sum}}</b>.<span class=\"why\">Warum: Weil alles gleichmäßig verteilt ist, kommt jedes Jahr dasselbe heraus.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>Jahr 1</th><th>Jahr 2</th><th>Jahr 3</th><th>Jahr 4</th><th>Summe</th></tr><tr><td>a) Zahlungssaldo</td><td>{{S1m}}</td><td>{{S2m}}</td><td>{{S3}}</td><td>{{S3}}</td><td>{{Sum}}</td></tr><tr><td>b) periodengerecht</td><td>{{Pg}}</td><td>{{Pg}}</td><td>{{Pg}}</td><td>{{Pg}}</td><td>{{Sum}}</td></tr></table>c) Beide Summen sind gleich.<span class=\"why\">Warum: Die periodengerechte Rechnung verschiebt Beträge nur zwischen den Jahren. Insgesamt wird nichts erfunden oder weggelassen. Pro Jahr zeigt sie aber den echten Erfolg besser.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> 4 · {{Pg}} = {{4*Pg}} und das ist gleich der Zahlungssumme {{Sum}}.</p>\n<p class=\"merke\"><b>Merke:</b> Zahlungen schwanken mit dem Zahlungstermin; periodengerechtes Ergebnis zeigt den Erfolg pro Jahr, über die ganze Zeit sind beide gleich. <i>(Übungsskript 2.4 (S. 14))</i></p>","short":"a) {{S1m}} / {{S2m}} / {{S3}} / {{S3}} · b) je {{Pg}} · Summe beide {{Sum}}","diag":false,"src":"eigene","gen":{"vars":{"P":{"min":24000,"max":60000,"step":4000},"W":{"min":4000,"max":12000,"step":400},"U":{"min":50000,"max":100000,"step":5000},"K":{"min":30000,"max":80000,"step":5000}},"let":{"H":"P/2","Pa":"P/4","Wa":"W/4","S1":"U-K-H-W","S2":"U-K-H","S3":"U-K","Sum":"4*(U-K)-P-W","Pg":"U-K-Pa-Wa","S1m":"(S1<0?'−':'')+num(abs(S1))","S2m":"(S2<0?'−':'')+num(abs(S2))"},"check":"U > K && Pg > 0"}},{"id":"bure-t10","topic":"bure-konzepte","level":3,"type":"open","q":"Ein Werk stellt 1000 Fertigteile her und verkauft {{S}} für je {{p}}. Direkte Materialausgaben {{D}}. Strom für die Hallenbeleuchtung (indirekt) {{I}}. Berechne das Einkommen nach Marginal- und nach Finalprinzip und erkläre die Differenz.","a":"<p class=\"goal\"><b>Ziel:</b> Das Einkommen nach Marginal- und nach Finalprinzip berechnen und den Unterschied erklären.</p>\n<ol class=\"sol-steps\">\n<li>Umsatzertrag: {{S}} × {{p}} = <b>{{Ru}}</b>.<span class=\"why\">Warum: Verkaufte Stück mal Preis pro Stück.</span></li>\n<li>Verkaufter Anteil: {{S}} von 1000 Stück = {{q}} %.<span class=\"why\">Warum: Nur für verkaufte Stücke wird die Herstellung zu Aufwand (Marktleistungsabgabe). Der Rest liegt im Lager und ist noch Vermögen.</span></li>\n<li><b>Marginalprinzip:</b> Nur direkte Ausgaben zählen zur Herstellung. Umsatzaufwand {{q}} % × {{D}} = {{ad}}. Strom {{I}} ist sofort Aufwand.<span class=\"why\">Warum: Marginal heißt: nur das, was direkt im Stück steckt (Material). Indirektes wie Hallenlicht wird sofort Aufwand (Periodisierung).</span></li>\n<li>Einkommen marginal: {{Ru}} − {{ad}} = {{Ru-ad}}; − {{I}} = <b>{{Ym}}</b>. Im Lager bleiben {{D}} − {{ad}} = {{D-ad}}.<span class=\"why\">Warum: Vom Umsatz ziehst du den Aufwand der verkauften Stücke und den ganzen Strom ab.</span></li>\n<li><b>Finalprinzip:</b> Herstellung = direkt + indirekt = {{D}} + {{I}} = {{D+I}}. Umsatzaufwand {{q}} % × {{D+I}} = {{af}}.<span class=\"why\">Warum: Final heißt: alles, was für die Herstellung nötig war, auch der Strom, wird auf die Stücke verteilt.</span></li>\n<li>Einkommen final: {{Ru}} − {{af}} = <b>{{Yf}}</b>. Im Lager: {{D+I}} − {{af}} = {{D+I-af}}.<span class=\"why\">Warum: Hier gibt es keinen extra Stromabzug mehr, denn der Strom steckt schon im Umsatzaufwand und im Lager.</span></li>\n<li>Differenz: {{Yf}} − {{Ym}} = <b>{{Yf-Ym}}</b> = {{100-q}} % × {{I}}.<span class=\"why\">Warum: Beim Finalprinzip liegt der Stromanteil der nicht verkauften Stücke noch im Lager. Beim Marginalprinzip ist er schon Aufwand.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{100-q}} % von {{I}} = {{I*(100-q)/100}}. Das ist genau die Differenz.</p>\n<p class=\"merke\"><b>Merke:</b> Lagermehrung (mehr hergestellt als verkauft) heißt: Finalprinzip zeigt das höhere Einkommen. <i>(Skript: Folien 34–37; Modul 2 Folie 61; Übungsskript 3.3 (S. 24))</i></p>","short":"Marginal {{Ym}}, Final {{Yf}}, Differenz {{Yf-Ym}}","diag":false,"src":"eigene","gen":{"vars":{"S":{"min":600,"max":900,"step":50},"p":{"min":15,"max":40,"step":1},"D":{"min":8000,"max":16000,"step":1000},"I":{"min":1000,"max":5000,"step":500}},"let":{"q":"S/10","Ru":"S*p","ad":"D*S/1000","af":"(D+I)*S/1000","Ym":"Ru-ad-I","Yf":"Ru-af"},"check":"isInt(ad) && isInt(af) && Ym > 0"}},{"id":"bure-t11","topic":"bure-ek","level":3,"type":"open","q":"Wie wirkt sich jedes Ereignis auf Bilanz und Eigenkapital des Unternehmens aus?<br/> a) Der Inhaber zahlt ein Firmendarlehen von {{La}} von seinem Privatkonto zurück. b) Er renoviert sein Privathaus und zahlt privat. c) Er bezahlt seinen Urlaub für {{Ur}} aus der Firmenkasse. d) Er bringt seinen privaten Pkw (Wert {{Pk}}) ins Unternehmen ein. e) Ein Lagergebäude (Buchwert {{Bw}}) brennt ab, ohne Versicherung. f) Das Unternehmen plant, nächstes Jahr einen Kredit aufzunehmen. g) Ein Grundstück (Buchwert {{Gb}}) wird für {{V}} auf Ziel verkauft.<br/> Wie ändert sich das EK insgesamt? Wie viel davon ist Einkommen?","a":"<p class=\"goal\"><b>Ziel:</b> Für jedes Ereignis die Wirkung auf Bilanz und Eigenkapital bestimmen und die EK-Änderung in Einkommen und Transfers aufteilen.</p>\n<ol class=\"sol-steps\">\n<li>a) FK −{{La}}, EK +{{La}} (Einlage) → Passivtausch mit EK-Wirkung, EK +{{La}}.<span class=\"why\">Warum: Der Inhaber zahlt privat. Firmengeld fließt nicht, aber die Schuld der Firma sinkt. Das wirkt so, als hätte er {{La}} eingelegt.</span></li>\n<li>b) Keine Buchung, EK 0.<span class=\"why\">Warum: Das Privathaus gehört nicht zur Firma. Firma und Inhaber werden getrennt gerechnet (andere Wirtschaftseinheit).</span></li>\n<li>c) Zahlungsmittel −{{Ur}}, EK −{{Ur}} → Bilanzverkürzung mit EK-Wirkung (Entnahme).<span class=\"why\">Warum: Firmengeld geht für privaten Urlaub raus. Das ist eine Entnahme, kein Aufwand der Firma.</span></li>\n<li>d) Pkw +{{Pk}}, EK +{{Pk}} → Bilanzverlängerung mit EK-Wirkung (Sacheinlage).<span class=\"why\">Warum: Statt Geld bringt der Inhaber einen Gegenstand ein. Auch das ist eine Einlage.</span></li>\n<li>e) Gebäude −{{Bw}}, EK −{{Bw}} → Bilanzverkürzung mit EK-Wirkung (Aufwand).<span class=\"why\">Warum: Das Gebäude ist weg und nichts kommt dafür zurück. Das macht ärmer, also Aufwand.</span></li>\n<li>f) Keine Buchung, EK 0.<span class=\"why\">Warum: Ein Plan ändert heute weder Vermögen noch Schulden.</span></li>\n<li>g) Forderung +{{V}}, Grundstück −{{Gb}} → Bilanzverlängerung mit EK-Wirkung. Ertrag {{V}} − Aufwand {{Gb}} = +{{g}}.<span class=\"why\">Warum: Das Grundstück geht weg (Aufwand in Höhe des Buchwerts), dafür bekommen wir eine Forderung über den Verkaufspreis (Ertrag). Der Unterschied ist Gewinn.</span></li>\n<li>EK gesamt: {{La}} − {{Ur}} + {{Pk}} − {{Bw}} + {{g}} = <b>{{tots}}</b>.<span class=\"why\">Warum: Einfach alle EK-Änderungen aus der Liste mit Vorzeichen addieren.</span></li>\n<li>Davon Einkommen: −{{Bw}} + {{g}} = <b>{{Ys}}</b>. Transfers: {{La}} − {{Ur}} + {{Pk}} = <b>{{Trs}}</b>.<span class=\"why\">Warum: Einkommen kommt nur aus Ertrag und Aufwand (e und g). Einlagen und Entnahmen (a, c, d) sind Transfers.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Einkommen + Transfers muss die EK-Änderung ergeben: {{Ys}} und {{Trs}} zusammen = {{tots}}.</p>\n<p class=\"merke\"><b>Merke:</b> Was der Inhaber privat bezahlt oder einbringt, ist für die Firma eine Einlage, was er privat nimmt, eine Entnahme. <i>(Skript: Folie 52; Übungsskript 3.2 (S. 20), Fälle k, t, u, v, x)</i></p>","short":"EK gesamt {{tots}}; davon Einkommen {{Ys}}, Transfers {{Trs}}","diag":false,"src":"eigene","gen":{"vars":{"La":{"min":5000,"max":30000,"step":1000},"Ur":{"min":1000,"max":6000,"step":500},"Pk":{"min":5000,"max":20000,"step":1000},"Bw":{"min":10000,"max":60000,"step":5000},"Gb":{"min":10000,"max":50000,"step":1000},"g":{"min":1000,"max":10000,"step":1000}},"let":{"V":"Gb+g","Tr":"La-Ur+Pk","Y":"g-Bw","tot":"Tr+Y","Trs":"(Tr<0?'−':'+')+num(abs(Tr))","Ys":"(Y<0?'−':'+')+num(abs(Y))","tots":"(tot<0?'−':'+')+num(abs(tot))"},"check":"tot != 0 && Y != 0"}},{"id":"bure-t12","topic":"bure-zwecke","level":3,"type":"open","q":"Ein Hersteller hat in 20X1: a) Verkauf aller Erzeugnisse für {{S}}, davon {{S1}} bezahlt, Rest in 20X2. b) Material {{M}} gekauft und verbraucht, {{M1}} bar, {{Mz}} auf Ziel. c) Löhne {{L}} überwiesen. d) Rohstoffe {{R}} bar gekauft, liegen noch im Lager. e) Abschreibung Maschinen {{A}}. f) Bankdarlehen {{D}} erhalten, Rückzahlung 20X3, Zinsen {{Z}} bar in 20X1. g) Entnahme {{En}}. h) Einlage {{Ei}}.<br/> Berechne den Einzahlungsüberschuss und leite daraus den Einnahme-Ausgabe-Saldo und das Einkommen ab.","a":"<p class=\"goal\"><b>Ziel:</b> Den Einzahlungsüberschuss berechnen und daraus Schritt für Schritt Einnahme-Ausgabe-Saldo und Einkommen ableiten.</p>\n<ol class=\"sol-steps\">\n<li>Drei Ebenen: Einzahlung (Bargeld), Einnahme (Geldvermögen = Geld + Forderungen − Verbindlichkeiten), Ertrag (verdient, EK steigt).<span class=\"why\">Warum: Wir starten bei den Zahlungen und korrigieren dann, was auf der nächsten Ebene anders zählt.</span></li>\n<li>Einzahlungen: bezahlter Verkauf {{S}} − {{Re}} = {{S1}}. Dazu Darlehen und Einlage: {{S1}} + {{D}} + {{Ei}} = <b>{{Ez}}</b>.<span class=\"why\">Warum: Nur Geld, das wirklich eingegangen ist, zählt. Der offene Rest {{Re}} kommt erst 20X2.</span></li>\n<li>Zinsen: {{zi}} % × {{D}} = {{Z}}. Material bar: {{M}} − {{Mz}} = {{M1}}.<span class=\"why\">Warum: Prozent heißt „von Hundert“: {{D}} / 100 · {{zi}}. Beim Material zählt nur der bar bezahlte Teil.</span></li>\n<li>Auszahlungen: {{M1}} + {{L}} + {{R}} + {{Z}} + {{En}} = <b>{{Az}}</b>. Überschuss: {{Ez}} − {{Az}} = <b>{{U}}</b>.<span class=\"why\">Warum: Alles, was vom Konto abging: Material bar, Löhne, Rohstoffe, Zinsen, Entnahme. Die Abschreibung ist keine Zahlung.</span></li>\n<li>Einnahme-Ausgabe: {{U}} + {{Re}} − {{Mz}} − {{D}} = <b>{{EAm}}</b>.<span class=\"why\">Warum: +{{Re}}: Die Forderung erhöht das Geldvermögen ohne Geld. −{{Mz}}: Material auf Ziel ist eine Schuld, also Ausgabe ohne Zahlung. −{{D}}: Das Darlehen brachte Geld, aber die Schuld steigt gleich stark, also keine Einnahme.</span></li>\n<li>Einkommen: {{EAm}} + {{En}} − {{Ei}} + {{R}} − {{A}} = <b>{{Y}}</b>.<span class=\"why\">Warum: +{{En}}: Entnahme ist Ausgabe, aber kein Aufwand. −{{Ei}}: Einlage ist Einnahme, aber kein Ertrag. +{{R}}: Rohstoffe im Lager sind noch Vermögen, also noch kein Aufwand. −{{A}}: Abschreibung ist Aufwand ohne Ausgabe.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Direkt: Ertrag {{S}} − Aufwand ({{M}} + {{L}} + {{A}} + {{Z}}) = {{S}} − {{M+L+A+Z}} = {{S-M-L-A-Z}}. Gleiches Ergebnis.</p>\n<p class=\"merke\"><b>Merke:</b> Von Zahlung zu Einkommen kommst du, indem du Forderungen, Schulden, Transfers, Lager und Abschreibung einzeln korrigierst. <i>(Übungsskript 1.4 (S. 5))</i></p>","short":"Einzahlungsüberschuss {{U}}; Einnahme-Ausgabe {{EAm}}; Einkommen {{Y}}","diag":false,"src":"eigene","gen":{"vars":{"S":{"min":50000,"max":120000,"step":5000},"Re":{"min":5000,"max":30000,"step":5000},"M":{"min":10000,"max":40000,"step":1000},"Mz":{"min":2000,"max":15000,"step":1000},"L":{"min":10000,"max":30000,"step":1000},"R":{"min":1000,"max":6000,"step":500},"A":{"min":2000,"max":10000,"step":500},"D":{"min":20000,"max":60000,"step":5000},"zi":[3,4,5],"En":{"min":3000,"max":12000,"step":500},"Ei":{"min":2000,"max":8000,"step":500}},"let":{"S1":"S-Re","M1":"M-Mz","Z":"D*zi/100","Ez":"S1+D+Ei","Az":"M1+L+R+Z+En","U":"Ez-Az","EA":"U+Re-Mz-D","Y":"EA+En-Ei+R-A","EAm":"(EA<0?'−':'')+num(abs(EA))"},"check":"Re < S && Mz < M && Y > 0 && U > 0 && EA != 0"}},{"id":"bure-t13","topic":"bure-ek","level":3,"type":"open","q":"Lena Brandt gründet im März 20X1 das Ingenieurbüro „Brandt Statik“.<br/> a) Einlage {{E}} bar. b) Büroausstattung für {{Au}} bar. c) Büromaterial {{Mat}} auf Ziel. d) Bankdarlehen {{D}}. e) Statikgutachten für {{Gu}} auf Ziel, Büromaterial {{u}} verbraucht. f) Miete {{Mi}} und Werbung {{W}} bar. g) Der Kunde aus e) zahlt {{p}}. h) {{hp}} der Büromaterial-Rechnung bezahlt. i) Entnahme {{Ent}}. j) Brandt kauft privat ein Fahrrad für {{Fa}}.<br/> 1. Gib die Bilanzwirkung je Ereignis an. 2. Stelle Einkommensrechnung, Eigenkapitaltransferrechnung und Eigenkapitalveränderungsrechnung auf. 3. Stelle die Bilanz zum 31.3. auf.","a":"<p class=\"goal\"><b>Ziel:</b> Die Gründung von „Brandt Statik“ in der Bilanz abbilden, die drei Rechnungen aufstellen und die Bilanz zum 31.3. machen.</p>\n<ol class=\"sol-steps\">\n<li>a) ZM +{{E}}, EK +{{E}} → Verlängerung mit EK (Einlage). b) Ausstattung +{{Au}}, ZM −{{Au}} → Aktivtausch.<span class=\"why\">Warum: Die Einlage kommt vom Inhaber (Transfer). Beim Kauf wird Geld nur zu Ausstattung getauscht.</span></li>\n<li>c) Material +{{Mat}}, Verbindlichkeiten +{{Mat}} → Verlängerung ohne EK. d) ZM +{{D}}, Darlehen +{{D}} → Verlängerung ohne EK.<span class=\"why\">Warum: Auf Ziel und Kredit: Es kommt Vermögen dazu, aber auch gleich viel Schuld.</span></li>\n<li>e) Forderung +{{Gu}} (Ertrag), Material −{{u}} (Aufwand) → EK +{{Gu}} − {{u}} = +{{Gu-u}}.<span class=\"why\">Warum: Das Gutachten ist verkauft (Ertrag), auch wenn noch nicht bezahlt. Das verbrauchte Material ist weg (Aufwand).</span></li>\n<li>f) Miete + Werbung: {{Mi}} + {{W}} = {{Fm}}. ZM −{{Fm}}, EK −{{Fm}} → Verkürzung mit EK (Aufwand).<span class=\"why\">Warum: Miete und Werbung sind verbraucht, dafür bleibt kein Vermögen.</span></li>\n<li>g) ZM +{{p}}, Forderung −{{p}} → Aktivtausch. h) Verbindlichkeiten −{{hp}}, ZM −{{hp}} → Verkürzung ohne EK.<span class=\"why\">Warum: Kundenzahlung: Forderung wird zu Geld. Schuld bezahlen: Geld und Schuld sinken gleich.</span></li>\n<li>i) ZM −{{Ent}}, EK −{{Ent}} → Verkürzung mit EK (Entnahme). j) Keine Buchung.<span class=\"why\">Warum: Die Entnahme ist ein Transfer. Das Fahrrad kauft Brandt privat, das geht die Firma nichts an.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>ZM</th><th>Ausstattung</th><th>Material</th><th>Forderung</th><th>=</th><th>Verb. Lief.</th><th>Darlehen</th><th>EK</th></tr><tr><td>a</td><td>+{{E}}</td><td></td><td></td><td></td><td></td><td></td><td></td><td>+{{E}}</td></tr><tr><td>b</td><td>−{{Au}}</td><td>+{{Au}}</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>c</td><td></td><td></td><td>+{{Mat}}</td><td></td><td></td><td>+{{Mat}}</td><td></td><td></td></tr><tr><td>d</td><td>+{{D}}</td><td></td><td></td><td></td><td></td><td></td><td>+{{D}}</td><td></td></tr><tr><td>e</td><td></td><td></td><td>−{{u}}</td><td>+{{Gu}}</td><td></td><td></td><td></td><td>+{{Gu-u}}</td></tr><tr><td>f</td><td>−{{Fm}}</td><td></td><td></td><td></td><td></td><td></td><td></td><td>−{{Fm}}</td></tr><tr><td>g</td><td>+{{p}}</td><td></td><td></td><td>−{{p}}</td><td></td><td></td><td></td><td></td></tr><tr><td>h</td><td>−{{hp}}</td><td></td><td></td><td></td><td></td><td>−{{hp}}</td><td></td><td></td></tr><tr><td>i</td><td>−{{Ent}}</td><td></td><td></td><td></td><td></td><td></td><td></td><td>−{{Ent}}</td></tr><tr><th>EB</th><th>{{ZM}}</th><th>{{Au}}</th><th>{{Ma}}</th><th>{{Fo}}</th><th>=</th><th>{{Vb}}</th><th>{{D}}</th><th>{{EK}}</th></tr></table><span class=\"why\">Warum: Endbestand je Spalte = Summe aller Plus und Minus. Zum Beispiel Material: {{Mat}} − {{u}} = {{Ma}}; Forderung: {{Gu}} − {{p}} = {{Fo}}; Verbindlichkeiten: {{Mat}} − {{hp}} = {{Vb}}.</span></li>\n<li>2. Einkommensrechnung: Ertrag {{Gu}}. Aufwand {{u}} + {{Mi}} + {{W}} = {{Aw}}. Einkommen {{Gu}} − {{Aw}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Einkommen ist der Gewinn im März: verdient minus verbraucht.</span></li>\n<li>Transferrechnung: {{E}} − {{Ent}} = <b>{{Tr}}</b>. Veränderungsrechnung: 0 + {{Tr}} + {{Y}} = <b>{{EK}}</b>.<span class=\"why\">Warum: Die Firma startet mit EK 0. Das EK am Ende besteht aus Transfers plus Einkommen.</span></li>\n<li>3. Bilanz: Aktiva {{ZM}} + {{Au}} + {{Ma}} + {{Fo}} = <b>{{AS}}</b>. Passiva {{Vb}} + {{D}} + {{EK}} = <b>{{AS}}</b>.<span class=\"why\">Warum: Links das Vermögen am 31.3., rechts Schulden und Eigenkapital.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Zahlungsmittel nachrechnen: {{E}} − {{Au}} + {{D}} − {{Fm}} + {{p}} − {{hp}} − {{Ent}} = {{ZM}}. Passiva {{Vb}} + {{D}} + {{EK}} = {{Vb+D+EK}} = Aktiva {{AS}}.</p>\n<p class=\"merke\"><b>Merke:</b> Private Käufe des Inhabers bucht die Firma nicht; nur was Firmenvermögen berührt, kommt in die Bilanz. <i>(Übungsskript 2.1 (S. 7))</i></p>","short":"Einkommen {{Y}}; Transfer {{Tr}}; EK {{EK}}; Bilanzsumme {{AS}}","diag":false,"src":"eigene","gen":{"vars":{"E":{"min":30000,"max":80000,"step":5000},"Au":{"min":3000,"max":10000,"step":500},"Mat":{"min":500,"max":1500,"step":100},"D":{"min":10000,"max":30000,"step":5000},"Gu":{"min":4000,"max":10000,"step":500},"u":{"min":100,"max":500,"step":50},"Mi":{"min":800,"max":1600,"step":100},"W":{"min":200,"max":800,"step":50},"p":{"min":2000,"max":9000,"step":500},"hp":{"min":200,"max":1400,"step":100},"Ent":{"min":1000,"max":3000,"step":500},"Fa":{"min":500,"max":1500,"step":100}},"let":{"Fm":"Mi+W","ZM":"E-Au+D-Fm+p-hp-Ent","Ma":"Mat-u","Fo":"Gu-p","Vb":"Mat-hp","Aw":"u+Mi+W","Y":"Gu-Aw","Tr":"E-Ent","EK":"Tr+Y","AS":"ZM+Au+Ma+Fo"},"check":"u < Mat && p < Gu && hp < Mat && Y > 0"}},{"id":"bure-t14","topic":"bure-zwecke","level":1,"type":"open","q":"Tim Becker eröffnet am 1.1.20X1 einen Fahrradhandel. Er legt {{E}} bar ein und nimmt ein Bankdarlehen über {{D}} auf (Rückzahlung {{D}} in 20X2). Er kauft Fahrräder für {{K}} bar und verkauft die Hälfte davon für {{V}}; der Kunde zahlt erst in 20X2. Für seinen Urlaub entnimmt er {{Ent}}.<br><b>Zahlungsorientiert</b>: Stelle auf 1. die Anfangsbilanz 1.1., 2. die Einkommensrechnung 20X1, 3. die Eigenkapitaltransferrechnung, 4. die Eigenkapitalveränderungsrechnung, 5. die Schlussbilanz 31.12.","a":"<p class=\"goal\"><b>Ziel:</b> Den Fahrradhandel von Tim Becker zahlungsorientiert durchrechnen: Hier zählt nur Geld, das wirklich fließt.</p>\n<ol class=\"sol-steps\">\n<li>1. Anfangsbilanz: Zahlungsmittel {{E}} + {{D}} = <b>{{ZA}}</b> = FK {{D}} + EK {{E}}.<span class=\"why\">Warum: Zahlungsorientiert gibt es nur Zahlungsmittel als Vermögen. Sie kommen aus Einlage (EK) und Darlehen (FK).</span></li>\n<li>2. Einkommensrechnung: Kauf −{{K}}. Verkauf auf Ziel 0. Einkommen <b>−{{K}}</b>.<span class=\"why\">Warum: Nur Zahlungen zählen. Der Kauf der Fahrräder kostete Geld, der Verkauf brachte noch kein Geld, weil der Käufer erst 20X2 zahlt.</span></li>\n<li>3. Transferrechnung: Entnahme <b>−{{Ent}}</b>.<span class=\"why\">Warum: Der Urlaub ist privat, also ein Transfer an den Inhaber.</span></li>\n<li>4. Veränderungsrechnung: {{E}} − {{K}} − {{Ent}} = <b>{{EKe}}</b>. Veränderung −{{K+Ent}}.<span class=\"why\">Warum: EK Ende = EK Anfang + Einkommen + Transfer.</span></li>\n<li>5. Schlussbilanz: Zahlungsmittel {{ZA}} − {{K}} − {{Ent}} = <b>{{ZE}}</b> = FK {{D}} + EK {{EKe}}.<span class=\"why\">Warum: Das Darlehen wird erst 20X2 zurückgezahlt, steht also noch als FK da.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> FK + EK: {{D}} + {{EKe}} = {{D+EKe}} = Zahlungsmittel {{ZE}}. Die Bilanz geht auf.</p>\n<p class=\"merke\"><b>Merke:</b> Zahlungsorientiert sieht die Firma schlecht aus, obwohl sie mit Gewinn verkauft hat; der Verkauf auf Ziel zählt hier einfach noch nicht.</p>","short":"Einkommen −{{K}}; EK Ende {{EKe}}; Schlussbilanz ZM {{ZE}} = FK {{D}} + EK {{EKe}}","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 1.1)","gen":{"vars":{"E":{"min":800,"max":2000,"step":100,"not":[1000]},"D":{"min":300,"max":1000,"step":100},"K":{"min":200,"max":800,"step":100},"V":{"min":200,"max":1600,"step":50},"Ent":{"min":200,"max":1000,"step":100,"not":[600]}},"let":{"ZA":"E+D","H":"K/2","EKe":"E-K-Ent","ZE":"E+D-K-Ent"},"check":"V > H && V <= 2*K && EKe >= 0"}},{"id":"bure-t15","topic":"bure-zwecke","level":1,"type":"open","q":"Fahrradhandel Tim Becker, Gründung 1.1.20X1: Einlage {{E}} bar, Darlehen {{D}} (Rückzahlung in 20X2), Fahrräder für {{K}} bar gekauft, die Hälfte davon für {{V}} auf Ziel verkauft (Zahlung 20X2), Entnahme {{Ent}} für den Urlaub. Rechne jetzt <b>reinvermögensorientiert</b>; bewerte zu Anschaffungsausgaben bzw. zum Rückzahlungsbetrag.<br>Stelle auf: 1. Anfangsbilanz, 2. Einkommensrechnung, 3. Transferrechnung, 4. Veränderungsrechnung, 5. Schlussbilanz.","a":"<p class=\"goal\"><b>Ziel:</b> Den Fahrradhandel von Tim Becker reinvermögensorientiert rechnen: Jetzt zählen alle Vermögensgüter und Schulden.</p>\n<ol class=\"sol-steps\">\n<li>1. Anfangsbilanz: Zahlungsmittel {{ZA}} = FK {{D}} + EK {{E}}.<span class=\"why\">Warum: Am 1.1. gibt es nur Geld aus Einlage und Darlehen, wie zahlungsorientiert.</span></li>\n<li>Barkauf {{K}}: Zahlungsmittel −{{K}}, Güter +{{K}} → Aktivtausch, kein Einkommen.<span class=\"why\">Warum: Reinvermögensorientiert sind die Güter Vermögen. Geld wird nur in Güter getauscht.</span></li>\n<li>2. Einkommen: Hälfte der Fahrräder {{K}} / 2 = {{H}}. Ertrag {{V}} − Aufwand {{H}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Beim Verkauf (Marktleistungsabgabe) zählt der Preis als Ertrag und die verkauften Güter als Aufwand. Es ist egal, dass der Kunde erst später zahlt.</span></li>\n<li>3. Transferrechnung: Entnahme <b>−{{Ent}}</b>.<span class=\"why\">Warum: Privater Urlaub, also Transfer.</span></li>\n<li>4. Veränderungsrechnung: {{E}} + {{Y}} − {{Ent}} = <b>{{EKe}}</b>. Veränderung {{dEs}}.<span class=\"why\">Warum: EK Ende = EK Anfang + Einkommen + Transfer.</span></li>\n<li>5. Schlussbilanz: Zahlungsmittel {{ZA}} − {{K}} − {{Ent}} = {{ZE}}. Vermögen {{ZE}} + Güter {{H}} + Forderung {{V}} = <b>{{VG}}</b> = FK {{D}} + EK {{EKe}}.<span class=\"why\">Warum: Die nicht verkauften Fahrräder stehen noch im Lager, und der Kunde schuldet uns {{V}}. Beides ist Vermögen.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Passiva {{D}} + {{EKe}} = {{D+EKe}}, Aktiva {{VG}}. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Reinvermögensorientiert zählt der Verkauf sofort als Ertrag, auch auf Ziel; deshalb sieht der Erfolg hier realistischer aus als zahlungsorientiert.</p>","short":"Einkommen {{Y}}; EK Ende {{EKe}}; Vermögen {{VG}}","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 1.2)","gen":{"vars":{"E":{"min":800,"max":2000,"step":100,"not":[1000]},"D":{"min":300,"max":1000,"step":100},"K":{"min":200,"max":800,"step":100},"V":{"min":200,"max":1600,"step":50},"Ent":{"min":200,"max":1000,"step":100,"not":[600]}},"let":{"ZA":"E+D","H":"K/2","Y":"V-H","EKe":"E+Y-Ent","dE":"Y-Ent","ZE":"E+D-K-Ent","VG":"ZE+H+V","dEs":"(dE<0?'−':'+')+num(abs(dE))"},"check":"V > H && V <= 2*K && ZE >= 0 && dE != 0"}},{"id":"bure-t16","topic":"bure-zwecke","level":3,"type":"open","q":"Bauunternehmen, 1.1.20X1: zwei Bagger zu je 300.000. Bagger 1 wird sofort bar bezahlt, Bagger 2 mit Zahlungsziel in 20X2. Nutzung je 4 Jahre, gleichmäßige Wertminderung. Zahlungsströme aus dem Einsatz der Bagger:<table class=\"tt\"><tr><th></th><th>20X1</th><th>20X2</th><th>20X3</th><th>20X4</th></tr><tr><td>Bagger 1</td><td>−80.000</td><td>+110.000</td><td>+200.000</td><td>+230.000</td></tr><tr><td>Bagger 2</td><td>−40.000</td><td>+120.000</td><td>+160.000</td><td>+240.000</td></tr></table>Gehälter der Baggerfahrer: 120.000 pro Jahr, jeweils in 20X1 bis 20X4 gezahlt. Entnahme der Inhaberin: 30.000 pro Jahr. Anfang 20X2 Kredit: Auszahlung 152.000, Rückzahlung 160.000 Ende 20X4, Zinsen 5 % des Rückzahlungsbetrags pro Jahr.<br>Annahmen: Die Zahlungsströme der Bagger sind im selben Jahr auch Einnahmen bzw. Ausgaben und Ertrag bzw. Aufwand. Das Disagio ist im Jahr der Kreditaufnahme voll Aufwand.<br>Stelle auf: 1. Einzahlungs-Auszahlungs-Rechnung je Jahr und für alle 4 Jahre. 2. Einnahme-Ausgabe-Rechnung. 3. Ertrags-Aufwands-Rechnung. Nimm jeweils kurz Stellung.","a":"<p class=\"goal\"><b>Ziel:</b> Für die beiden Bagger drei Rechnungen über vier Jahre aufstellen und vergleichen.</p>\n<ol class=\"sol-steps\">\n<li>Laufende Ströme beider Bagger addieren: 20X1 −80.000 − 40.000 = −120.000; 20X2 110.000 + 120.000 = 230.000; 20X3 200.000 + 160.000 = 360.000; 20X4 230.000 + 240.000 = 470.000.<span class=\"why\">Warum: Die laufenden Ströme sind laut Annahme in allen drei Rechnungen gleich, also rechnest du sie einmal vorab.</span></li>\n<li>Zinsen: 5 % × 160.000 = 160.000 / 100 · 5 = 8.000 pro Jahr ab 20X2. Disagio: 160.000 − 152.000 = 8.000. Wertminderung: 300.000 / 4 = 75.000 je Bagger, für beide 150.000 pro Jahr.<span class=\"why\">Warum: Zinsen zahlt man auf den Rückzahlungsbetrag. „Gleichmäßige Wertminderung“ heißt: Kaufpreis geteilt durch Nutzungsjahre (Abschreibung).</span></li>\n<li><b>Teil 1: Einzahlungs-Auszahlungs-Rechnung</b><table class=\"tt\"><tr><th></th><th>20X1</th><th>20X2</th><th>20X3</th><th>20X4</th><th>Summe</th></tr><tr><td>Kaufpreis Bagger</td><td>−300.000</td><td>−300.000</td><td>0</td><td>0</td><td>−600.000</td></tr><tr><td>laufende Ströme</td><td>−120.000</td><td>+230.000</td><td>+360.000</td><td>+470.000</td><td>+940.000</td></tr><tr><td>Gehälter</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−480.000</td></tr><tr><td>Entnahmen</td><td>−30.000</td><td>−30.000</td><td>−30.000</td><td>−30.000</td><td>−120.000</td></tr><tr><td>Kredit: Auszahlung an uns / Tilgung</td><td>0</td><td>+152.000</td><td>0</td><td>−160.000</td><td>−8.000</td></tr><tr><td>Zinsen</td><td>0</td><td>−8.000</td><td>−8.000</td><td>−8.000</td><td>−24.000</td></tr><tr><th>Saldo</th><th>−570.000</th><th>−76.000</th><th>+202.000</th><th>+152.000</th><th>−292.000</th></tr></table>Beispiel 20X1: −300.000 − 120.000 − 120.000 − 30.000 = −570.000.<span class=\"why\">Warum: Hier zählt nur, wann Geld fließt. Bagger 2 wird erst 20X2 bezahlt, der Kredit kommt 20X2 rein und geht 20X4 raus. Aussage: Kauf, Kredit und Entnahmen verzerren einzelne Jahre stark.</span></li>\n<li><b>Teil 2: Einnahme-Ausgabe-Rechnung</b><table class=\"tt\"><tr><th></th><th>20X1</th><th>20X2</th><th>20X3</th><th>20X4</th><th>Summe</th></tr><tr><td>Kaufpreis (Bagger 2 auf Ziel: Ausgabe schon 20X1)</td><td>−600.000</td><td>0</td><td>0</td><td>0</td><td>−600.000</td></tr><tr><td>laufende Ströme</td><td>−120.000</td><td>+230.000</td><td>+360.000</td><td>+470.000</td><td>+940.000</td></tr><tr><td>Gehälter</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−480.000</td></tr><tr><td>Entnahmen</td><td>−30.000</td><td>−30.000</td><td>−30.000</td><td>−30.000</td><td>−120.000</td></tr><tr><td>Kredit: +152.000 Geld, +160.000 Schuld</td><td>0</td><td>−8.000</td><td>0</td><td>0</td><td>−8.000</td></tr><tr><td>Zinsen</td><td>0</td><td>−8.000</td><td>−8.000</td><td>−8.000</td><td>−24.000</td></tr><tr><th>Saldo</th><th>−870.000</th><th>+64.000</th><th>+202.000</th><th>+312.000</th><th>−292.000</th></tr></table><span class=\"why\">Warum: Hier zählt das Geldvermögen (Geld + Forderungen − Schulden). Die Schuld für Bagger 2 entsteht schon 20X1. Beim Kredit: +152.000 Geld und +160.000 Schuld ergibt −8.000. Die Tilgung 20X4 senkt Geld und Schuld gleich, also 0.</span></li>\n<li><b>Teil 3: Ertrags-Aufwands-Rechnung</b><table class=\"tt\"><tr><th></th><th>20X1</th><th>20X2</th><th>20X3</th><th>20X4</th><th>Summe</th></tr><tr><td>Wertminderung Bagger</td><td>−150.000</td><td>−150.000</td><td>−150.000</td><td>−150.000</td><td>−600.000</td></tr><tr><td>laufende Ströme</td><td>−120.000</td><td>+230.000</td><td>+360.000</td><td>+470.000</td><td>+940.000</td></tr><tr><td>Gehälter</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−120.000</td><td>−480.000</td></tr><tr><td>Entnahmen (Transfer, kein Aufwand)</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>Disagio</td><td>0</td><td>−8.000</td><td>0</td><td>0</td><td>−8.000</td></tr><tr><td>Zinsen</td><td>0</td><td>−8.000</td><td>−8.000</td><td>−8.000</td><td>−24.000</td></tr><tr><th>Einkommen</th><th>−390.000</th><th>−56.000</th><th>+82.000</th><th>+192.000</th><th>−172.000</th></tr></table><span class=\"why\">Warum: Der Kaufpreis verteilt sich als Wertminderung über die Nutzung. Entnahmen sind privat und kein Aufwand. Diese Rechnung zeigt den Erfolg je Jahr am besten, braucht aber Schätzungen wie die Nutzungsdauer.</span></li>\n<li>Vergleich: Teil 1 und 2 haben in der Summe beide −292.000. Teil 3 liegt um die Entnahmen höher: −292.000 + 120.000 = −172.000.<span class=\"why\">Warum: Über die ganze Zeit gleichen sich Forderungen und Schulden aus. Nur die Entnahmen zählen in Teil 3 nicht, weil sie kein Aufwand sind.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Teil 3 Summenzeile nachrechnen: −600.000 + 940.000 = 340.000; − 480.000 = −140.000; − 8.000 − 24.000 = −172.000. Passt zur Tabelle.</p>\n<p class=\"merke\"><b>Merke:</b> Entnahmen sind Zahlungen und Ausgaben, aber nie Aufwand.</p>","short":"Summen: Zahlungen −292.000; Einnahme-Ausgabe −292.000; Einkommen −172.000","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 1.3 (Präsenzübung ab 19.10.))"},{"id":"bure-t17","topic":"bure-zwecke","level":3,"type":"open","q":"Möbelschreinerei, Geschäftsjahr 20X1: a) Rohstoffe für {{Ra}} bar eingekauft und vollständig verbraucht. b) Fertigungsmaterial für {{Fm}} eingekauft und verbraucht; die Hälfte bar, die andere Hälfte mit Zahlungsziel 20X2. c) Hilfs- und Betriebsstoffe für {{Hb}} eingekauft und verbraucht, Zahlungsziel 20X2. d) Löhne von {{Lo}} überwiesen. e) Rohstoffe für {{Rl}} bar gekauft, sie liegen noch im Lager. f) Abschreibung auf Maschinen {{Ab}}. g) Alle Möbel für {{Um}} verkauft, davon {{Up}} schon bezahlt, der Rest folgt 20X2. h) Entnahme von {{Ent}} aus der Kasse. i) Kredit: Rückzahlung {{Kr}} in 20X4, Disagio {{Dis}} (Auszahlung Anfang 20X1 abzüglich Disagio), Zinsen {{zp}} % des Rückzahlungsbetrags pro Jahr. j) Einlage {{Ein}}.<br>1. Stelle die Einzahlungs-Auszahlungs-Rechnung auf. 2. Leite daraus den Saldo (a) der Einnahme-Ausgabe-Rechnung und (b) der Ertrags-Aufwands-Rechnung ab. 3. Unterscheiden sich beide Salden in der Totalbetrachtung? Um wie viel?","a":"<p class=\"goal\"><b>Ziel:</b> Aus den Zahlungen den Einzahlungsüberschuss berechnen und daraus Einnahme-Ausgabe-Saldo und Einkommen ableiten.</p>\n<ol class=\"sol-steps\">\n<li>Vorab: bezahlter Umsatz {{Um}} − {{Of}} = {{Up}}. Material bar: {{Fm}} / 2 = {{Fh}}. Kredit-Auszahlung: {{Kr}} − {{Dis}} = {{Kn}}. Zinsen: {{zp}} % × {{Kr}} = {{Kr}} / 100 · {{zp}} = {{Zi}}.<span class=\"why\">Warum: Diese Teilbeträge brauchst du gleich mehrmals. Disagio heißt: Die Bank zahlt weniger aus, als du zurückzahlen musst. Der Unterschied ist ein Preis für den Kredit.</span></li>\n<li><b>Teil 1.</b> Einzahlungen: {{Up}} + {{Kn}} + {{Ein}} = <b>{{Ez}}</b>.<span class=\"why\">Warum: Nur Geld, das 20X1 wirklich ankommt: Kundenzahlungen, Kredit (ohne Disagio) und Einlage.</span></li>\n<li>Auszahlungen: {{Ra}} + {{Fh}} + {{Lo}} + {{Rl}} + {{Ent}} + {{Zi}} = <b>{{Az}}</b>.<span class=\"why\">Warum: Alles, was 20X1 abfließt. Hilfs- und Betriebsstoffe (Ziel 20X2) und Abschreibung sind keine Zahlungen.</span></li>\n<li>Einzahlungsüberschuss: {{Ez}} − {{Az}} = <b>{{U}}</b>.<span class=\"why\">Warum: Im Alltag: um so viel ist der Kontostand im Jahr gestiegen.</span></li>\n<li><b>Teil 2a.</b><table class=\"tt\"><tr><td>Einzahlungsüberschuss</td><td>{{U}}</td></tr><tr><td>+ Forderungen aus Verkauf (g)</td><td>+{{Of}}</td></tr><tr><td>− Material auf Ziel (b)</td><td>−{{Fh}}</td></tr><tr><td>− Hilfs- und Betriebsstoffe auf Ziel (c)</td><td>−{{Hb}}</td></tr><tr><td>− Kredit: Einzahlung {{Kn}} ist keine Einnahme, Schuld {{Kr}} entsteht</td><td>−{{Kr}}</td></tr><tr><th>Einnahme-Ausgabe-Saldo</th><th>{{EAm}}</th></tr></table><span class=\"why\">Warum: Einnahme-Ausgabe zählt das Geldvermögen: Forderungen kommen dazu, neue Schulden gehen ab. Beim Kredit stecken {{Kn}} schon im Überschuss, die Schuld ist aber {{Kr}}. Darum ziehst du {{Kr}} ab; netto bleibt das Disagio −{{Dis}} als Ausgabe.</span></li>\n<li><b>Teil 2b.</b><table class=\"tt\"><tr><td>Einnahme-Ausgabe-Saldo</td><td>{{EAm}}</td></tr><tr><td>+ Entnahme: Ausgabe, aber kein Aufwand</td><td>+{{Ent}}</td></tr><tr><td>− Einlage: Einnahme, aber kein Ertrag</td><td>−{{Ein}}</td></tr><tr><td>+ Rohstoffe auf Lager: Ausgabe, noch kein Aufwand</td><td>+{{Rl}}</td></tr><tr><td>− Abschreibung: Aufwand ohne Ausgabe</td><td>−{{Ab}}</td></tr><tr><th>Ertrags-Aufwands-Saldo ({{Y>=0?'Gewinn':'Verlust'}})</th><th>{{Ym}}</th></tr></table><span class=\"why\">Warum: Transfers mit dem Inhaber sind kein Einkommen, darum werden sie herausgerechnet. Lager ist noch Vermögen, Abschreibung ist Wertverlust ohne Zahlung. Das Disagio bleibt hier wie in der Kurzlösung voll in 20X1; verteilt auf vier Jahre käme mehr heraus.</span></li>\n<li><b>Teil 3.</b> Über die ganze Lebensdauer unterscheiden sich beide Salden nur um die Transfers: −{{Ent}} + {{Ein}} = −{{Td}}. Der Einnahme-Ausgabe-Saldo ist um <b>{{Td}}</b> niedriger.<span class=\"why\">Warum: Lager, Forderungen, Schulden und Abschreibung gleichen sich über die ganze Zeit aus. Nur Einlagen und Entnahmen zählen beim Einnahme-Ausgabe-Saldo mit, beim Einkommen nie.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Einkommen direkt: Ertrag {{Um}} − Aufwand ({{Ra}} + {{Fm}} + {{Hb}} + {{Lo}} + {{Ab}} + {{Zi}} + {{Dis}}) = {{Um}} − {{Ra+Fm+Hb+Lo+Ab+Zi+Dis}} = {{Ym}}. Gleiches Ergebnis.</p>\n<p class=\"merke\"><b>Merke:</b> Kredit, Tilgung, Kundenzahlung und Schuldenbezahlung sind nur Zahlungen; Einkommen entsteht durch Verkaufen und Verbrauchen.</p>","short":"{{U}}; {{EAm}}; {{Ym}}; Total-Differenz {{Td}} (Transfers)","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 1.4)","gen":{"vars":{"Ra":{"min":5000,"max":15000,"step":1000},"Fm":{"min":20000,"max":60000,"step":2000,"not":[40000]},"Hb":{"min":5000,"max":20000,"step":1000},"Lo":{"min":20000,"max":40000,"step":1000},"Rl":{"min":2000,"max":6000,"step":500},"Ab":{"min":5000,"max":15000,"step":1000},"Um":{"min":100000,"max":200000,"step":10000,"not":[150000]},"Of":{"min":20000,"max":80000,"step":10000},"Ent":{"min":10000,"max":25000,"step":1000},"Kr":{"min":50000,"max":150000,"step":10000},"dp":[5,8,10],"zp":[4,5,6],"Ein":{"min":2000,"max":10000,"step":1000}},"let":{"Fh":"Fm/2","Dis":"Kr*dp/100","Kn":"Kr-Dis","Zi":"Kr*zp/100","Up":"Um-Of","Ez":"Up+Kn+Ein","Az":"Ra+Fh+Lo+Rl+Ent+Zi","U":"Ez-Az","EA":"U+Of-Fh-Hb-Kr","Y":"EA+Ent-Ein+Rl-Ab","Td":"Ent-Ein","EAm":"(EA<0?'−':'')+num(abs(EA))","Ym":"(Y<0?'−':'')+num(abs(Y))"},"check":"Of < Um && Ein < Ent && Y != 0 && U > 0"}},{"id":"bure-t18","topic":"bure-ek","level":2,"type":"open","q":"„Ingenieurbüro Krämer“, September 20X1: a) Einlage {{E}} bar. b) Büromaterial für {{Bm}} auf Rechnung gekauft. c) Grundstück für {{Gr}} bar gekauft. d) Beratungshonorare {{Pr}} bar erhalten. e) {{Tz}} der Rechnung aus b bezahlt. f) Privaturlaub für {{Ur}} aus der Firmenkasse bezahlt. g) Büromiete {{Mi}} und sonstige Dienstleistungen {{Dl}} bar bezahlt. h) Büromaterial für {{Vk}} bar weiterverkauft (Einkaufswert {{Ek}}). i) Entnahme {{Ent}}.<br>1. Zeige die Wirkung jedes Vorfalls auf die Bilanzgleichung (Salden nach dem letzten Vorfall). 2. Ordne Ertrag und Aufwand den Einkommenskonzepten zu. 3. Stelle Einkommensrechnung, Transferrechnung, Veränderungsrechnung und Bilanz auf.","a":"<p class=\"goal\"><b>Ziel:</b> Die Ereignisse im „Ingenieurbüro Krämer“ in der Bilanzgleichung abbilden, den Konzepten zuordnen und die Berichte aufstellen.</p>\n<ol class=\"sol-steps\">\n<li>a) ZM +{{E}}, EK +{{E}} (Einlage). b) Büromaterial +{{Bm}}, Verbindlichkeiten +{{Bm}}. c) ZM −{{Gr}}, Grundstück +{{Gr}}.<span class=\"why\">Warum: Einlage = Transfer vom Inhaber. Kauf auf Rechnung erzeugt eine Schuld. Barkauf ist ein Tausch Geld gegen Grundstück.</span></li>\n<li>d) ZM +{{Pr}}, EK +{{Pr}} (Ertrag). e) ZM −{{Tz}}, Verbindlichkeiten −{{Tz}}.<span class=\"why\">Warum: Honorare sind verdient, also Ertrag. Teilzahlung: Geld und Schuld sinken gleich, EK bleibt.</span></li>\n<li>f) ZM −{{Ur}}, EK −{{Ur}} (Entnahme). g) Miete + Dienstleistungen {{Mi}} + {{Dl}} = {{GD}}: ZM −{{GD}}, EK −{{GD}} (Aufwand).<span class=\"why\">Warum: Der Urlaub ist privat: Transfer. Miete und Dienstleistungen sind verbraucht: Aufwand.</span></li>\n<li>h) ZM +{{Vk}}, Büromaterial −{{Ek}}. EK +{{Vk}} − {{Ek}} = +{{Vk-Ek}} (Ertrag {{Vk}}, Aufwand {{Ek}}). i) ZM −{{Ent}}, EK −{{Ent}} (Entnahme).<span class=\"why\">Warum: Beim Verkauf kommt der Preis als Ertrag rein, das abgegebene Material geht zum Einkaufswert als Aufwand raus.</span></li>\n<li><table class=\"tt\"><tr><th></th><th>ZM</th><th>Büromat.</th><th>Grundst.</th><th>Verb.</th><th>EK</th><th>EK-Art</th></tr><tr><td>a</td><td>+{{E}}</td><td></td><td></td><td></td><td>+{{E}}</td><td>Einlage</td></tr><tr><td>b</td><td></td><td>+{{Bm}}</td><td></td><td>+{{Bm}}</td><td></td><td></td></tr><tr><td>c</td><td>−{{Gr}}</td><td></td><td>+{{Gr}}</td><td></td><td></td><td></td></tr><tr><td>d</td><td>+{{Pr}}</td><td></td><td></td><td></td><td>+{{Pr}}</td><td>Ertrag</td></tr><tr><td>e</td><td>−{{Tz}}</td><td></td><td></td><td>−{{Tz}}</td><td></td><td></td></tr><tr><td>f</td><td>−{{Ur}}</td><td></td><td></td><td></td><td>−{{Ur}}</td><td>Entnahme</td></tr><tr><td>g</td><td>−{{GD}}</td><td></td><td></td><td></td><td>−{{GD}}</td><td>Aufwand</td></tr><tr><td>h</td><td>+{{Vk}}</td><td>−{{Ek}}</td><td></td><td></td><td>+{{Vk-Ek}}</td><td>Ertrag {{Vk}}, Aufwand {{Ek}}</td></tr><tr><td>i</td><td>−{{Ent}}</td><td></td><td></td><td></td><td>−{{Ent}}</td><td>Entnahme</td></tr><tr><td><b>EB</b></td><td><b>{{ZM}}</b></td><td><b>{{BM}}</b></td><td><b>{{Gr}}</b></td><td><b>{{VB}}</b></td><td><b>{{EK}}</b></td><td></td></tr></table><span class=\"why\">Warum: Endbestand je Spalte = alle Plus minus alle Minus. Zum Beispiel Büromaterial {{Bm}} − {{Ek}} = {{BM}}, Verbindlichkeiten {{Bm}} − {{Tz}} = {{VB}}. (Teil 1 und 2 werden in der Übung erarbeitet, dies ist ein Vorschlag.)</span></li>\n<li>2. Honorare (d) und Verkauf (h): Marktleistungsabgabe. Miete und Dienstleistungen (g): Periodisierung.<span class=\"why\">Warum: Honorare und Verkauf entstehen, wenn die Leistung an den Kunden geht. Miete gehört zu keinem Produkt, sondern zur Zeit.</span></li>\n<li>3. Erträge {{Pr}} + {{Vk}} = {{Er}}. Aufwand {{Ek}} + {{Mi}} + {{Dl}} = {{Aw}}. Einkommen {{Er}} − {{Aw}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Einkommen ist der Gewinn im September.</span></li>\n<li>Transfer: {{E}} − ({{Ur}} + {{Ent}}) = {{E}} − {{En}} = <b>{{Tr}}</b>. EK 30.9.: 0 + {{Tr}} + {{Y}} = <b>{{EK}}</b>.<span class=\"why\">Warum: Urlaub und Entnahme sind beide Entnahmen. Das EK am Monatsende besteht aus Transfers plus Einkommen.</span></li>\n<li>Bilanz: ZM {{ZM}} + Büromaterial {{BM}} + Grundstück {{Gr}} = <b>{{AS}}</b> = Verbindlichkeiten {{VB}} + EK {{EK}}.<span class=\"why\">Warum: Aktiva = Passiva am Stichtag 30.9.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Passiva {{VB}} + {{EK}} = {{VB+EK}}, Aktiva {{AS}}. Die Bilanz geht auf.</p>\n<p class=\"merke\"><b>Merke:</b> Urlaub aus der Firmenkasse ist eine Entnahme, kein Aufwand.</p>","short":"Einkommen {{Y}}; Transfer {{Tr}}; EK {{EK}}; Bilanzsumme {{AS}}","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 2.1 (Präsenzübung ab 26.10.))","gen":{"vars":{"E":{"min":50000,"max":100000,"step":5000,"not":[70000]},"Bm":{"min":500,"max":1200,"step":100},"Gr":{"min":40000,"max":80000,"step":5000},"Pr":{"min":2000,"max":6000,"step":100},"Tz":{"min":100,"max":1000,"step":50},"Ur":{"min":2000,"max":6000,"step":500},"Mi":{"min":500,"max":1200,"step":50},"Dl":{"min":100,"max":400,"step":50},"Vk":{"min":200,"max":600,"step":50},"Ek":{"min":100,"max":500,"step":50},"Ent":{"min":1000,"max":4000,"step":100}},"let":{"GD":"Mi+Dl","ZM":"E-Gr+Pr-Tz-Ur-GD+Vk-Ent","BM":"Bm-Ek","VB":"Bm-Tz","Er":"Pr+Vk","Aw":"Ek+Mi+Dl","Y":"Er-Aw","En":"Ur+Ent","Tr":"E-En","EK":"Tr+Y","AS":"ZM+BM+Gr"},"check":"Gr <= E-10000 && Tz < Bm && Ek < Vk && Ek < Bm && ZM > 0 && Y > 0"}},{"id":"bure-t19","topic":"bure-ek","level":2,"type":"open","q":"Barmittel am 1.4.20X1: {{Z0}} (davon {{F0}} von Fremden geliehen, {{E0}} vom Inhaber eingelegt). Im April: Darlehen über {{D}} aufgenommen, Einlage {{Ei}} bar, Baugrundstück für {{G}} bar gekauft, ein Wertpapier für {{Ak}} bar gekauft und später für {{Av}} bar wieder verkauft; das Baugrundstück ist Ende April {{W}} wert. Barmittel am 30.4.: {{Z1}}.<br>1. Berechne die Veränderung der Zahlungsmittel aus den Beständen. 2. Berechne dieselbe Veränderung aus Ein- und Auszahlungen. 3. Stelle die Bestandsrechnung der Zahlungsmittel aus Sicht aller Kapitalgeber auf. 4. Stelle sie getrennt nach Eigen- und Fremdkapital auf (1.4. und 30.4.).","a":"<p class=\"goal\"><b>Ziel:</b> Die Veränderung der Barmittel auf zwei Wegen berechnen und die Kapitalgeber aufteilen.</p>\n<ol class=\"sol-steps\">\n<li>1. Aus den Beständen: {{Z1}} − {{Z0}} = <b>{{dZs}}</b>.<span class=\"why\">Warum: Veränderung = Endbestand minus Anfangsbestand.</span></li>\n<li>2. Einzahlungen: {{D}} + {{Ei}} + {{Av}} = {{Ez}}. Auszahlungen: {{G}} + {{Ak}} = {{Az}}.<span class=\"why\">Warum: Darlehen, Einlage und Verkauf des Wertpapiers bringen Geld. Kauf des Baugrundstücks und Kauf des Wertpapiers kosten Geld. Die Wertsteigerung des Baugrundstücks ist keine Zahlung, denn es fließt kein Geld.</span></li>\n<li>Überschuss: {{Ez}} − {{Az}} = <b>{{dZs}}</b>.<span class=\"why\">Warum: Beide Wege müssen dasselbe ergeben, denn Bestand ändert sich nur durch Zahlungen.</span></li>\n<li>3. Sicht aller Kapitalgeber: 1.4. Barmittel {{Z0}} = Kapital {{Z0}}. 30.4. Barmittel {{Z1}} = Kapital {{Z1}}.<span class=\"why\">Warum: Wenn man nur Barmittel betrachtet, gehört jeder Euro irgendeinem Kapitalgeber. Darum sind beide Seiten gleich.</span></li>\n<li>4. FK am 30.4.: {{F0}} + {{D}} = <b>{{F1}}</b>. EK: {{Z1}} − {{F1}} = <b>{{E1}}</b>.<table class=\"tt\"><tr><th></th><th>Barmittel</th><th>FK</th><th>EK</th></tr><tr><td>1.4.</td><td>{{Z0}}</td><td>{{F0}}</td><td>{{E0}}</td></tr><tr><td>30.4.</td><td>{{Z1}}</td><td>{{F1}}</td><td>{{E1}}</td></tr></table><span class=\"why\">Warum: Das neue Darlehen erhöht das FK. Das EK ist der Rest: Barmittel minus Schulden. (Teil 5–7 werden in der Übung erarbeitet.)</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> FK + EK am 30.4.: {{F1}} + {{E1}} = {{F1+E1}} = Barmittel {{Z1}}.</p>\n<p class=\"merke\"><b>Merke:</b> Eine Wertsteigerung ist keine Zahlung und ändert die Barmittel nicht.</p>","short":"{{dZs}}; 30.4.: FK {{F1}}, EK {{E1}}","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 2.3 Teil 1–4 (Präsenzübung ab 26.10.))","gen":{"vars":{"F0":{"min":1000,"max":3000,"step":100,"not":[1500]},"E0":{"min":1000,"max":3000,"step":100},"D":{"min":300,"max":1500,"step":100},"Ei":{"min":1000,"max":4000,"step":500},"G":{"min":1500,"max":3500,"step":100},"Ak":{"min":200,"max":800,"step":100},"Av":{"min":50,"max":750,"step":50},"up":{"min":200,"max":1000,"step":100}},"let":{"Z0":"F0+E0","W":"G+up","Ez":"D+Ei+Av","Az":"G+Ak","Z1":"Z0+Ez-Az","dZ":"Z1-Z0","F1":"F0+D","E1":"Z1-F1","dZs":"(dZ<0?'−':'+')+num(abs(dZ))"},"check":"Av < Ak && E1 > 0 && dZ != 0"}},{"id":"bure-t20","topic":"bure-konten","level":1,"type":"open","q":"Entscheide jeweils: Wird im Konto im Soll oder im Haben gebucht? a) Zugang Zahlungsmittel. b) Abgang Grundstück. c) Zugang Verbindlichkeit. d) Abgang Verbindlichkeit. e) Aufwand entsteht. f) Ertrag entsteht. g) Entnahme. h) Einlage. Welche Seite ist bei Vermögenskonten normal größer, welche bei Ertragskonten?","a":"<p class=\"goal\"><b>Ziel:</b> Für jeden Vorgang die richtige Kontoseite bestimmen.</p>\n<ol class=\"sol-steps\">\n<li>Regel für Konten: Aktivkonten (Vermögen) buchen Zugänge im Soll (links) und Abgänge im Haben (rechts). Passivkonten (Schulden, Eigenkapital) machen es genau umgekehrt: Zugang im Haben, Abgang im Soll. Der Buchungssatz heißt immer „Soll an Haben“: zuerst das Soll-Konto, dann „an“ das Haben-Konto, beide mit demselben Betrag.<span class=\"why\">Warum: Aktiva stehen in der Bilanz links, also wachsen sie links (Soll). Passiva stehen rechts, also wachsen sie rechts (Haben).</span></li>\n<li>a) Zugang Zahlungsmittel → <b>Soll</b>. b) Abgang Grundstück → <b>Haben</b>.<span class=\"why\">Warum: Zahlungsmittel und Grundstück sind Aktivkonten. Zugang also Soll, Abgang Haben.</span></li>\n<li>c) Zugang Verbindlichkeit → <b>Haben</b>. d) Abgang Verbindlichkeit → <b>Soll</b>.<span class=\"why\">Warum: Verbindlichkeiten sind Fremdkapital, also ein Passivkonto. Zugang Haben, Abgang Soll.</span></li>\n<li>e) Aufwand → <b>Soll</b>. g) Entnahme → <b>Soll</b>.<span class=\"why\">Warum: Aufwand und Entnahme sind Unterkonten des Eigenkapitals. Sie verringern das EK, und ein Abgang beim Passivkonto EK steht im Soll.</span></li>\n<li>f) Ertrag → <b>Haben</b>. h) Einlage → <b>Haben</b>.<span class=\"why\">Warum: Ertrag und Einlage erhöhen das EK. Zugang beim Passivkonto EK steht im Haben.</span></li>\n<li>Saldo: Vermögenskonten und Aufwandskonten haben meist mehr im Soll (Soll-Saldo). FK-, EK- und Ertragskonten haben mehr im Haben (Haben-Saldo).<span class=\"why\">Warum: Bei Vermögen kommt mehr dazu, als abgeht, sonst wäre es negativ. Ein Ertragskonto sammelt nur Erträge, also nur Haben-Buchungen.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Prüfe mit einem Buchungssatz: Einlage bar ist „Zahlungsmittel an Eigenkapital (Einlage)“. Zahlungsmittel Soll (a), Einlage Haben (h). Passt.</p>\n<p class=\"merke\"><b>Merke:</b> Alles, was das EK erhöht (Ertrag, Einlage), steht im Haben; alles, was es mindert (Aufwand, Entnahme), im Soll. <i>(Folien 18–19, 26; Verständniskontrolle Folie 41, Frage 10)</i></p>","short":"a S · b H · c H · d S · e S · f H · g S · h H","diag":false,"src":"eigene"},{"id":"bure-t21","topic":"bure-konten","level":1,"type":"open","q":"Entscheide für jedes Ereignis: Geschäftsvorfall, anderes relevantes Ereignis oder gar nicht buchen?<br/> a) Eingangsrechnung für Büromaterial. b) Planmäßige Abschreibung einer Maschine am 31.12. c) Überweisung der Miete. d) Die Geschäftsführung beschließt, nächstes Jahr einen Lkw zu kaufen. e) Ein Kunde zahlt bar.","a":"<p class=\"goal\"><b>Ziel:</b> Entscheiden, ob ein Ereignis ein Geschäftsvorfall, ein anderes relevantes Ereignis oder gar nicht zu buchen ist.</p>\n<ol class=\"sol-steps\">\n<li>Unterschied: Ein <b>Geschäftsvorfall</b> ist ein physischer oder rechtlicher Vorgang, meist mit Beleg. Ein <b>anderes relevantes Ereignis</b> ändert Vermögen oder Schulden ohne so einen Vorgang. <b>Nichts</b> bucht man, wenn sich jetzt nichts finanziell ändert.<span class=\"why\">Warum: Buchhaltung bildet nur Dinge ab, die Vermögen oder Kapital heute ändern.</span></li>\n<li>a) Eingangsrechnung Büromaterial → Geschäftsvorfall.<span class=\"why\">Warum: Die Rechnung ist ein Beleg: Material kommt, eine Schuld entsteht.</span></li>\n<li>b) Planmäßige Abschreibung → anderes relevantes Ereignis (beleglose Buchung).<span class=\"why\">Warum: Die Maschine verliert Wert, aber niemand schickt eine Rechnung. Gebucht wird trotzdem, ohne Beleg (Thema Kapitel 5).</span></li>\n<li>c) Mietüberweisung → Geschäftsvorfall. e) Kunde zahlt bar → Geschäftsvorfall.<span class=\"why\">Warum: Geld fließt wirklich, dafür gibt es Kontoauszug oder Quittung.</span></li>\n<li>d) Beschluss, nächstes Jahr einen Lkw zu kaufen → nicht buchen.<span class=\"why\">Warum: Ein Plan ändert heute weder Vermögen noch Schulden.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Ohne finanzielle Folge heute gibt es keine Buchung, egal wie wichtig der Plan ist. <i>(Folie 11, Folie 37; Verständniskontrolle Folie 40, Frage 2)</i></p>","short":"a, c, e Geschäftsvorfall · b anderes relevantes Ereignis · d nicht buchen","diag":false,"src":"eigene"},{"id":"bure-t22","topic":"bure-konten","level":2,"type":"open","q":"Bilde die Buchungssätze. a) Grundstück für {{A}} bar gekauft. b) Material für {{Mb}} auf Ziel. c) Lieferantenschuld {{Mc}} per Überweisung bezahlt. d) Lieferantenschuld {{Md}} wird in ein Bankdarlehen umgewandelt. e) Kunde zahlt Forderung {{Me}} bar. f) Inhaber legt {{Mf}} bar ein. g) Miete {{Mg}} bar. h) Inhaber entnimmt {{Mh}} bar.","a":"<p class=\"goal\"><b>Ziel:</b> Für jeden Vorgang den Buchungssatz bilden und begründen, welches Konto ins Soll und welches ins Haben kommt.</p>\n<ol class=\"sol-steps\">\n<li>Regel für Konten: Aktivkonten (Vermögen) buchen Zugänge im Soll (links) und Abgänge im Haben (rechts). Passivkonten (Schulden, Eigenkapital) machen es genau umgekehrt: Zugang im Haben, Abgang im Soll. Der Buchungssatz heißt immer „Soll an Haben“: zuerst das Soll-Konto, dann „an“ das Haben-Konto, beide mit demselben Betrag.<span class=\"why\">Warum: Mit dieser Regel prüfst du jedes Konto einzeln: Was für ein Konto ist es, nimmt es zu oder ab?</span></li>\n<li>a) <b>Grundstücke an Zahlungsmittel {{A}}</b>.<span class=\"why\">Warum: Grundstück ist ein Aktivkonto und nimmt zu, also Soll. Zahlungsmittel ist ein Aktivkonto und nimmt ab, also Haben.</span></li>\n<li>b) <b>Material an Verbindlichkeiten (Einkauf) {{Mb}}</b>.<span class=\"why\">Warum: Material ist ein Aktivkonto und nimmt zu, also Soll. Verbindlichkeiten sind ein Passivkonto und nehmen zu, also Haben.</span></li>\n<li>c) <b>Verbindlichkeiten (Einkauf) an Zahlungsmittel {{Mc}}</b>.<span class=\"why\">Warum: Die Schuld (Passivkonto) nimmt ab, also Soll. Zahlungsmittel (Aktivkonto) nimmt ab, also Haben.</span></li>\n<li>d) <b>Verbindlichkeiten (Einkauf) an Verbindlichkeiten (Bank) {{Md}}</b>.<span class=\"why\">Warum: Lieferantenschuld (Passiv) nimmt ab, also Soll. Bankschuld (Passiv) nimmt zu, also Haben.</span></li>\n<li>e) <b>Zahlungsmittel an Forderungen (Verkauf) {{Me}}</b>.<span class=\"why\">Warum: Zahlungsmittel (Aktiv) nimmt zu, also Soll. Forderung (Aktiv) nimmt ab, also Haben.</span></li>\n<li>f) <b>Zahlungsmittel an Eigenkapital (Einlage) {{Mf}}</b>.<span class=\"why\">Warum: Zahlungsmittel (Aktiv) nimmt zu, also Soll. Eigenkapital (Passiv) nimmt zu, also Haben.</span></li>\n<li>g) <b>Aufwand (Miete) an Zahlungsmittel {{Mg}}</b>. h) <b>Eigenkapital (Entnahme) an Zahlungsmittel {{Mh}}</b>.<span class=\"why\">Warum: Aufwand und Entnahme mindern das EK (Passiv nimmt ab), also Soll. Zahlungsmittel (Aktiv) nimmt ab, also Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> In jeder Zeile steht derselbe Betrag im Soll und im Haben. Nur dann bleibt die Bilanz im Gleichgewicht.</p>\n<p class=\"merke\"><b>Merke:</b> Zuerst immer fragen: Aktiv- oder Passivkonto? Dann: Zugang oder Abgang? Daraus folgt die Seite. <i>(Übungsskript 3.2 (S. 20), 3.1 (S. 17))</i></p>","short":"a Grundstücke an ZM {{A}} … h EK (Entnahme) an ZM {{Mh}}","diag":false,"src":"eigene","gen":{"vars":{"A":{"min":20000,"max":90000,"step":5000},"Mb":{"min":1000,"max":6000,"step":500},"Mc":{"min":500,"max":4000,"step":100},"Md":{"min":5000,"max":20000,"step":1000},"Me":{"min":500,"max":3000,"step":100},"Mf":{"min":2000,"max":10000,"step":500},"Mg":{"min":400,"max":1500,"step":50},"Mh":{"min":500,"max":2500,"step":100}}}},{"id":"bure-t23","topic":"bure-konten","level":2,"type":"open","q":"Führe das T-Konto Zahlungsmittel. Anfangsbestand {{AB}}. Danach: Einlage {{Ei}}, Miete {{Mi}}, Kunde zahlt {{Ku}}, Tilgung Lieferantenschuld {{Ti}}, Entnahme {{En}}, Dienstleistung bar {{Dl}}. Wie hoch ist der Endbestand? Auf welcher Seite steht der Saldo im Konto?","a":"<p class=\"goal\"><b>Ziel:</b> Das T-Konto Zahlungsmittel führen und den Endbestand berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Zahlungsmittel ist ein Aktivkonto: Anfangsbestand und Zugänge ins <b>Soll</b> (links), Abgänge ins <b>Haben</b> (rechts).<span class=\"why\">Warum: Aktiva stehen in der Bilanz links, darum steht auch ihr Anfangsbestand links im Konto.</span></li>\n<li>Soll: AB {{AB}}, Einlage {{Ei}}, Kunde {{Ku}}, Dienstleistung {{Dl}}. Summe {{AB}} + {{Ei}} = {{AB+Ei}}; + {{Ku}} = {{AB+Ei+Ku}}; + {{Dl}} = <b>{{SS}}</b>.<span class=\"why\">Warum: Das sind alle Vorgänge, bei denen Geld hereinkommt.</span></li>\n<li>Haben: Miete {{Mi}}, Tilgung {{Ti}}, Entnahme {{En}}. Summe {{Mi}} + {{Ti}} + {{En}} = <b>{{SH}}</b>.<span class=\"why\">Warum: Das sind alle Vorgänge, bei denen Geld hinausgeht.</span></li>\n<li>Endbestand: {{SS}} − {{SH}} = <b>{{EB}}</b>.<span class=\"why\">Warum: Was hereinkam minus was hinausging. Im Alltag: so viel Geld ist am Ende noch da.</span></li>\n<li><table class=\"tt\"><tr><th colspan=\"2\">Soll</th><th colspan=\"2\">Zahlungsmittel · Haben</th></tr><tr><td>AB</td><td>{{AB}}</td><td>Miete</td><td>{{Mi}}</td></tr><tr><td>Einlage</td><td>{{Ei}}</td><td>Tilgung</td><td>{{Ti}}</td></tr><tr><td>Kunde</td><td>{{Ku}}</td><td>Entnahme</td><td>{{En}}</td></tr><tr><td>Dienstleistung</td><td>{{Dl}}</td><td>Saldo (EB)</td><td>{{EB}}</td></tr><tr><th>Summe</th><th>{{SS}}</th><th>Summe</th><th>{{SS}}</th></tr></table><span class=\"why\">Warum: Es ist ein Soll-Saldo (Soll ist größer). Damit beide Seiten gleich groß werden, schreibt man ihn zum Ausgleich auf die Haben-Seite.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Haben-Seite mit Saldo: {{SH}} + {{EB}} = {{SH+EB}} = Soll-Summe {{SS}}.</p>\n<p class=\"merke\"><b>Merke:</b> Der Saldo steht immer auf der kleineren Seite, damit das Konto aufgeht. <i>(Folien 13–15, 26)</i></p>","short":"Endbestand {{EB}} (Soll-Saldo)","diag":false,"src":"eigene","gen":{"vars":{"AB":{"min":10000,"max":50000,"step":1000},"Ei":{"min":2000,"max":8000,"step":500},"Mi":{"min":500,"max":1500,"step":50},"Ku":{"min":500,"max":3000,"step":100},"Ti":{"min":1000,"max":4000,"step":100},"En":{"min":500,"max":2000,"step":100},"Dl":{"min":2000,"max":6000,"step":100}},"let":{"SS":"AB+Ei+Ku+Dl","SH":"Mi+Ti+En","EB":"SS-SH"}}},{"id":"bure-t24","topic":"bure-konten","level":2,"type":"open","q":"Kurierdienst „Radkurier Aachen“ startet am 1.5.: a) Einlage {{E}} bar. b) Lastenrad für {{B}} bar (Betriebs- und Geschäftsausstattung). c) Büromaterial {{Bm}} auf Ziel. d) Bankdarlehen {{D}}. e) {{Tz}} der Büromaterial-Rechnung bezahlt. f) Entnahme {{En}}.<br/> Erstelle: 1. das Journal (Buchungssätze), 2. die T-Konten, 3. die vorläufige Saldenaufstellung.","a":"<p class=\"goal\"><b>Ziel:</b> Für „Radkurier Aachen“ Journal, T-Konten und vorläufige Saldenaufstellung erstellen.</p>\n<ol class=\"sol-steps\">\n<li>a) <b>Zahlungsmittel an Eigenkapital (Einlage) {{E}}</b>.<span class=\"why\">Warum: Zahlungsmittel (Aktiv) nimmt zu, also Soll. EK (Passiv) nimmt zu, also Haben.</span></li>\n<li>b) <b>BGA an Zahlungsmittel {{B}}</b>.<span class=\"why\">Warum: BGA heißt Betriebs- und Geschäftsausstattung (Aktiv) und nimmt zu, also Soll. Zahlungsmittel nimmt ab, also Haben.</span></li>\n<li>c) <b>Büromaterial an Verbindlichkeiten (Einkauf) {{Bm}}</b>. d) <b>Zahlungsmittel an Verbindlichkeiten (Bank) {{D}}</b>.<span class=\"why\">Warum: Büromaterial und Zahlungsmittel (Aktiv) nehmen zu, also Soll. Die Schulden (Passiv) nehmen zu, also Haben.</span></li>\n<li>e) <b>Verbindlichkeiten (Einkauf) an Zahlungsmittel {{Tz}}</b>. f) <b>Eigenkapital (Entnahme) an Zahlungsmittel {{En}}</b>.<span class=\"why\">Warum: Schuld (Passiv) nimmt ab, also Soll. Entnahme mindert das EK, also Soll. Zahlungsmittel nimmt jeweils ab, also Haben.</span></li>\n<li>T-Konto Zahlungsmittel: Soll {{E}} + {{D}} = {{ZS}}. Haben {{B}} + {{Tz}} + {{En}} = {{ZH}}. Saldo {{ZS}} − {{ZH}} = <b>{{Zs}}</b>. Verbindlichkeiten (Einkauf): Haben {{Bm}}, Soll {{Tz}}, Saldo {{Bm}} − {{Tz}} = <b>{{VB}}</b> im Haben.<span class=\"why\">Warum: Jeder Journalbetrag wird auf sein Konto übertragen, Soll links, Haben rechts. Die anderen Konten haben nur einen Eintrag, ihr Saldo ist dieser Betrag.</span></li>\n<li><table class=\"tt\"><tr><th>Konto</th><th>Summe Soll</th><th>Summe Haben</th><th>Saldo Soll</th><th>Saldo Haben</th></tr><tr><td>Zahlungsmittel</td><td>{{ZS}}</td><td>{{ZH}}</td><td>{{Zs}}</td><td></td></tr><tr><td>BGA</td><td>{{B}}</td><td></td><td>{{B}}</td><td></td></tr><tr><td>Büromaterial</td><td>{{Bm}}</td><td></td><td>{{Bm}}</td><td></td></tr><tr><td>Verbindlichkeiten (Einkauf)</td><td>{{Tz}}</td><td>{{Bm}}</td><td></td><td>{{VB}}</td></tr><tr><td>Verbindlichkeiten (Bank)</td><td></td><td>{{D}}</td><td></td><td>{{D}}</td></tr><tr><td>Eigenkapital (Einlage)</td><td></td><td>{{E}}</td><td></td><td>{{E}}</td></tr><tr><td>Eigenkapital (Entnahme)</td><td>{{En}}</td><td></td><td>{{En}}</td><td></td></tr><tr><th>Summe</th><th>{{SuS}}</th><th>{{SuS}}</th><th>{{SaS}}</th><th>{{SaS}}</th></tr></table><span class=\"why\">Warum: Die Saldenaufstellung listet alle Konten. Weil jede Buchung Soll und Haben gleich groß macht, müssen die Spaltensummen gleich sein.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Salden Haben: {{VB}} + {{D}} + {{E}} = {{VB+D+E}}. Salden Soll: {{Zs}} + {{B}} + {{Bm}} + {{En}} = {{SaS}}. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Gehen Summe Soll und Summe Haben nicht auf, ist irgendwo ein Buchungsfehler. <i>(Übungsskript 3.1 (S. 17) und 3.4 (S. 25))</i></p>","short":"Summen {{SuS}} = {{SuS}}; Salden {{SaS}} = {{SaS}}","diag":false,"src":"eigene","gen":{"vars":{"E":{"min":20000,"max":60000,"step":5000},"B":{"min":3000,"max":10000,"step":500},"Bm":{"min":800,"max":2500,"step":100},"D":{"min":5000,"max":20000,"step":1000},"Tz":{"min":500,"max":2400,"step":100},"En":{"min":1000,"max":4000,"step":500}},"let":{"ZS":"E+D","ZH":"B+Tz+En","Zs":"ZS-ZH","VB":"Bm-Tz","SuS":"ZS+B+Bm+Tz+En","SaS":"Zs+B+Bm+En"},"check":"Tz < Bm && Zs > 0"}},{"id":"bure-t25","topic":"bure-konten","level":2,"type":"open","q":"Büromaterial für {{x}} auf Ziel wurde versehentlich mit {{10*x}} gebucht: „Büromaterial an Verbindlichkeiten (Einkauf) {{10*x}}“. Fällt der Fehler in der Saldenaufstellung auf? Wie korrigierst du ihn?","a":"<p class=\"goal\"><b>Ziel:</b> Prüfen, ob ein Betragsfehler in der Saldenaufstellung auffällt, und ihn richtig korrigieren.</p>\n<ol class=\"sol-steps\">\n<li>Falsch gebucht: Büromaterial (Soll) {{10*x}} und Verbindlichkeiten (Haben) {{10*x}}.<span class=\"why\">Warum: Der Kontenaufbau stimmt (Aktiv zu → Soll, Schuld zu → Haben), nur der Betrag ist zehnmal zu groß.</span></li>\n<li>Saldenaufstellung: Soll und Haben sind beide um {{10*x}} − {{x}} = {{9*x}} zu hoch. → Der Fehler <b>fällt nicht auf</b>.<span class=\"why\">Warum: Die Saldenaufstellung prüft nur, ob Soll = Haben ist. Ist derselbe falsche Betrag auf beiden Seiten, bleibt die Gleichheit erhalten.</span></li>\n<li>Storno: <b>Verbindlichkeiten (Einkauf) an Büromaterial {{10*x}}</b>.<span class=\"why\">Warum: Stornieren heißt: dieselbe Buchung mit vertauschten Seiten. Das hebt die falsche Buchung genau auf.</span></li>\n<li>Neu richtig buchen: <b>Büromaterial an Verbindlichkeiten (Einkauf) {{x}}</b>.<span class=\"why\">Warum: Büromaterial (Aktiv) nimmt um {{x}} zu, also Soll. Die Schuld (Passiv) nimmt um {{x}} zu, also Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Büromaterial: +{{10*x}} − {{10*x}} + {{x}} = {{x}}. So soll es sein.</p>\n<p class=\"merke\"><b>Merke:</b> Man radiert nicht: Erst stornieren, dann richtig buchen, beides ins Journal und auf die Konten. <i>(Folie 33; Verständniskontrolle Folie 43, Frage 15)</i></p>","short":"Fällt nicht auf; Storno {{10*x}}, dann {{x}} richtig buchen","diag":false,"src":"eigene","gen":{"vars":{"x":[35,45,60,80,90,120,150,250]}}},{"id":"bure-t26","topic":"bure-konten","level":2,"type":"open","q":"Jonas Weber gründet am 1. März 20X1 sein „Vermessungsbüro“. a) 1.3.: Er zahlt {{E}} bar auf das Firmenkonto ein. b) 2.3.: Kauf eines Bürogebäudes für {{Ge}} per Überweisung. c) 3.3.: Büromaterial für {{Bm}} auf Ziel. d) 4.3.: Büromöbel für {{Mo}} bezahlt. e) 5.3.: Überweisung von {{Tz}} an den Lieferanten aus c. f) 6.3.: Privatentnahme {{En}}.<br>Erstelle 1. das Journal (Buchungssätze), 2. die Konten, 3. die vorläufige Saldenaufstellung am 10. März.","a":"<p class=\"goal\"><b>Ziel:</b> Für Jonas Webers „Vermessungsbüro“ Journal, Konten und Saldenaufstellung erstellen.</p>\n<ol class=\"sol-steps\">\n<li>a) 1.3. <b>Zahlungsmittel an Eigenkapital (Einlage) {{E}}</b>.<span class=\"why\">Warum: Zahlungsmittel (Aktiv) nimmt zu, also Soll. EK (Passiv) nimmt zu, also Haben.</span></li>\n<li>b) 2.3. <b>abn. Sachanlagen (Gebäude) an Zahlungsmittel {{Ge}}</b>. d) 4.3. <b>Möbel an Zahlungsmittel {{Mo}}</b>.<span class=\"why\">Warum: Gebäude und Möbel sind Vermögen (Aktiv) und nehmen zu, also Soll. Geld nimmt ab, also Haben. „abn.“ heißt abnutzbar: Das Gebäude verliert mit der Zeit an Wert.</span></li>\n<li>c) 3.3. <b>Büromaterial an Verbindlichkeiten (Einkauf) {{Bm}}</b>.<span class=\"why\">Warum: Büromaterial (Aktiv) zu, also Soll. Schuld (Passiv) zu, also Haben.</span></li>\n<li>e) 5.3. <b>Verbindlichkeiten (Einkauf) an Zahlungsmittel {{Tz}}</b>. f) 6.3. <b>Eigenkapital (Entnahme) an Zahlungsmittel {{En}}</b>.<span class=\"why\">Warum: Schuld (Passiv) nimmt ab, also Soll. Entnahme mindert das EK, also Soll. Geld nimmt ab, also Haben.</span></li>\n<li>Zahlungsmittel: Soll {{E}}. Haben {{Ge}} + {{Mo}} + {{Tz}} + {{En}} = {{ZH}}. Saldo {{E}} − {{ZH}} = <b>{{Zs}}</b>. Verbindlichkeiten: {{Bm}} − {{Tz}} = <b>{{VB}}</b> (Haben-Saldo).<span class=\"why\">Warum: Saldo = größere Seite minus kleinere Seite. Die übrigen Konten haben nur einen Eintrag.</span></li>\n<li><table class=\"tt\"><tr><th>Konto</th><th>Summe Soll</th><th>Summe Haben</th><th>Saldo Soll</th><th>Saldo Haben</th></tr><tr><td>Zahlungsmittel</td><td>{{E}}</td><td>{{ZH}}</td><td>{{Zs}}</td><td></td></tr><tr><td>abn. Sachanlagen (Gebäude)</td><td>{{Ge}}</td><td></td><td>{{Ge}}</td><td></td></tr><tr><td>Büromaterial</td><td>{{Bm}}</td><td></td><td>{{Bm}}</td><td></td></tr><tr><td>Möbel</td><td>{{Mo}}</td><td></td><td>{{Mo}}</td><td></td></tr><tr><td>Verbindlichkeiten (Einkauf)</td><td>{{Tz}}</td><td>{{Bm}}</td><td></td><td>{{VB}}</td></tr><tr><td>Eigenkapital (Einlage)</td><td></td><td>{{E}}</td><td></td><td>{{E}}</td></tr><tr><td>Eigenkapital (Entnahme)</td><td>{{En}}</td><td></td><td>{{En}}</td><td></td></tr><tr><th>Summe</th><th>{{SuS}}</th><th>{{SuS}}</th><th>{{SaS}}</th><th>{{SaS}}</th></tr></table><span class=\"why\">Warum: Vorläufig heißt: vor dem Jahresabschluss. Sie zeigt, ob bis hierhin Soll = Haben stimmt.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Salden Haben: {{VB}} + {{E}} = {{VB+E}}. Salden Soll: {{Zs}} + {{Ge}} + {{Bm}} + {{Mo}} + {{En}} = {{SaS}}. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Jede Buchung trägt denselben Betrag einmal ins Soll und einmal ins Haben ein, darum gehen die Summen immer auf.</p>","short":"Summen {{SuS}} = {{SuS}}; Salden {{SaS}} = {{SaS}}","diag":false,"src":"eigene (Variante zu Übungsskript BuFü A 3.1)","gen":{"vars":{"E":{"min":60000,"max":150000,"step":10000,"not":[100000]},"Ge":{"min":30000,"max":70000,"step":5000},"Bm":{"min":5000,"max":15000,"step":1000},"Mo":{"min":5000,"max":12000,"step":1000},"Tz":{"min":2000,"max":14000,"step":1000},"En":{"min":3000,"max":10000,"step":1000}},"let":{"ZH":"Ge+Mo+Tz+En","Zs":"E-ZH","VB":"Bm-Tz","SuS":"E+Ge+Bm+Mo+Tz+En","SaS":"Zs+Ge+Bm+Mo+En"},"check":"Ge <= E/2 && Tz < Bm && Zs > 0"}},{"id":"bure-t27","topic":"bure-ukv","level":2,"type":"open","q":"Ein Betonwerk stellt im Mai {{N}} Treppenstufen her. Material {{M}} und Fertigungslöhne {{Lo}}, beides bar und direkt zurechenbar.<br/> a) Alle {{N}} Stufen werden für {{V}} auf Ziel verkauft. Buche nach UKV und nach GKV. b) Nur {{k}} Stufen werden für {{Vb}} verkauft. Wie hoch ist das Einkommen nach beiden Verfahren?","a":"<p class=\"goal\"><b>Ziel:</b> Herstellung und Verkauf von Treppenstufen nach UKV und GKV buchen und das Einkommen vergleichen.</p>\n<ol class=\"sol-steps\">\n<li>Herstellungsausgaben: {{M}} + {{Lo}} = <b>{{HK}}</b>.<span class=\"why\">Warum: Material und Fertigungslöhne gehören direkt zu den Stufen.</span></li>\n<li>a) <b>UKV</b> (Umsatzkostenverfahren). Herstellung: <b>Fertigerzeugnisse an Zahlungsmittel {{HK}}</b>.<span class=\"why\">Warum: Beim UKV gehen die Ausgaben erst ins Lager. Fertigerzeugnisse (Aktiv) nehmen zu, also Soll; Geld nimmt ab, also Haben. Einkommen ändert sich nicht.</span></li>\n<li>Verkauf: <b>Forderungen (Verkauf) an Ertrag (Verkauf) {{V}}</b> und <b>Aufwand (Verkauf) an Fertigerzeugnisse {{HK}}</b>.<span class=\"why\">Warum: Forderung (Aktiv) zu, also Soll; Ertrag erhöht das EK, also Haben. Dann verlassen die Stufen das Lager: Aufwand mindert das EK, also Soll; Fertigerzeugnisse (Aktiv) nehmen ab, also Haben.</span></li>\n<li>a) <b>GKV</b> (Gesamtkostenverfahren). Herstellung: <b>Aufwand (Material) {{M}} und Aufwand (Personal) {{Lo}} an Zahlungsmittel {{HK}}</b>. Verkauf: <b>Forderungen (Verkauf) an Ertrag (Verkauf) {{V}}</b>.<span class=\"why\">Warum: Beim GKV ist jede Ausgabe gleich Aufwand (Soll). Beim Verkauf gibt es darum nur die Ertragsbuchung.</span></li>\n<li>Einkommen a) in beiden Fällen: {{V}} − {{HK}} = <b>{{Ya}}</b>.<span class=\"why\">Warum: Alle Stufen sind verkauft, also ist die ganze Herstellung Aufwand.</span></li>\n<li>b) Kosten pro Stufe: {{HK}} / {{N}} = {{HK/N}}. Für {{k}} verkaufte Stufen: {{k}} · {{HK/N}} = {{Ab}}. Im Lager bleiben {{HK}} − {{Ab}} = {{La}}.<span class=\"why\">Warum: Erst den Preis pro Stück, dann mal die verkaufte Stückzahl.</span></li>\n<li>UKV: Einkommen {{Vb}} − {{Ab}} = <b>{{Yb}}</b>.<span class=\"why\">Warum: Nur die verkauften Stufen werden Aufwand. Die anderen bleiben als Fertigerzeugnisse Vermögen.</span></li>\n<li>GKV: Am Jahresende <b>Fertigerzeugnisse an Lagermehrung {{La}}</b>. Einkommen {{Vb}} + {{La}} − {{HK}} = <b>{{Yb}}</b>.<span class=\"why\">Warum: Weil beim GKV alles schon Aufwand war, korrigiert man die Stufen im Lager zurück. Fertigerzeugnisse (Aktiv) zu, also Soll; Lagermehrung wirkt wie ein Ertrag, also Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> GKV: {{Vb}} + {{La}} = {{Vb+La}}; − {{HK}} = {{Yb}}. Gleich wie UKV.</p>\n<p class=\"merke\"><b>Merke:</b> UKV und GKV rechnen anders, kommen aber auf dasselbe Einkommen. <i>(Folien 50–53; Übungsskript 4.5 (UKV, S. 40) und 4.6 (GKV, S. 43))</i></p>","short":"a) Einkommen {{Ya}} · b) {{Yb}} (UKV = GKV)","diag":false,"src":"eigene","gen":{"vars":{"N":[80,100,120,150,200],"f":[60,70,75,80,90],"m":{"min":20,"max":40,"step":1},"l":{"min":10,"max":30,"step":1},"p":{"min":50,"max":100,"step":5}},"let":{"k":"N*f/100","M":"N*m","Lo":"N*l","HK":"M+Lo","V":"N*p","Vb":"k*p","Ab":"k*(m+l)","La":"HK-Ab","Ya":"V-HK","Yb":"Vb-Ab"},"check":"isInt(k) && Yb > 0"}},{"id":"bure-t28","topic":"bure-ukv","level":3,"type":"open","q":"Ein Unternehmen stellt 1000 Einheiten her und verkauft {{pct}} %. Direkte Herstellungsausgaben {{D}}, indirekte Herstellungsausgaben {{I}}, sonstige Ausgaben ohne Bezug zur Herstellung {{So}}. Umsatzerlöse {{U}}, sonstige Einnahmen {{Se}}. Berechne das Einkommen für UKV und GKV, jeweils mit Marginal- und Finalprinzip.","a":"<p class=\"goal\"><b>Ziel:</b> Das Einkommen für UKV und GKV jeweils nach Marginal- und Finalprinzip berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Erträge: {{U}} + {{Se}} = <b>{{Er}}</b>. Verkauft {{pct}} %, also im Lager {{r}} %.<span class=\"why\">Warum: Umsatzerlöse und sonstige Einnahmen sind beide Ertrag. Was nicht verkauft wurde, liegt im Lager: 100 % − {{pct}} % = {{r}} %.</span></li>\n<li><b>UKV, Marginal:</b> Umsatzaufwand {{pct}} % × {{D}} = {{aD}}. Einkommen {{Er}} − {{aD}} − ({{I}} + {{So}}) = {{Er}} − {{aD}} − {{I+So}} = <b>{{Ym}}</b>.<span class=\"why\">Warum: Marginal: nur direkte Ausgaben stecken in den Produkten. Indirekte und sonstige sind sofort Aufwand.</span></li>\n<li><b>UKV, Final:</b> Umsatzaufwand {{pct}} % × ({{D}} + {{I}}) = {{pct}} % × {{D+I}} = {{aF}}. Einkommen {{Er}} − {{aF}} − {{So}} = <b>{{Yf}}</b>.<span class=\"why\">Warum: Final: auch die indirekten Herstellungsausgaben stecken in den Produkten. Nur die sonstigen Ausgaben ohne Herstellungsbezug sind sofort Aufwand.</span></li>\n<li><b>GKV:</b> Gesamte Ausgaben als Aufwand: {{D}} + {{I}} + {{So}} = <b>{{Ges}}</b>.<span class=\"why\">Warum: Beim GKV ist erst einmal alles Aufwand. Danach korrigiert man um die Lagermehrung.</span></li>\n<li><b>GKV, Marginal:</b> Lagermehrung {{r}} % × {{D}} = {{lD}}. Einkommen {{Er}} + {{lD}} − {{Ges}} = <b>{{Ym}}</b>.<span class=\"why\">Warum: Die Lagermehrung wird zum Wert des Marginalprinzips bewertet, also nur mit direkten Ausgaben.</span></li>\n<li><b>GKV, Final:</b> Lagermehrung {{r}} % × {{D+I}} = {{lF}}. Einkommen {{Er}} + {{lF}} − {{Ges}} = <b>{{Yf}}</b>.<span class=\"why\">Warum: Beim Finalprinzip ist das Lager mehr wert, weil der indirekte Anteil mit drinsteckt.</span></li>\n<li>Unterschied: {{Yf}} − {{Ym}} = <b>{{Df}}</b> = {{r}} % × {{I}}.<span class=\"why\">Warum: Nur das Zuordnungsprinzip macht den Unterschied: Beim Finalprinzip liegt dieser Teil der indirekten Ausgaben noch im Lager.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{r}} % von {{I}} = {{I*r/100}}, genau der Unterschied. Außerdem liefern UKV und GKV in jeder Spalte dasselbe.</p>\n<p class=\"merke\"><b>Merke:</b> Das Verfahren (UKV oder GKV) ändert das Einkommen nicht, nur das Zuordnungsprinzip (Marginal oder Final). <i>(Folien 56–61)</i></p>","short":"Marginal {{Ym}}, Final {{Yf}} (UKV = GKV)","diag":false,"src":"eigene","gen":{"vars":{"pct":[50,60,70,75,80],"D":{"min":10000,"max":30000,"step":1000},"I":{"min":4000,"max":12000,"step":1000},"So":{"min":2000,"max":8000,"step":1000},"U":{"min":20000,"max":50000,"step":1000},"Se":{"min":500,"max":3000,"step":500}},"let":{"r":"100-pct","Er":"U+Se","Ges":"D+I+So","aD":"pct*D/100","aF":"pct*(D+I)/100","lD":"D-aD","lF":"D+I-aF","Ym":"Er-aD-(I+So)","Yf":"Er-aF-So","Df":"Yf-Ym"},"check":"isInt(aD) && isInt(aF) && Ym > 0"}},{"id":"bure-t29","topic":"bure-sonder","level":2,"type":"open","q":"Steuersatz 10 % wie in der Vorlesung. Rechne und bilde bei b) bis d) die Buchungssätze. a) Eine Rechnung lautet brutto {{Ba}}. Berechne Netto und Steuer. b) Kauf von Handelsware netto {{K}} auf Ziel. c) Drei Viertel davon (Buchwert {{Bw}}) für netto {{Vn}} bar verkauft (UKV). d) Berechne die Zahllast und buche ihre Überweisung. e) Wie hoch ist das Einkommen?","a":"<p class=\"goal\"><b>Ziel:</b> Mit 10 % Umsatzsteuer netto und Steuer trennen, Kauf, Verkauf und Zahllast buchen und das Einkommen bestimmen.</p>\n<ol class=\"sol-steps\">\n<li>a) Brutto = Netto + 10 % von Netto = 1,1 · Netto. Also Netto = {{Ba}} / 1,1 = <b>{{Na}}</b>. Steuer {{Ba}} − {{Na}} = <b>{{Sa}}</b>.<span class=\"why\">Warum: Die 10 % beziehen sich auf den Nettobetrag, nicht auf den Bruttobetrag. Darum teilst du durch 1,1 und ziehst nicht 10 % vom Brutto ab.</span></li>\n<li>b) Vorsteuer: 10 % × {{K}} = {{Vo}}. Brutto {{K}} + {{Vo}} = {{Kb}}. Buchung: <b>Handelsware {{K}} und Forderungen (VoSt) {{Vo}} an Verbindlichkeiten (Einkauf) {{Kb}}</b>.<span class=\"why\">Warum: Handelsware (Aktiv) nimmt zu, also Soll. Die Vorsteuer holt man sich vom Finanzamt zurück, sie ist eine Forderung (Aktiv), also Soll. Die Schuld beim Lieferanten (Passiv) steigt um den Bruttobetrag, also Haben.</span></li>\n<li>c) Mehrwertsteuer: 10 % × {{Vn}} = {{Mw}}. Brutto {{Vn}} + {{Mw}} = {{Vb}}. Buchung: <b>Zahlungsmittel {{Vb}} an Ertrag (Verkauf) {{Vn}} und Verbindlichkeiten (MwSt) {{Mw}}</b>.<span class=\"why\">Warum: Geld (Aktiv) nimmt zu, also Soll. Der Ertrag erhöht das EK, also Haben. Die Steuer gehört dem Finanzamt, also eine Schuld (Passiv) im Haben.</span></li>\n<li>Abgang der Ware: drei Viertel von {{K}} = {{K}} / 4 · 3 = {{Bw}}. Buchung (UKV): <b>Aufwand (Verkauf) an Handelsware {{Bw}}</b>.<span class=\"why\">Warum: Aufwand mindert das EK, also Soll. Handelsware (Aktiv) nimmt ab, also Haben.</span></li>\n<li>d) Zahllast: {{Mw}} − {{Vo}} = <b>{{Zl}}</b>. Buchung: <b>Verbindlichkeiten (MwSt) {{Mw}} an Forderungen (VoSt) {{Vo}} und Zahlungsmittel {{Zl}}</b>.<span class=\"why\">Warum: Zahllast heißt im Alltag: so viel überweist die Firma wirklich ans Finanzamt, nämlich kassierte Steuer minus schon gezahlte Steuer. Die Schuld (Passiv) nimmt ab, also Soll. Forderung und Geld (Aktiv) nehmen ab, also Haben.</span></li>\n<li>e) Einkommen: {{Vn}} − {{Bw}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Nur Ertrag und Aufwand zählen, beide netto. Die Steuer läuft nur über Forderungs- und Schuldkonten.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> a) {{Na}} · 1,1 = {{Ba}}. d) Nach der Zahlung sind VoSt-Konto ({{Vo}} − {{Vo}}) und MwSt-Konto ({{Mw}} − {{Mw}}) beide 0.</p>\n<p class=\"merke\"><b>Merke:</b> Netto aus Brutto: durch 1,1 teilen, nicht 10 % abziehen. Die Umsatzsteuer ändert das Einkommen nicht. <i>(Folien 73–78; Übungsskript 4.5 (S. 40))</i></p>","short":"a) {{Na}} + {{Sa}} · d) Zahllast {{Zl}} · e) Einkommen {{Y}}","diag":false,"src":"eigene","gen":{"vars":{"Na":{"min":1000,"max":5000,"step":100},"K":{"min":1000,"max":4000,"step":200},"Vn":{"min":1000,"max":6000,"step":100}},"let":{"Ba":"Na*11/10","Sa":"Ba-Na","Vo":"K/10","Kb":"K+Vo","Bw":"K*3/4","Mw":"Vn/10","Vb":"Vn+Mw","Zl":"Mw-Vo","Y":"Vn-Bw"},"check":"Vn > K && isInt(Ba) && isInt(Bw)"}},{"id":"bure-t30","topic":"bure-sonder","level":2,"type":"open","q":"Eine Verwaltungsangestellte verdient brutto {{B}}. Lohnsteuer und Kirchensteuer zusammen {{St}}. Arbeitnehmeranteil Sozialversicherung {{ANc}}. Der Arbeitgeberanteil ist nach der Regel von Folie 66 um 0,9 % des Bruttos kleiner. Berufsgenossenschaft {{BG}}. Alles wird später gezahlt.<br/> a) Wie hoch ist das Netto? b) Wie hoch sind die Personalausgaben des Arbeitgebers? c) Bilde den Buchungssatz, wenn die Ausgaben nichts mit der Herstellung zu tun haben.","a":"<p class=\"goal\"><b>Ziel:</b> Netto, Personalausgaben und Buchungssatz für ein Gehalt berechnen.</p>\n<ol class=\"sol-steps\">\n<li>a) Netto = Brutto − Steuern − AN-Anteil: {{B}} − {{St}} = {{B-St}}; − {{ANc}} = <b>{{Nec}}</b>.<span class=\"why\">Warum: Netto ist im Alltag das, was die Angestellte wirklich aufs Konto bekommt. Steuern und ihren Sozialversicherungsanteil behält der Arbeitgeber ein und zahlt sie weiter.</span></li>\n<li>b) 0,9 % vom Brutto: {{B}} / 100 · 0,9 = {{AGac}}. AG-Anteil {{ANc}} − {{AGac}} = <b>{{AGc}}</b>.<span class=\"why\">Warum: Laut Folie 66 zahlt der Arbeitgeber 0,9 % des Bruttos weniger Sozialversicherung als die Arbeitnehmerin.</span></li>\n<li>Personalausgaben: {{B}} + {{AGc}} + {{BG}} = <b>{{PAc}}</b>.<span class=\"why\">Warum: Den Arbeitgeber kostet die Stelle mehr als das Brutto: Dazu kommen sein eigener SV-Anteil und die Berufsgenossenschaft (Unfallversicherung).</span></li>\n<li>Sozialversicherung gesamt: {{ANc}} + {{AGc}} = {{SVc}}.<span class=\"why\">Warum: Die Krankenkasse bekommt beide Anteile in einer Summe.</span></li>\n<li>c) <b>Aufwand (Personal) {{PAc}} an Verbindlichkeiten (Gehalt) {{Nec}}, Verbindlichkeiten (Fiskus) {{St}}, Verbindlichkeiten (Sozialvers.) {{SVc}}, Verbindlichkeiten (Berufsgen.) {{BG}}</b>.<span class=\"why\">Warum: Kein Bezug zur Herstellung, also Periodisierung: sofort Aufwand. Aufwand mindert das EK, also Soll. Alles wird später gezahlt, also entstehen Schulden (Passiv) im Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{Nec}} + {{St}} + {{SVc}} + {{BG}} = {{PAc}}. Soll und Haben sind gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Personalausgaben = Brutto + AG-Anteil + Berufsgenossenschaft; das Netto ist nur der Teil, der an die Angestellte geht. <i>(Folien 65–70; Übungsskript 4.1 (S. 29))</i></p>","short":"Netto {{Nec}}; Personalausgaben {{PAc}}","diag":false,"src":"eigene","gen":{"vars":{"B":{"min":2000,"max":5000,"step":100},"St":{"min":200,"max":1000,"step":10},"p":[195,200,205,210],"BG":{"min":15,"max":60,"step":1}},"let":{"AN":"B*p/1000","AGa":"B*9/1000","AG":"AN-AGa","Ne":"B-St-AN","PA":"B+AG+BG","SV":"AN+AG","ANc":"isInt(AN)?num(AN):num(AN,2)","AGac":"isInt(AGa)?num(AGa):num(AGa,2)","AGc":"isInt(AG)?num(AG):num(AG,2)","Nec":"isInt(Ne)?num(Ne):num(Ne,2)","PAc":"isInt(PA)?num(PA):num(PA,2)","SVc":"isInt(SV)?num(SV):num(SV,2)"},"check":"St >= 0.08*B && St <= 0.25*B && isInt(AN*100) && isInt(AG*100)"}},{"id":"bure-t31","topic":"bure-sonder","level":2,"type":"open","q":"Handelsware für {{P}} auf Ziel gekauft, ohne Umsatzsteuer. Zahlung mit {{s}} % Skonto innerhalb von 10 Tagen möglich. a) Wie viel ist bei Zahlung am Tag 8 zu zahlen, wie viel am Tag 15? b) Buchungssatz bei Zahlung mit Skonto, Ware noch im Lager. c) Was ändert sich, wenn die Ware schon verkauft war?","a":"<p class=\"goal\"><b>Ziel:</b> Den Zahlbetrag mit und ohne Skonto berechnen und die Zahlung mit Skonto buchen.</p>\n<ol class=\"sol-steps\">\n<li>Skonto: {{s}} % von {{P}} = {{P}} / 100 · {{s}} = <b>{{Skc}}</b>.<span class=\"why\">Warum: Skonto ist ein Rabatt fürs schnelle Bezahlen.</span></li>\n<li>a) Tag 8 (innerhalb von 10 Tagen): {{P}} − {{Skc}} = <b>{{Zc}}</b>. Das ist dasselbe wie {{P}} × {{(100-s)/100:2}}. Tag 15: voller Betrag <b>{{P}}</b>.<span class=\"why\">Warum: Nach Tag 10 ist die Skontofrist vorbei, dann gilt der volle Preis.</span></li>\n<li>b) <b>Verbindlichkeiten (Einkauf) {{P}} an Zahlungsmittel {{Zc}} und Handelsware {{Skc}}</b>.<span class=\"why\">Warum: Die ganze Schuld (Passiv) ist weg, also Soll {{P}}. Geld (Aktiv) nimmt ab, also Haben. Die Ware war billiger als gedacht: Ihr Wert (Aktiv) sinkt um den Skonto, also Haben.</span></li>\n<li>c) Ware schon verkauft: <b>Verbindlichkeiten (Einkauf) {{P}} an Zahlungsmittel {{Zc}} und Aufwand (Verkauf) {{Skc}}</b>.<span class=\"why\">Warum: Es gibt keine Ware mehr, deren Wert man senken kann. Stattdessen war der Aufwand für die verkaufte Ware um {{Skc}} zu hoch. Aufwand mindern heißt: Buchung im Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> b) Haben: {{Zc}} + {{Skc}} = {{P}} = Soll.</p>\n<p class=\"merke\"><b>Merke:</b> Skonto senkt den Anschaffungswert der Ware, er ist kein Ertrag. <i>(Folie 80; Verständniskontrolle Folie 82, Frage 3; Übungsskript 4.4 (S. 36))</i></p>","short":"Tag 8: {{Zc}}, Tag 15: {{P}}; Skonto {{Skc}} mindert Ware bzw. Aufwand","diag":false,"src":"eigene","gen":{"vars":{"P":{"min":1000,"max":5000,"step":50},"s":[2,3]},"let":{"Sk":"P*s/100","Z":"P-Sk","Skc":"isInt(Sk)?num(Sk):num(Sk,2)","Zc":"isInt(Z)?num(Z):num(Z,2)"},"check":"isInt(Sk*100)"}},{"id":"bure-t32","topic":"bure-zwecke","level":1,"type":"mc","q":"Eine Dienstleistung wird für 1.000 auf Ziel verkauft. Was liegt vor: Einzahlung, Einnahme, Ertrag?","options":["Einnahme und Ertrag, aber keine Einzahlung","Einzahlung, Einnahme und Ertrag","Einzahlung und Ertrag, aber keine Einnahme","Nur Ertrag, weder Einzahlung noch Einnahme"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Prüfen, ob ein Verkauf auf Ziel Einzahlung, Einnahme oder Ertrag ist.</p>\n<ol class=\"sol-steps\">\n<li>Einzahlung = Zahlungsmittel steigen. Einnahme = Geldvermögen steigt (Geld + Forderungen − Verbindlichkeiten). Ertrag = das EK steigt durch eine Leistung.<span class=\"why\">Warum: Die drei Begriffe messen verschieden weit: nur Bargeld, Geld plus offene Rechnungen, oder echten Verdienst.</span></li>\n<li>Zahlungsmittel bleiben gleich → <b>keine Einzahlung</b>.<span class=\"why\">Warum: „Auf Ziel“ heißt: Der Kunde zahlt später. Heute kommt kein Geld.</span></li>\n<li>Forderung +1.000 → Geldvermögen +1.000 → <b>Einnahme</b>.<span class=\"why\">Warum: Der Kunde schuldet uns jetzt 1.000. Das zählt zum Geldvermögen.</span></li>\n<li>Leistung an den Kunden abgegeben → <b>Ertrag 1.000</b> (Marktleistungsabgabe).<span class=\"why\">Warum: Wir haben die Dienstleistung erbracht und damit verdient, egal wann gezahlt wird.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Geldvermögen: 0 (Geld) + 1.000 (Forderung) = +1.000. Also Einnahme ja, Einzahlung nein.</p>\n<p class=\"merke\"><b>Merke:</b> Verkauf auf Ziel: Einnahme und Ertrag sofort, die Einzahlung kommt erst mit der Zahlung.</p>","short":"Einnahme und Ertrag, keine Einzahlung","diag":true,"src":"eigene"},{"id":"bure-t33","topic":"bure-zwecke","level":2,"type":"mc","q":"Ein Kunde bezahlt eine bestehende Forderung von 2.000 bar. Was liegt vor: Einzahlung, Einnahme, Ertrag?","options":["Einzahlung, Einnahme und Ertrag","Einzahlung, aber weder Einnahme noch Ertrag","Einzahlung und Einnahme, aber kein Ertrag","Weder Einzahlung noch Einnahme"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Prüfen, was die Zahlung einer bestehenden Forderung ist.</p>\n<ol class=\"sol-steps\">\n<li>Einzahlung = Zahlungsmittel steigen. Einnahme = Geldvermögen steigt (Geld + Forderungen − Verbindlichkeiten). Ertrag = das EK steigt durch eine Leistung.<span class=\"why\">Warum: Die drei Begriffe messen verschieden weit: nur Bargeld, Geld plus offene Rechnungen, oder echten Verdienst.</span></li>\n<li>Zahlungsmittel +2.000 → <b>Einzahlung</b>.<span class=\"why\">Warum: Es kommt echtes Geld rein.</span></li>\n<li>Forderung −2.000 → Geldvermögen +2.000 − 2.000 = 0 → <b>keine Einnahme</b>.<span class=\"why\">Warum: Das Recht auf Geld wird nur zu Geld. Unterm Strich hat man nicht mehr.</span></li>\n<li><b>Kein Ertrag</b>.<span class=\"why\">Warum: Verdient wurde schon beim Verkauf. Sonst würde man denselben Verkauf zweimal zählen.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Eine Kundenzahlung ist nur eine Einzahlung; Einnahme und Ertrag gab es schon beim Verkauf.</p>","short":"Nur Einzahlung","diag":true,"src":"eigene"},{"id":"bure-t34","topic":"bure-zwecke","level":3,"type":"mc","q":"Einzahlungsüberschuss {{U}}. Darin enthalten: Bankdarlehen {{D}} erhalten. Außerdem: Verkauf auf Ziel {{F}} (noch offen) und Material {{V}} auf Ziel gekauft. Wie hoch ist der Einnahme-Ausgabe-Saldo?","options":["{{U+F-V}}","{{o1m}}","{{EAm}}","{{U+F-V+D}}"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Vom Einzahlungsüberschuss zum Einnahme-Ausgabe-Saldo kommen.</p>\n<ol class=\"sol-steps\">\n<li>Start: Einzahlungsüberschuss {{U}}.<span class=\"why\">Warum: Er enthält nur echte Geldflüsse.</span></li>\n<li>+ {{F}} für die offene Forderung.<span class=\"why\">Warum: Verkauf auf Ziel erhöht das Geldvermögen ohne Geld: Einnahme ohne Einzahlung.</span></li>\n<li>− {{V}} für das Material auf Ziel.<span class=\"why\">Warum: Es entsteht eine Schuld ohne Zahlung: Ausgabe ohne Auszahlung.</span></li>\n<li>− {{D}} für das Darlehen.<span class=\"why\">Warum: Das Darlehen steckt als Einzahlung in {{U}}. Die Schuld steigt aber genauso, also ist es keine Einnahme. Darum wieder abziehen.</span></li>\n<li>Rechnen: \\({{U:0t}} + {{F:0t}} = {{U+F:0t}}\\); \\({{U+F:0t}} - {{V:0t}} = {{U+F-V:0t}}\\); \\({{U+F-V:0t}} - {{D:0t}} = {{EA:0t}}\\).<span class=\"why\">Warum: Schritt für Schritt von links nach rechts, damit sich kein Vorzeichen vertauscht.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Das Ergebnis ist {{EAm}}. Typische Falle: Wer das Darlehen vergisst, landet bei {{U+F-V}}.</p>\n<p class=\"merke\"><b>Merke:</b> Kredite sind Einzahlungen, aber keine Einnahmen, weil die Schuld gleich mitwächst.</p>","short":"{{EAm}}","diag":true,"src":"eigene","gen":{"vars":{"U":{"min":30000,"max":80000,"step":1000},"D":{"min":10000,"max":40000,"step":1000},"F":{"min":5000,"max":20000,"step":1000},"V":{"min":3000,"max":15000,"step":1000}},"let":{"EA":"U+F-V-D","o1":"U-F+V-D","EAm":"(EA<0?'−':'')+num(abs(EA))","o1m":"(o1<0?'−':'')+num(abs(o1))"},"check":"D < U && F != V"}},{"id":"bure-t35","topic":"bure-zwecke","level":2,"type":"mc","q":"Totalbetrachtung: Die Zahlungssalden aller Jahre ergeben {{Ss}}. Es gab nur Entnahmen von insgesamt {{En}}, keine Einlagen. Wie hoch ist die Summe der Einkommen?","options":["{{Ws}}","{{Es}}","{{Ss}}","+{{En}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Aus der Summe der Zahlungssalden und den Entnahmen die Summe der Einkommen berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Totalformel: Summe der Zahlungssalden = Summe der Einkommen + Summe der Transfers.<span class=\"why\">Warum: Über die ganze Lebensdauer gleichen sich Forderungen, Schulden und Lager aus. Übrig bleibt, was verdient wurde und was der Inhaber eingelegt oder entnommen hat.</span></li>\n<li>Transfers: Einlagen 0 − Entnahmen {{En}} = −{{En}}.<span class=\"why\">Warum: Es gab nur Entnahmen, und die verringern das Firmengeld.</span></li>\n<li>Umstellen: Summe Einkommen = Summe Zahlungssalden − Summe Transfers = {{Ss}} − (−{{En}}).<span class=\"why\">Warum: Die Transfers stehen rechts mit +, also kommen sie beim Umstellen mit − auf die andere Seite.</span></li>\n<li>Vorzeichenregel \\(-(-a) = +a\\): {{Ss}} + {{En}} = <b>{{Es}}</b>.<span class=\"why\">Warum: Minus mal minus ergibt plus. Die Entnahmen haben Geld abgezogen, das kein Aufwand war, also war das Einkommen um {{En}} besser als der Zahlungssaldo.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{Es}} + (−{{En}}) = {{Ss}}. Passt.</p>\n<p class=\"merke\"><b>Merke:</b> Entnahmen drücken den Zahlungssaldo, aber nicht das Einkommen.</p>","short":"{{Es}}","diag":false,"src":"eigene","gen":{"vars":{"S":{"min":-800000,"max":-100000,"step":10000},"En":{"min":50000,"max":250000,"step":10000}},"let":{"E":"S+En","W":"S-En","Es":"(E<0?'−':'+')+num(abs(E))","Ws":"(W<0?'−':'+')+num(abs(W))","Ss":"(S<0?'−':'+')+num(abs(S))"},"check":"E != 0"}},{"id":"bure-t36","topic":"bure-zwecke","level":1,"type":"mc","q":"Welcher Finanzbericht ist eine Bestandsrechnung (Zeitpunkt, „Schnappschuss“)?","options":["Einkommensrechnung","Eigenkapitaltransferrechnung","Bilanz","Eigenkapitalveränderungsrechnung"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Den Finanzbericht finden, der einen Zeitpunkt zeigt.</p>\n<ol class=\"sol-steps\">\n<li>Bilanz → Zeitpunkt (Stichtag), Bestandsrechnung.<span class=\"why\">Warum: Sie zeigt wie ein Foto, was an einem Tag da ist.</span></li>\n<li>Einkommens-, Transfer- und Veränderungsrechnung → Zeitraum, Bewegungsrechnung.<span class=\"why\">Warum: Sie zeigen wie ein Video, was sich über ein Jahr verändert hat.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Bilanz = Foto am Stichtag, die anderen drei = Video über den Zeitraum.</p>","short":"Bilanz","diag":false,"src":"eigene"},{"id":"bure-t37","topic":"bure-ek","level":1,"type":"mc","q":"Vermögen: Grundstück {{Gr}}, Maschine {{Ma}}, Zahlungsmittel {{Z}}. Fremdkapital {{FK}}. Wie hoch ist das Eigenkapital?","options":["{{V+FK}}","{{EK}}","{{Gr+Ma-FK}}","{{V}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Das Eigenkapital aus Vermögen und Fremdkapital berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Bilanzgleichung umstellen: \\(\\text{EK} = \\text{Vermögen} - \\text{FK}\\).<span class=\"why\">Warum: Das Vermögen gehört zum Teil den Gläubigern (FK). Der Rest gehört dem Inhaber.</span></li>\n<li>Vermögen: {{Gr}} + {{Ma}} = {{Gr+Ma}}; + {{Z}} = <b>{{V}}</b>.<span class=\"why\">Warum: Alle Vermögensgüter addieren.</span></li>\n<li>\\(\\text{EK} = {{V:0t}} - {{FK:0t}} = {{EK:0t}}\\)<span class=\"why\">Warum: Im Alltag: Nach Bezahlung aller Schulden blieben dem Inhaber {{EK}}.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> FK + EK: {{FK}} + {{EK}} = {{V}} = Vermögen.</p>\n<p class=\"merke\"><b>Merke:</b> Typische Falle: Vermögen + FK rechnen. FK wird abgezogen, nicht addiert.</p>","short":"{{EK}}","diag":true,"src":"eigene","gen":{"vars":{"Gr":{"min":20000,"max":80000,"step":1000},"Ma":{"min":10000,"max":50000,"step":1000},"Z":{"min":5000,"max":30000,"step":100},"FK":{"min":20000,"max":60000,"step":100}},"let":{"V":"Gr+Ma+Z","EK":"V-FK"},"check":"EK > 0 && Gr+Ma > FK"}},{"id":"bure-t38","topic":"bure-ek","level":1,"type":"mc","q":"Material für 3.000 wird auf Ziel gekauft. Welche Bilanzveränderung liegt vor?","options":["Aktivtausch","Passivtausch","Bilanzverlängerung ohne EK-Wirkung","Bilanzverkürzung ohne EK-Wirkung"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Die Bilanzveränderung beim Materialkauf auf Ziel bestimmen.</p>\n<ol class=\"sol-steps\">\n<li>Material +3.000 → Aktiva steigen.<span class=\"why\">Warum: Material ist Vermögen und kommt dazu.</span></li>\n<li>Verbindlichkeiten +3.000 → Passiva (FK) steigen.<span class=\"why\">Warum: „Auf Ziel“ heißt: später zahlen, also entsteht eine Schuld.</span></li>\n<li>Beide Seiten +3.000, EK gleich → <b>Bilanzverlängerung ohne EK-Wirkung</b>.<span class=\"why\">Warum: Wenn links und rechts gleich viel dazukommt, wird die Bilanz „länger“. Niemand ist reicher oder ärmer geworden.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Aktiva +3.000, Passiva +3.000. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Kaufen auf Ziel verlängert die Bilanz; bar kaufen ist nur ein Aktivtausch.</p>","short":"Bilanzverlängerung ohne EK-Wirkung","diag":true,"src":"eigene"},{"id":"bure-t39","topic":"bure-ek","level":2,"type":"mc","q":"EK am 1.1.: {{EK0}}. Im Jahr: Einlagen {{Ei}}, Entnahmen {{En}}, Erträge {{Er}}, Aufwand {{Au}}. Wie hoch ist das EK am 31.12.?","options":["{{O0}}","{{EK1}}","{{O2}}","{{O3}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Das Eigenkapital am Jahresende aus Einkommen und Transfers berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Einkommen: {{Er}} − {{Au}} = <b>{{Y}}</b>.<span class=\"why\">Warum: Erträge minus Aufwand ist der Gewinn des Jahres.</span></li>\n<li>Transfer: {{Ei}} − {{En}} = <b>{{Trs}}</b>.<span class=\"why\">Warum: Einlagen erhöhen, Entnahmen senken das EK. Verdient ist das aber nicht.</span></li>\n<li>\\(EK_1 = {{EK0:0t}} + {{Y:0t}} {{Tr<0?'-':'+'}} {{abs(Tr):0t}} = {{EK1:0t}}\\)<span class=\"why\">Warum: EK am Ende = EK am Anfang + Einkommen + Transfer (Eigenkapitalveränderungsrechnung).</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{EK1}} − {{EK0}} = {{EK1-EK0}}, und das ist Einkommen plus Transfer.</p>\n<p class=\"merke\"><b>Merke:</b> Entnahmen werden abgezogen, nicht addiert: Sie sind ein negativer Transfer.</p>","short":"{{EK1}}","diag":true,"src":"eigene","gen":{"vars":{"EK0":{"min":10000,"max":40000,"step":1000},"Ei":{"min":1000,"max":8000,"step":1000},"En":{"min":2000,"max":10000,"step":1000},"Er":{"min":20000,"max":50000,"step":1000},"Au":{"min":10000,"max":45000,"step":1000}},"let":{"Y":"Er-Au","Tr":"Ei-En","EK1":"EK0+Y+Tr","O0":"EK0+Ei+En+Y","O2":"EK0+Y","O3":"EK0+Tr","Trs":"(Tr<0?'−':'+')+num(abs(Tr))"},"check":"Au < Er && Ei != En && Y != Tr && Y != -Tr"}},{"id":"bure-t40","topic":"bure-ek","level":3,"type":"mc","q":"Ein Grundstück (Buchwert {{B}}) wird für {{V}} auf Ziel verkauft. Wie ändern sich Bilanzsumme und Eigenkapital?","options":["Beides gleich (Aktivtausch)","Bilanzsumme +{{V}}, EK +{{V}}","Bilanzsumme +{{g}}, EK +{{g}}","Bilanzsumme +{{g}}, EK gleich"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Bestimmen, wie der Verkauf eines Grundstücks über Buchwert die Bilanz und das EK ändert.</p>\n<ol class=\"sol-steps\">\n<li>Forderung +{{V}}, Grundstück −{{B}}. Aktiva: {{V}} − {{B}} = +{{g}}.<span class=\"why\">Warum: Das Grundstück geht weg, dafür schuldet uns der Käufer den Preis.</span></li>\n<li>Ertrag {{V}}, Aufwand {{B}}. Einkommen {{V}} − {{B}} = +{{g}}, also EK +{{g}}.<span class=\"why\">Warum: Der Verkaufspreis ist Ertrag. Das abgegebene Grundstück zählt zum Buchwert als Aufwand. Der Rest ist Gewinn.</span></li>\n<li>Bilanzsumme +{{g}}, EK +{{g}} → <b>Bilanzverlängerung mit EK-Wirkung</b>.<span class=\"why\">Warum: Links und rechts wächst die Bilanz um den Gewinn.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Aktiva +{{g}}, Passiva (EK) +{{g}}. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Beim Verkauf über Buchwert wächst das EK nur um den Gewinn, nicht um den ganzen Preis.</p>","short":"Bilanzsumme +{{g}}, EK +{{g}}","diag":true,"src":"eigene","gen":{"vars":{"B":{"min":10000,"max":60000,"step":1000},"g":{"min":1000,"max":15000,"step":1000}},"let":{"V":"B+g"}}},{"id":"bure-t41","topic":"bure-ek","level":3,"type":"mc","q":"Der Inhaber zahlt ein Firmendarlehen von 15.000 von seinem Privatkonto zurück. Wie wirkt das beim Unternehmen?","options":["Keine Buchung, privater Vorgang","FK −15.000, EK +15.000 (Einlage)","Zahlungsmittel −15.000, FK −15.000","FK −15.000, Ertrag +15.000"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Die Wirkung beim Unternehmen bestimmen, wenn der Inhaber ein Firmendarlehen privat zurückzahlt.</p>\n<ol class=\"sol-steps\">\n<li>Firmengeld fließt nicht. Fremdkapital −15.000.<span class=\"why\">Warum: Die Firma schuldet der Bank nichts mehr, obwohl sie selbst nichts bezahlt hat.</span></li>\n<li>EK +15.000 als <b>Einlage</b>.<span class=\"why\">Warum: Der Inhaber hat mit seinem privaten Geld für die Firma bezahlt. Das ist so, als hätte er Geld eingelegt.</span></li>\n<li>Ein Passivposten sinkt, ein anderer steigt → <b>Passivtausch mit EK-Wirkung</b>, Bilanzsumme gleich.<span class=\"why\">Warum: Nur die rechte Seite ändert sich: weniger FK, mehr EK.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Passiva: −15.000 + 15.000 = 0. Bilanzsumme bleibt gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Was der Inhaber privat für die Firma bezahlt, ist eine Einlage.</p>","short":"FK −15.000, EK +15.000 (Einlage)","diag":false,"src":"eigene"},{"id":"bure-t42","topic":"bure-konzepte","level":1,"type":"mc","q":"Zinsen für einen Überbrückungskredit werden überwiesen. Welches Konzept bestimmt die Einkommenswirkung?","options":["Marktleistungsabgabekonzept","Periodisierungskonzept","Einkommensvorwegnahmekonzept","Keine Einkommenswirkung"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Das Konzept finden, das die Einkommenswirkung von Kreditzinsen bestimmt.</p>\n<ol class=\"sol-steps\">\n<li>Zinsen haben keinen Bezug zu einem Verkauf.<span class=\"why\">Warum: Sie gehören zu keinem bestimmten Produkt, sondern zur Zeit, in der der Kredit läuft.</span></li>\n<li>Darum <b>Periodisierung</b>: Aufwand in der Zeit, in der sie anfallen.<span class=\"why\">Warum: Periodisierung heißt: Aufwand der Periode (dem Zeitraum) zuordnen, zu der er gehört.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Was zu keinem verkauften Produkt gehört, wird periodisiert.</p>","short":"Periodisierungskonzept","diag":true,"src":"eigene"},{"id":"bure-t43","topic":"bure-konzepte","level":2,"type":"mc","q":"Ein Gericht wird das Unternehmen absehbar zu 12.000 Schadensersatz verurteilen. Was gilt jetzt?","options":["Keine Buchung, es ist noch nichts gezahlt","Periodisierung: Aufwand erst bei Zahlung","Einkommensvorwegnahme: Aufwand 12.000 schon jetzt","Marktleistungsabgabe: Aufwand beim nächsten Verkauf"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Bestimmen, was bei einer absehbaren Schadensersatzzahlung jetzt gilt.</p>\n<ol class=\"sol-steps\">\n<li>Die Zahlung ist noch nicht passiert, aber absehbar.<span class=\"why\">Warum: Ein Gericht wird das Unternehmen sehr wahrscheinlich verurteilen.</span></li>\n<li><b>Einkommensvorwegnahme</b>: Aufwand 12.000 schon jetzt.<span class=\"why\">Warum: Aus Vorsicht zeigt man drohende Verluste sofort. Sonst sähe die Firma reicher aus, als sie ist.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Absehbare Verluste nimmt man vorweg, man wartet nicht auf die Zahlung.</p>","short":"Einkommensvorwegnahme: Aufwand 12.000 jetzt","diag":true,"src":"eigene"},{"id":"bure-t44","topic":"bure-konzepte","level":3,"type":"mc","q":"{{N}} Stück hergestellt, {{S}} für je {{p}} verkauft. Direkte Herstellungsausgaben {{D}}, indirekte (Hallenlicht) {{I}}. Wie hoch ist das Einkommen nach dem Finalprinzip?","options":["{{Ym}}","{{Yallm}}","{{Yf}}","{{Yno}}"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Das Einkommen nach dem Finalprinzip berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Verkaufte Stückzahl: {{f}} % von {{N}} = {{S}}. Umsatzertrag: {{S}} · {{p}} = <b>{{Ru}}</b>.<span class=\"why\">Warum: Erst die verkaufte Menge, dann mal den Preis pro Stück.</span></li>\n<li>Finalprinzip: Herstellung = direkt + indirekt = {{D}} + {{I}} = <b>{{HK}}</b>.<span class=\"why\">Warum: Final heißt: alles, was für die Herstellung nötig war, auch das Hallenlicht, geht ins Lager.</span></li>\n<li>Umsatzaufwand: {{f}} % · {{HK}} = {{HK}} / 100 · {{f}} = <b>{{aF}}</b>.<span class=\"why\">Warum: Nur der verkaufte Anteil wird Aufwand. Der Rest bleibt als Vermögen im Lager.</span></li>\n<li>\\(E = {{Ru:0t}} - {{aF:0t}} = {{Yf:0t}}\\)<span class=\"why\">Warum: Einkommen = Umsatzertrag − Umsatzaufwand.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Zum Vergleich Marginal: {{Ru}} − {{aD}} − {{I}} = {{Ym}}. Final ist größer, weil ein Teil von {{I}} im Lager steckt.</p>\n<p class=\"merke\"><b>Merke:</b> Beim Finalprinzip wird das Indirekte nicht extra abgezogen, es steckt schon im Umsatzaufwand.</p>","short":"{{Yf}}","diag":true,"src":"eigene","gen":{"vars":{"N":[400,500,600,800,1000],"f":[60,70,75,80,90],"p":{"min":20,"max":60,"step":1},"D":{"min":5000,"max":20000,"step":500},"I":{"min":1000,"max":5000,"step":500}},"let":{"S":"N*f/100","Ru":"S*p","HK":"D+I","aF":"HK*f/100","aD":"D*f/100","Yf":"Ru-aF","Ym":"Ru-aD-I","Yall":"Ru-D-I","Yno":"Ru-aD","Yallm":"(Yall<0?'−':'')+num(abs(Yall))"},"check":"isInt(S) && isInt(aF) && isInt(aD) && Ym > 0"}},{"id":"bure-t45","topic":"bure-konzepte","level":2,"type":"mc","q":"Lagermehrung: Es wurde mehr hergestellt als verkauft. Welches Zuordnungsprinzip zeigt das höhere Einkommen?","options":["Marginalprinzip","Finalprinzip","Beide gleich","Hängt von UKV oder GKV ab"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Herausfinden, welches Zuordnungsprinzip bei Lagermehrung mehr Einkommen zeigt.</p>\n<ol class=\"sol-steps\">\n<li>Finalprinzip: Ein Teil der indirekten Ausgaben steckt in den Lagerprodukten.<span class=\"why\">Warum: Lagerprodukte sind Vermögen, also noch kein Aufwand.</span></li>\n<li>Marginalprinzip: Die indirekten Ausgaben sind sofort ganz Aufwand.<span class=\"why\">Warum: Hier steckt im Lager nur das Direkte.</span></li>\n<li>Lagermehrung → weniger Aufwand beim Finalprinzip → <b>Finalprinzip zeigt mehr Einkommen</b>.<span class=\"why\">Warum: Weniger Aufwand heißt mehr Gewinn. Bei Lagerminderung ist es umgekehrt.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Lagermehrung: Final größer. Lagerminderung: Marginal größer.</p>","short":"Finalprinzip","diag":false,"src":"eigene"},{"id":"bure-t46","topic":"bure-konten","level":1,"type":"mc","q":"Welcher Buchungssatz ist richtig? Grundstück für 60.000 bar gekauft.","options":["Zahlungsmittel an Grundstücke 60.000","Grundstücke an Zahlungsmittel 60.000","Grundstücke an Eigenkapital 60.000","Aufwand an Zahlungsmittel 60.000"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Den richtigen Buchungssatz für einen Grundstückskauf bar finden.</p>\n<ol class=\"sol-steps\">\n<li>Grundstück: Aktivkonto, nimmt zu → <b>Soll</b>.<span class=\"why\">Warum: Aktivkonten buchen Zugänge im Soll (links), wie sie in der Bilanz links stehen.</span></li>\n<li>Zahlungsmittel: Aktivkonto, nimmt ab → <b>Haben</b>.<span class=\"why\">Warum: Abgänge bei Aktivkonten stehen im Haben (rechts).</span></li>\n<li>„Soll an Haben“: <b>Grundstücke an Zahlungsmittel 60.000</b>.<span class=\"why\">Warum: Im Buchungssatz steht zuerst das Soll-Konto, dann „an“ das Haben-Konto.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Soll 60.000 = Haben 60.000. Die Bilanzsumme bleibt gleich (Aktivtausch).</p>\n<p class=\"merke\"><b>Merke:</b> Typische Falle: die Seiten vertauschen. Was zunimmt bei Vermögen, steht immer im Soll.</p>","short":"Grundstücke an Zahlungsmittel 60.000","diag":true,"src":"eigene"},{"id":"bure-t47","topic":"bure-konten","level":2,"type":"mc","q":"Welcher Buchungssatz ist richtig? Der Inhaber entnimmt 1.000 bar.","options":["Zahlungsmittel an Eigenkapital (Entnahme) 1.000","Aufwand an Zahlungsmittel 1.000","Eigenkapital (Entnahme) an Zahlungsmittel 1.000","Eigenkapital (Einlage) an Zahlungsmittel 1.000"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Den richtigen Buchungssatz für eine Barentnahme finden.</p>\n<ol class=\"sol-steps\">\n<li>Eigenkapital (Entnahme): Unterkonto des EK, das EK nimmt ab → <b>Soll</b>.<span class=\"why\">Warum: EK ist ein Passivkonto. Abgänge bei Passivkonten stehen im Soll.</span></li>\n<li>Zahlungsmittel: Aktivkonto, nimmt ab → <b>Haben</b>.<span class=\"why\">Warum: Abgang bei Vermögen steht im Haben.</span></li>\n<li><b>Eigenkapital (Entnahme) an Zahlungsmittel 1.000</b>.<span class=\"why\">Warum: Soll an Haben. Es ist kein Aufwand, weil das Geld privat genutzt wird.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Entnahme ist kein Aufwand, sondern ein Transfer, gebucht auf dem EK-Unterkonto Entnahme.</p>","short":"Eigenkapital (Entnahme) an Zahlungsmittel 1.000","diag":true,"src":"eigene"},{"id":"bure-t48","topic":"bure-konten","level":2,"type":"mc","q":"T-Konto Zahlungsmittel: Anfangsbestand {{AB}}. Zugänge {{z1}} und {{z2}}, Abgänge {{a1}} und {{a2}}. Wie hoch ist der Endbestand?","options":["{{AB+z+a}}","{{o1m}}","{{EB}}","{{z-a}}"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Den Endbestand eines T-Kontos Zahlungsmittel berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Soll (Anfangsbestand und Zugänge): {{AB}} + {{z1}} + {{z2}} = <b>{{SS}}</b>.<span class=\"why\">Warum: Zahlungsmittel ist ein Aktivkonto: Anfangsbestand und Zugänge stehen links im Soll.</span></li>\n<li>Haben (Abgänge): {{a1}} + {{a2}} = <b>{{a}}</b>.<span class=\"why\">Warum: Abgänge stehen rechts im Haben.</span></li>\n<li>\\(EB = {{SS:0t}} - {{a:0t}} = {{EB:0t}}\\)<span class=\"why\">Warum: Endbestand = Soll-Summe − Haben-Summe. Im Alltag: so viel Geld ist am Ende da.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Haben + Endbestand: {{a}} + {{EB}} = {{SS}} = Soll-Summe.</p>\n<p class=\"merke\"><b>Merke:</b> Anfangsbestand gehört bei Aktivkonten ins Soll und wird mitgezählt.</p>","short":"{{EB}}","diag":true,"src":"eigene","gen":{"vars":{"AB":{"min":5000,"max":20000,"step":1000},"z1":{"min":1000,"max":5000,"step":100},"z2":{"min":1000,"max":5000,"step":100},"a1":{"min":1000,"max":6000,"step":100},"a2":{"min":500,"max":3000,"step":100}},"let":{"z":"z1+z2","a":"a1+a2","SS":"AB+z","EB":"SS-a","o1":"AB-z+a","o1m":"(o1<0?'−':'')+num(abs(o1))"},"check":"z > a"}},{"id":"bure-t49","topic":"bure-konten","level":3,"type":"mc","q":"Ein Kunde zahlt eine Forderung von 1.500 bar. Gebucht wurde aber „Forderungen an Zahlungsmittel 1.500“. Wie korrigierst du?","options":["Storno „Zahlungsmittel an Forderungen 1.500“, danach richtig „Zahlungsmittel an Forderungen 1.500“","Nur „Zahlungsmittel an Forderungen 1.500“","Nichts, die Saldenaufstellung gleicht das aus","Noch einmal „Forderungen an Zahlungsmittel 1.500“"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Eine Buchung mit vertauschten Seiten richtig korrigieren.</p>\n<ol class=\"sol-steps\">\n<li>Richtig wäre: <b>Zahlungsmittel an Forderungen 1.500</b>.<span class=\"why\">Warum: Zahlungsmittel (Aktiv) nimmt zu, also Soll. Forderung (Aktiv) nimmt ab, also Haben.</span></li>\n<li>Storno: dieselbe falsche Buchung mit getauschten Seiten: <b>Zahlungsmittel an Forderungen 1.500</b>.<span class=\"why\">Warum: Das hebt die falsche Buchung „Forderungen an Zahlungsmittel“ genau auf. Danach steht alles auf null.</span></li>\n<li>Danach richtig buchen: noch einmal <b>Zahlungsmittel an Forderungen 1.500</b>.<span class=\"why\">Warum: Erst jetzt ist der Zahlungseingang wirklich erfasst.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Zahlungsmittel: −1.500 (falsch) + 1.500 (Storno) + 1.500 (richtig) = +1.500. Stimmt.</p>\n<p class=\"merke\"><b>Merke:</b> Nur eine Gegenbuchung hebt den Fehler bloß auf; erst Storno plus richtige Buchung ergibt den richtigen Stand.</p>","short":"Storno, dann richtige Buchung (2 × ZM an Forderungen 1.500)","diag":true,"src":"eigene"},{"id":"bure-t50","topic":"bure-konten","level":1,"type":"mc","q":"Ein Ertrag entsteht. Auf welcher Seite des Ertragskontos wird gebucht?","options":["Soll","Haben","Je nach Betrag","Gar nicht, nur in der Bilanz"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Die Seite finden, auf der ein Ertrag gebucht wird.</p>\n<ol class=\"sol-steps\">\n<li>Ertrag ist ein Unterkonto des Eigenkapitals.<span class=\"why\">Warum: Ein Ertrag macht die Firma reicher, also erhöht er das EK.</span></li>\n<li>EK ist ein Passivkonto, Zugänge im <b>Haben</b>.<span class=\"why\">Warum: Passivkonten buchen Zugänge rechts, so wie Passiva in der Bilanz rechts stehen.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Ertrag und Einlage im Haben, Aufwand und Entnahme im Soll.</p>","short":"Haben","diag":false,"src":"eigene"},{"id":"bure-t51","topic":"bure-konten","level":2,"type":"mc","q":"Welche Aussage zur vorläufigen Saldenaufstellung stimmt?","options":["Jeder Buchungsfehler fällt auf","Ein falscher Betrag, der in Soll und Haben gleich gebucht ist, fällt nicht auf","Summe Soll ist immer größer als Summe Haben","Sie ersetzt das Journal"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Die richtige Aussage zur vorläufigen Saldenaufstellung finden.</p>\n<ol class=\"sol-steps\">\n<li>Sie prüft nur: Summe Soll = Summe Haben.<span class=\"why\">Warum: Jede Buchung hat Soll und Haben mit demselben Betrag. Darum müssen die Summen gleich sein.</span></li>\n<li>Ein falscher Betrag, der in Soll und Haben gleich gebucht ist, <b>fällt nicht auf</b>.<span class=\"why\">Warum: Beide Seiten sind dann gleich falsch, die Gleichheit bleibt.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Die Saldenaufstellung findet einseitige Fehler, aber keine, die auf beiden Seiten gleich falsch sind. <i>(Folie 33)</i></p>","short":"Gleicher falscher Betrag auf beiden Seiten fällt nicht auf","diag":false,"src":"eigene"},{"id":"bure-t52","topic":"bure-konten","level":1,"type":"mc","q":"Ergänze den Satz richtig: Die planmäßige Abschreibung einer Maschine am 31.12. ist …","options":["ein Geschäftsvorfall mit Beleg","ein anderes relevantes Ereignis (beleglose Buchung)","kein relevantes Ereignis","eine Entnahme"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Die planmäßige Abschreibung richtig einordnen.</p>\n<ol class=\"sol-steps\">\n<li>Kein physischer oder rechtlicher Vorgang und kein Beleg.<span class=\"why\">Warum: Niemand schickt eine Rechnung dafür, dass die Maschine älter wird.</span></li>\n<li>Trotzdem sinkt der Wert der Maschine → <b>anderes relevantes Ereignis</b>, beleglose Buchung.<span class=\"why\">Warum: Weil sich das Vermögen ändert, muss man buchen, auch ohne Beleg (Kapitel 5).</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Abschreibung ist ein Aufwand ohne Zahlung und ohne Beleg.</p>","short":"anderes relevantes Ereignis","diag":false,"src":"eigene"},{"id":"bure-t53","topic":"bure-ukv","level":1,"type":"mc","q":"Wie viele Buchungen braucht ein Verkauf von Erzeugnissen beim Umsatzkostenverfahren?","options":["Eine: nur die Ertragsbuchung","Zwei: Ertrags- und Aufwandsbuchung","Keine, erst am Jahresende","Drei: Ertrag, Aufwand, Bestandsänderung"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Zählen, wie viele Buchungen ein Verkauf beim UKV braucht.</p>\n<ol class=\"sol-steps\">\n<li>Ertragsbuchung: <b>Forderungen an Ertrag (Verkauf)</b>.<span class=\"why\">Warum: Forderung (Aktiv) nimmt zu, also Soll. Ertrag erhöht das EK, also Haben.</span></li>\n<li>Aufwandsbuchung: <b>Aufwand (Verkauf) an Fertigerzeugnisse</b>.<span class=\"why\">Warum: Beim UKV liegen die Herstellungsausgaben im Lager. Beim Verkauf werden sie Aufwand (Soll), das Lager nimmt ab (Haben).</span></li>\n<li>Also <b>zwei</b> Buchungen.<span class=\"why\">Warum: Beim GKV ist die Herstellung schon Aufwand, darum dort nur die Ertragsbuchung.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> UKV: Verkauf = Ertrag + Aufwand buchen; GKV: nur Ertrag.</p>","short":"Zwei","diag":true,"src":"eigene"},{"id":"bure-t54","topic":"bure-ukv","level":2,"type":"mc","q":"Welche Aussage zu UKV und GKV stimmt?","options":["UKV und GKV liefern bei gleichem Zuordnungsprinzip dasselbe Einkommen","Das GKV liefert immer das höhere Einkommen","Beim GKV gehen Herstellungsausgaben erst ins Lager","Beim UKV wird am Jahresende die Bestandsänderung gebucht"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Die richtige Aussage zu UKV und GKV finden.</p>\n<ol class=\"sol-steps\">\n<li>UKV: Herstellung erst ins Lager, Aufwand beim Verkauf.<span class=\"why\">Warum: Umsatzkostenverfahren: Aufwand nur für das, was umgesetzt (verkauft) wurde.</span></li>\n<li>GKV: Herstellung sofort Aufwand, am Jahresende Korrektur um die Bestandsänderung.<span class=\"why\">Warum: Gesamtkostenverfahren: erst alles als Aufwand, dann das Lager zurückrechnen.</span></li>\n<li>Beide kommen bei gleichem Zuordnungsprinzip auf <b>dasselbe Einkommen</b>.<span class=\"why\">Warum: Nur der Weg ist anders. Ob Marginal oder Final bewertet wird, entscheidet die Höhe.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Die Höhe des Einkommens hängt vom Zuordnungsprinzip ab, nicht vom Verfahren. <i>(Folie 53)</i></p>","short":"Gleiches Einkommen bei gleichem Zuordnungsprinzip","diag":true,"src":"eigene"},{"id":"bure-t55","topic":"bure-ukv","level":3,"type":"mc","q":"{{N}} Stück hergestellt, direkte Herstellungsausgaben {{D}} (bar). {{k}} Stück für {{V}} verkauft. Wie hoch ist das Einkommen nach GKV?","options":["{{O0m}}","{{Y}}","{{O2m}}","{{Au}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Das Einkommen nach GKV berechnen, wenn nicht alles verkauft wurde.</p>\n<ol class=\"sol-steps\">\n<li>GKV: {{D}} ist sofort Aufwand.<span class=\"why\">Warum: Beim Gesamtkostenverfahren ist jede Herstellungsausgabe gleich Aufwand.</span></li>\n<li>Unverkauft: {{N}} − {{k}} = {{N-k}} Stück. Lagermehrung: {{N-k}}/{{N}} · {{D}} = <b>{{La}}</b>.<span class=\"why\">Warum: Die Stücke im Lager sind noch Vermögen. Ihr Anteil an den Ausgaben wird als Lagermehrung zurückgerechnet.</span></li>\n<li>\\(E = {{V:0t}} + {{La:0t}} - {{D:0t}} = {{Y:0t}}\\)<span class=\"why\">Warum: Einkommen = Umsatz + Lagermehrung − gesamter Aufwand.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> UKV: {{V}} − {{k}}/{{N}} · {{D}} = {{V}} − {{Au}} = {{Y}}. Gleich.</p>\n<p class=\"merke\"><b>Merke:</b> Beim GKV die Lagermehrung nicht vergessen, sonst ist das Einkommen zu klein.</p>","short":"{{Y}}","diag":true,"src":"eigene","gen":{"vars":{"N":[100,200,250,400,500],"f":[50,60,70,75,80,90],"D":{"min":4000,"max":15000,"step":500},"V":{"min":5000,"max":20000,"step":500}},"let":{"k":"N*f/100","La":"D*(N-k)/N","Y":"V+La-D","Au":"D*k/N","Ys":"(Y<0?'−':'+')+num(abs(Y))","O0":"V-D","O2":"V-D-La","O0m":"(O0<0?'−':'')+num(abs(O0))","O2m":"(O2<0?'−':'')+num(abs(O2))"},"check":"isInt(k) && isInt(La) && Y > 0 && V-D != 0"}},{"id":"bure-t56","topic":"bure-ukv","level":2,"type":"mc","q":"UKV: Fertigerzeugnisse (Herstellung 5.000) werden verkauft. Welche Aufwandsbuchung gehört dazu?","options":["Fertigerzeugnisse an Aufwand (Verkauf) 5.000","Aufwand (Verkauf) an Fertigerzeugnisse 5.000","Fertigerzeugnisse an Lagermehrung 5.000","Aufwand (Material) an Zahlungsmittel 5.000"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Die Aufwandsbuchung beim Verkauf im UKV finden.</p>\n<ol class=\"sol-steps\">\n<li>Fertigerzeugnisse verlassen das Lager: Aktivkonto nimmt ab → <b>Haben</b>.<span class=\"why\">Warum: Abgang bei Vermögen steht im Haben.</span></li>\n<li>Umsatzaufwand entsteht: mindert das EK → <b>Soll</b>.<span class=\"why\">Warum: Aufwand ist ein EK-Unterkonto; was das EK mindert, steht im Soll.</span></li>\n<li><b>Aufwand (Verkauf) an Fertigerzeugnisse 5.000</b>.<span class=\"why\">Warum: Soll an Haben.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Beim UKV wird das Lager beim Verkauf zum Aufwand.</p>","short":"Aufwand (Verkauf) an Fertigerzeugnisse 5.000","diag":false,"src":"eigene"},{"id":"bure-t57","topic":"bure-sonder","level":1,"type":"mc","q":"Steuersatz {{r}} %. Eine Rechnung lautet brutto {{B}}. Wie hoch ist der Nettobetrag?","options":["{{cc?num(o0,2):num(o0)}}","{{cc?num(N,2):num(N)}}","{{cc?num(o2,2):num(o2)}}","{{cc?num(B,2):num(B)}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Aus dem Bruttobetrag den Nettobetrag berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Brutto = Netto + {{r}} % von Netto = Netto · \\({{qt}}\\).<span class=\"why\">Warum: Die Steuer wird auf den Nettobetrag aufgeschlagen. Netto ist also 100 %, Brutto 100 % + {{r}} % = {{100+r}} %.</span></li>\n<li>Umstellen: Netto = Brutto / \\({{qt}}\\).<span class=\"why\">Warum: Wenn man mit einer Zahl malnimmt, macht Teilen durch dieselbe Zahl das rückgängig.</span></li>\n<li>\\(P_n = \\frac{ {{B:0t}} }{ {{qt}} } = {{N:0t}}\\)<span class=\"why\">Warum: Der Nettobetrag ist im Alltag der Preis, der beim Unternehmen bleibt. Die Differenz geht ans Finanzamt.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> \\({{N:0t}} \\cdot {{qt}} = {{B:0t}}\\). Passt.</p>\n<p class=\"merke\"><b>Merke:</b> Fehlerfalle: {{r}} % vom Brutto abziehen ergibt {{o0c}}, das ist zu wenig, weil die Prozente vom Netto gerechnet werden.</p>","short":"{{N}}","diag":true,"src":"eigene","gen":{"vars":{"r":[10,19],"N":{"min":500,"max":5000,"step":100}},"let":{"B":"N*(100+r)/100","o0":"B*(100-r)/100","o2":"B*(100+r)/100","qt":"r==10?'1{,}1':'1{,}19'","o0c":"isInt(o0)?num(o0):num(o0,2)","o2c":"isInt(o2)?num(o2):num(o2,2)","cc":"!(isInt(o0) && isInt(o2))"},"check":"isInt(B)"}},{"id":"bure-t58","topic":"bure-sonder","level":2,"type":"mc","q":"Verkauf netto {{V}} und Einkauf netto {{K}}, jeweils mit {{r}} % Umsatzsteuer. Wie hoch ist die Zahllast?","options":["{{V-K}}","{{Mw+Vo}}","{{Z}}","{{Mw}}"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Die Umsatzsteuer-Zahllast berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Mehrwertsteuer beim Verkauf: {{V}} · {{rd:2}} = <b>{{Mw}}</b>.<span class=\"why\">Warum: {{r}} % heißt {{r}} von 100, also mal {{rd:2}}. Diese Steuer hat der Kunde bezahlt, sie gehört dem Finanzamt.</span></li>\n<li>Vorsteuer beim Einkauf: {{K}} · {{rd:2}} = <b>{{Vo}}</b>.<span class=\"why\">Warum: Diese Steuer hat die Firma selbst schon bezahlt und darf sie abziehen.</span></li>\n<li>\\(Z = {{Mw:0t}} - {{Vo:0t}} = {{Z:0t}}\\)<span class=\"why\">Warum: Zahllast heißt im Alltag: so viel überweist die Firma wirklich ans Finanzamt.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{r}} % von ({{V}} − {{K}}) = {{r}} % von {{V-K}} = {{Z}}. Gleiches Ergebnis.</p>\n<p class=\"merke\"><b>Merke:</b> Zahllast = MwSt minus Vorsteuer, nicht die Summe.</p>","short":"{{Z}}","diag":true,"src":"eigene","gen":{"vars":{"r":[10,19],"V":{"min":2000,"max":10000,"step":100},"K":{"min":1000,"max":8000,"step":100}},"let":{"Mw":"V*r/100","Vo":"K*r/100","Z":"Mw-Vo","rd":"r/100"},"check":"K < V"}},{"id":"bure-t59","topic":"bure-sonder","level":3,"type":"mc","q":"Welcher Buchungssatz ist richtig? Verkauf auf Ziel, brutto {{B}} ({{r}} % USt).","options":["Forderungen (Verkauf) {{B}} an Ertrag (Verkauf) {{B}}","Forderungen (Verkauf) {{B}} an Ertrag (Verkauf) {{N}} und Verbindlichkeiten (MwSt) {{St}}","Ertrag (Verkauf) {{N}} und Verbindlichkeiten (MwSt) {{St}} an Forderungen (Verkauf) {{B}}","Forderungen (Verkauf) {{N}} und Forderungen (VoSt) {{St}} an Ertrag (Verkauf) {{B}}"],"correct":1,"a":"<p class=\"goal\"><b>Ziel:</b> Den richtigen Buchungssatz für einen Verkauf auf Ziel mit Umsatzsteuer finden.</p>\n<ol class=\"sol-steps\">\n<li>Netto: {{B}} / {{qs}} = <b>{{N}}</b>. Steuer: {{B}} − {{N}} = <b>{{St}}</b>.<span class=\"why\">Warum: Brutto = Netto · {{qs}}, also durch {{qs}} teilen.</span></li>\n<li>Forderungen (Verkauf) {{B}} ins <b>Soll</b>.<span class=\"why\">Warum: Der Kunde schuldet uns den ganzen Bruttobetrag. Forderung (Aktiv) nimmt zu, also Soll.</span></li>\n<li>Ertrag (Verkauf) {{N}} ins <b>Haben</b>.<span class=\"why\">Warum: Nur der Nettobetrag ist verdient. Ertrag erhöht das EK, also Haben.</span></li>\n<li>Verbindlichkeiten (MwSt) {{St}} ins <b>Haben</b>.<span class=\"why\">Warum: Die Steuer gehört dem Finanzamt. Die Schuld (Passiv) nimmt zu, also Haben.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Haben: {{N}} + {{St}} = {{B}} = Soll.</p>\n<p class=\"merke\"><b>Merke:</b> Die Umsatzsteuer ist nie Ertrag, sondern eine Schuld beim Finanzamt.</p>","short":"Forderungen {{B}} an Ertrag {{N}} und Verb. (MwSt) {{St}}","diag":true,"src":"eigene","gen":{"vars":{"r":[10,19],"N":{"min":100,"max":3000,"step":100}},"let":{"St":"N*r/100","B":"N+St","qs":"r==10?'1,1':'1,19'"},"check":"isInt(St)"}},{"id":"bure-t60","topic":"bure-sonder","level":2,"type":"mc","q":"Brutto {{B}}, Arbeitnehmeranteil Sozialversicherung {{ANc}}, Unfallversicherung {{UV}}. AG-Anteil = AN-Anteil − 0,9 % des Bruttos. Wie hoch sind die Personalausgaben des Arbeitgebers?","options":["{{cc?num(o0,2):num(o0)}}","{{cc?num(o1,2):num(o1)}}","{{cc?num(P,2):num(P)}}","{{cc?num(o3,2):num(o3)}}"],"correct":2,"a":"<p class=\"goal\"><b>Ziel:</b> Die Personalausgaben des Arbeitgebers berechnen.</p>\n<ol class=\"sol-steps\">\n<li>0,9 % vom Brutto: 0,009 · {{B}} = {{Abc}}.<span class=\"why\">Warum: 0,9 % heißt 0,9 von 100, also 0,009.</span></li>\n<li>AG-Anteil: {{ANc}} − {{Abc}} = <b>{{AGc}}</b>.<span class=\"why\">Warum: Der Arbeitgeber zahlt etwas weniger Sozialversicherung als der Arbeitnehmer.</span></li>\n<li>\\(P = {{B:0t}} + {{isInt(AG)?tex(AG):tex(AG,2)}} + {{UV:0t}} = {{isInt(P)?tex(P):tex(P,2)}}\\)<span class=\"why\">Warum: Den Arbeitgeber kostet die Stelle: Brutto + eigener SV-Anteil + Unfallversicherung. Der AN-Anteil steckt schon im Brutto.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Den AN-Anteil nicht noch einmal dazurechnen; er wird vom Brutto abgezogen, nicht obendrauf gezahlt.</p>","short":"{{Pc}}","diag":true,"src":"eigene","gen":{"vars":{"B":{"min":1500,"max":5000,"step":100},"p":[195,200,205,210],"UV":{"min":10,"max":40,"step":1}},"let":{"AN":"B*p/1000","Ab":"B*9/1000","AG":"AN-Ab","P":"B+AG+UV","o0":"B+AN+UV","o1":"B+AG","o3":"B+AN+Ab","ANc":"isInt(AN)?num(AN):num(AN,2)","Abc":"isInt(Ab)?num(Ab):num(Ab,2)","AGc":"isInt(AG)?num(AG):num(AG,2)","Pc":"isInt(P)?num(P):num(P,2)","o0c":"isInt(o0)?num(o0):num(o0,2)","o1c":"isInt(o1)?num(o1):num(o1,2)","o3c":"isInt(o3)?num(o3):num(o3,2)","cc":"!(isInt(AN) && isInt(AG))"},"check":"isInt(AN*100) && isInt(AG*100) && abs(UV-Ab) > 0.5"}},{"id":"bure-t61","topic":"bure-sonder","level":1,"type":"mc","q":"Handelsware für {{P}} auf Ziel, {{s}} % Skonto bei Zahlung innerhalb von 10 Tagen. Was zahlst du am Tag 7?","options":["{{Z}}","{{o1}}","{{P}}","{{o3}}"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Den Zahlbetrag mit Skonto berechnen.</p>\n<ol class=\"sol-steps\">\n<li>Tag 7 liegt in der Skontofrist von 10 Tagen.<span class=\"why\">Warum: Also darf {{s}} % Skonto abgezogen werden.</span></li>\n<li>Skonto: {{s}} % von {{P}} = {{P}} / 100 · {{s}} = {{P*s/100}}.<span class=\"why\">Warum: Skonto ist ein Rabatt fürs schnelle Bezahlen.</span></li>\n<li>\\(Z = {{P:0t}} - {{P*s/100:0t}} = {{Z:0t}}\\)<span class=\"why\">Warum: Rechnungsbetrag minus Skonto. Das ist dasselbe wie {{P}} · (1 − {{sd:2}}).</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{Z}} + {{P*s/100}} = {{P}}.</p>\n<p class=\"merke\"><b>Merke:</b> Skonto wird abgezogen, nicht aufgeschlagen, und nur innerhalb der Frist.</p>","short":"{{Z}}","diag":false,"src":"eigene","gen":{"vars":{"P":{"min":1000,"max":10000,"step":100},"s":[2,3]},"let":{"Z":"P*(100-s)/100","o1":"P*(100+s)/100","o3":"P*9/10","sd":"s/100"}}},{"id":"bure-t62","topic":"bure-sonder","level":2,"type":"mc","q":"Wie wirkt die Umsatzsteuer auf das Einkommen eines Unternehmens mit Vorsteuerabzug?","options":["Gar nicht, sie ist einkommensneutral","Sie mindert das Einkommen um die Zahllast","Sie erhöht das Einkommen um die MwSt","Sie ist Aufwand beim Einkauf"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Klären, wie die Umsatzsteuer auf das Einkommen wirkt.</p>\n<ol class=\"sol-steps\">\n<li>Vorsteuer beim Einkauf → Forderung an das Finanzamt.<span class=\"why\">Warum: Die Firma bekommt sie zurück, also ist sie Vermögen.</span></li>\n<li>Mehrwertsteuer beim Verkauf → Verbindlichkeit beim Finanzamt.<span class=\"why\">Warum: Die Firma sammelt sie nur ein und gibt sie weiter.</span></li>\n<li>Kein Ertrags- oder Aufwandskonto ist betroffen → <b>einkommensneutral</b>.<span class=\"why\">Warum: Einkommen entsteht nur über Ertrag und Aufwand. Die Steuer läuft an der Firma vorbei.</span></li>\n</ol>\n<p class=\"merke\"><b>Merke:</b> Mit Vorsteuerabzug ist die Umsatzsteuer für die Firma ein durchlaufender Posten.</p>","short":"Gar nicht (einkommensneutral)","diag":false,"src":"eigene"},{"id":"bure-t300","topic":"bure-ek","level":2,"type":"open","q":"Ein Planungsbüro hat am 1.5.20X1 nur Barmittel: {{Z0}} (davon {{F0}} geliehen, {{E0}} von der Inhaberin eingelegt). Im Mai: a) Darlehen {{D}} bar aufgenommen. b) Einlage der Inhaberin {{Ei}} bar. c) Baugrundstück für {{G}} bar gekauft. d) Wertpapier für {{Ak}} bar gekauft. e) Das Wertpapier für {{Av}} bar verkauft. f) Ende Mai ist das Baugrundstück {{W}} wert.<br>1. Bestandsrechnung der <b>Vermögensgüter</b> (1.5., Zugänge, Abgänge, 31.5.). 2. Kapital aus Sicht aller Kapitalgeber. 3. Kapital getrennt nach FK und EK (EK als Saldo). 4. Wie hoch ist das Einkommen im Mai, und stimmt die Eigenkapitalveränderung?","a":"<p class=\"goal\"><b>Ziel:</b> Nicht nur die Barmittel, sondern alle Vermögensgüter betrachten. Dann FK und EK am 31.5. bestimmen und das EK über Einlage und Einkommen nachprüfen.</p>\n<ol class=\"sol-steps\">\n<li>Barmittel: Einzahlungen {{D}} + {{Ei}} + {{Av}} = {{Ez}}, Auszahlungen {{G}} + {{Ak}} = {{Az}}. Bestand 31.5.: {{Z0}} + {{Ez}} − {{Az}} = <b>{{Z1}}</b>.<span class=\"why\">Warum: Darlehen, Einlage und Verkauf des Wertpapiers bringen Geld. Kauf von Grundstück und Wertpapier kosten Geld. Die Wertsteigerung f ist keine Zahlung.</span></li>\n<li>1. Vermögensgüter:<table class=\"tt\"><tr><th>VG</th><th>1.5.</th><th>Zugänge</th><th>Abgänge</th><th>31.5.</th></tr><tr><td>Barmittel</td><td>{{Z0}}</td><td>{{Ez}}</td><td>{{Az}}</td><td>{{Z1}}</td></tr><tr><td>Baugrundstück</td><td>0</td><td>{{G}} + {{up}}</td><td>0</td><td>{{W}}</td></tr><tr><td>Wertpapier</td><td>0</td><td>{{Ak}}</td><td>{{Ak}}</td><td>0</td></tr><tr><td><b>Summe</b></td><td><b>{{Z0}}</b></td><td></td><td></td><td><b>{{V1}}</b></td></tr></table>Veränderung: {{V1}} − {{Z0}} = <b>{{dVs}}</b>.<span class=\"why\">Warum: Jetzt zählt jedes Vermögensgut. Das Grundstück kommt mit {{G}} herein und steigt um {{up}} auf {{W}}. Das Wertpapier kommt herein und geht wieder hinaus, am Ende ist es weg.</span></li>\n<li>2. Alle Kapitalgeber: Kapital 1.5. = {{Z0}}, Kapital 31.5. = {{V1}}.<span class=\"why\">Warum: Aus Sicht aller Kapitalgeber gehört jedes Vermögensgut irgendwem. Darum ist das Kapital so groß wie die Vermögensgüter: VG = FK + EK.</span></li>\n<li>3. FK 31.5.: {{F0}} + {{D}} = <b>{{F1}}</b>. EK als Saldo: {{V1}} − {{F1}} = <b>{{E1}}</b>.<table class=\"tt\"><tr><th>Kapital</th><th>1.5.</th><th>31.5.</th></tr><tr><td>FK</td><td>{{F0}}</td><td>{{F1}}</td></tr><tr><td>EK</td><td>{{E0}}</td><td>{{E1}}</td></tr><tr><td><b>Summe</b></td><td><b>{{Z0}}</b></td><td><b>{{V1}}</b></td></tr></table><span class=\"why\">Warum: Nur das Darlehen ändert das FK. Das EK ist aus Sicht der Eigenkapitalgeber der Rest: Vermögensgüter minus Schulden.</span></li>\n<li>4. Einkommen: Wertpapier {{Av}} − {{Ak}} = {{WPs}}, Grundstück {{W}} − {{G}} = {{ups}}. Summe <b>{{Ys}}</b>.<span class=\"why\">Warum: Ein Gewinn oder Verlust beim Wertpapier und die Wertsteigerung ändern das EK, ohne dass die Inhaberin etwas einlegt oder entnimmt. Das ist Einkommen. Die Einlage b ist dagegen Eigenkapitaltransfer.</span></li>\n<li>EK-Veränderung: {{E0}} + Einlage {{Ei}} {{Ys2}} (Einkommen) = <b>{{E1}}</b> ✓<span class=\"why\">Warum: Das EK ändert sich nur durch Transfer (Einlage, Entnahme) und Einkommen. Kommt dasselbe heraus wie in 3., ist alles stimmig.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> VG = FK + EK am 31.5.: {{F1}} + {{E1}} = {{V1}} ✓. Zum Vergleich nur Barmittel: EK wäre {{Z1}} − {{F1}} = {{EBs}}; der Unterschied {{E1}} − ({{EBs}}) = {{W}} ist genau das Grundstück.</p>\n<p class=\"merke\"><b>Merke:</b> Wer nur Barmittel zählt, übersieht das Grundstück und die Wertsteigerung. Erst die Sicht auf alle Vermögensgüter zeigt das richtige EK.</p>","short":"VG 31.5. {{V1}} ({{dVs}}); FK {{F1}}, EK {{E1}}; Einkommen {{Ys}}","src":"eigene (Variante zu Übungsskript BuFü A 2.3 Teil 5–7)","gen":{"vars":{"F0":{"min":1500,"max":3000,"step":100},"E0":{"min":1000,"max":2500,"step":100},"D":{"min":500,"max":1500,"step":100},"Ei":{"min":1000,"max":3000,"step":500},"G":{"min":2000,"max":4000,"step":100},"Ak":{"min":400,"max":1000,"step":100},"dv":{"min":-300,"max":400,"step":50,"not":[0]},"up":{"min":200,"max":1000,"step":100}},"let":{"Z0":"F0+E0","Av":"Ak+dv","W":"G+up","Ez":"D+Ei+Av","Az":"G+Ak","Z1":"Z0+Ez-Az","V1":"Z1+W","dV":"V1-Z0","F1":"F0+D","E1":"V1-F1","Y":"dv+up","EB":"Z1-F1","dVs":"(dV<0?'−':'+')+num(abs(dV))","WPs":"(dv<0?'−':'+')+num(abs(dv))","ups":"(up<0?'−':'+')+num(abs(up))","Ys":"(Y<0?'−':'+')+num(abs(Y))","Ys2":"(Y<0?'− ':'+ ')+num(abs(Y))","EBs":"EB<0?'−'+num(abs(EB)):num(EB)"},"check":"Z1 > 0 && E1 > 0 && E1 == E0+Ei+Y"},"diag":false},{"id":"bure-t301","topic":"bure-ek","level":2,"type":"mc","diag":true,"q":"Die Inhaberin bringt eine eigene Maschine im Wert von {{W}} in ihr Unternehmen ein. Welche Art von Ereignis ist das?","options":["Bilanzverlängerung mit Eigenkapitaltransferwirkung","Aktivtausch","Bilanzverlängerung mit Einkommenswirkung","Passivtausch ohne Eigenkapitalwirkung"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Wirkung auf die Bilanzgleichung VG = FK + EK bestimmen und dann die Art der EK-Wirkung.</p>\n<ol class=\"sol-steps\">\n<li>VG: Maschine +{{W}}. FK: unverändert. EK: +{{W}}.<span class=\"why\">Warum: Die Maschine ist jetzt Vermögen des Unternehmens. Niemand Fremdes hat Geld gegeben, also bleibt das FK gleich. Damit die Gleichung stimmt, steigt das EK.</span></li>\n<li>Beide Seiten steigen um {{W}} → <b>Bilanzverlängerung</b>.<span class=\"why\">Warum: Vermögen und Kapital nehmen gleich stark zu, die Bilanzsumme wächst.</span></li>\n<li>Die Inhaberin selbst löst die EK-Änderung aus → <b>Eigenkapitaltransferwirkung</b> (Einlage).<span class=\"why\">Warum: Einkommen entsteht durch Leistung am Markt oder Wertänderungen, nicht dadurch, dass die Eigentümerin etwas hineingibt.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Bilanzsumme vorher + {{W}} = nachher, EK-Transfer +{{W}}, Einkommen 0 ✓</p>\n<p class=\"merke\"><b>Merke:</b> Einlage = Bilanzverlängerung mit Transferwirkung. Entnahme = Bilanzverkürzung mit Transferwirkung.</p>","short":"Bilanzverlängerung mit Eigenkapitaltransferwirkung","src":"eigene (Typ wie Übungsskript BuFü A 2.2 Teil 2)","gen":{"vars":{"W":{"min":5000,"max":12000,"step":500}}}},{"id":"bure-t302","topic":"bure-ek","level":3,"type":"mc","q":"Ein Lieferant erlässt dem Unternehmen eine offene Verbindlichkeit über {{V}} (das Unternehmen muss sie nicht mehr bezahlen). Welche Art von Ereignis ist das?","options":["Passivtausch mit Einkommenswirkung","Bilanzverkürzung ohne Eigenkapitalwirkung","Aktivtausch","Passivtausch mit Eigenkapitaltransferwirkung"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Wirkung auf VG = FK + EK prüfen und dann, wer die EK-Änderung auslöst.</p>\n<ol class=\"sol-steps\">\n<li>VG: unverändert (es fließt kein Geld). FK: −{{V}}. EK: +{{V}}.<span class=\"why\">Warum: Die Schuld verschwindet, aber das Unternehmen zahlt nichts. Damit die Gleichung stimmt, muss das EK um denselben Betrag steigen.</span></li>\n<li>Nur die Kapitalseite ändert sich, die Bilanzsumme bleibt → <b>Passivtausch</b>.<span class=\"why\">Warum: Ein Kapitalposten (FK) sinkt, ein anderer (EK) steigt. Eine Bilanzverkürzung wäre es nur, wenn auch Vermögen abgehen würde, z. B. bei Bezahlung.</span></li>\n<li>Das EK steigt, ohne dass die Eigentümer etwas einlegen → <b>Einkommenswirkung</b> (Ertrag).<span class=\"why\">Warum: Transferwirkung gäbe es nur bei Einlage oder Entnahme durch die Eigentümer. Hier verzichtet ein Fremder auf Geld, das ist ein Ertrag.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> VG gleich, FK − {{V}}, EK + {{V}}: −{{V}} + {{V}} = 0 auf der Kapitalseite ✓</p>\n<p class=\"merke\"><b>Merke:</b> Passivtausch, Bilanzverlängerung und Bilanzverkürzung gibt es jeweils ohne EK-Wirkung, mit Einkommenswirkung oder mit Transferwirkung.</p>","short":"Passivtausch mit Einkommenswirkung","src":"eigene (Typ wie Übungsskript BuFü A 2.2 Teil 2)","gen":{"vars":{"V":{"min":1000,"max":6000,"step":500}}},"diag":false},{"id":"bure-t303","topic":"bure-ek","level":1,"type":"mc","diag":true,"q":"Welche der vier Ereignisarten hat <b>nie</b> eine Wirkung auf das Eigenkapital?","options":["Aktivtausch","Passivtausch","Bilanzverlängerung","Bilanzverkürzung"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Für jede Ereignisart prüfen, ob das EK betroffen sein kann.</p>\n<ol class=\"sol-steps\">\n<li>Aktivtausch: Nur Vermögensgüter tauschen, z. B. Grundstück gegen Geld. Die Kapitalseite bleibt ganz unberührt.<span class=\"why\">Warum: Das EK steht auf der Kapitalseite. Wenn sich dort nichts ändert, kann sich auch das EK nicht ändern.</span></li>\n<li>Passivtausch: z. B. Erlass einer Schuld (FK −, EK +) → EK-Wirkung möglich.<span class=\"why\">Warum: Ein Kapitalposten kann das EK sein.</span></li>\n<li>Bilanzverlängerung: z. B. Einlage (EK +) oder Dienstleistung gegen Bargeld (Einkommen) → möglich.<span class=\"why\">Warum: Die Kapitalseite steigt, das kann FK oder EK sein.</span></li>\n<li>Bilanzverkürzung: z. B. Entnahme (EK −) oder Miete bar bezahlt (Aufwand) → möglich.<span class=\"why\">Warum: Die Kapitalseite sinkt, das kann FK oder EK sein.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Zählen: Aktivtausch 1 Fall, die anderen je 3 (ohne EK-Wirkung, Einkommen, Transfer): 1 + 3 · 3 = 10 Fälle ✓</p>\n<p class=\"merke\"><b>Merke:</b> Aktivtausch ist immer erfolgsneutral. Alle anderen drei Arten können ohne, mit Einkommens- oder mit Transferwirkung auftreten.</p>","short":"Aktivtausch","src":"eigene (Typ wie Übungsskript BuFü A 2.2 Teil 2)"},{"id":"bure-t304","topic":"bure-konzepte","level":2,"type":"mc","q":"Ein Vermittlungsbüro vermittelt eine Wohnung und erhält dafür sofort eine Provision von {{P}} bar. Nach welchem Konzept entsteht hier Einkommen?","options":["Marktleistungsabgabekonzept","Periodisierungskonzept","Einkommensvorwegnahmekonzept","Gar keins: Es ist nur eine Einzahlung"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Die drei Einkommenskonzepte unterscheiden und die Provision zuordnen.</p>\n<ol class=\"sol-steps\">\n<li>Das Büro hat eine Leistung am Markt abgegeben: die Vermittlung. Dafür bekommt es {{P}}.<span class=\"why\">Warum: Die Provision ist der Preis für eine verkaufte Dienstleistung.</span></li>\n<li>Marktleistungsabgabekonzept: Einkommen aus Verkäufen entsteht, wenn die Leistung abgegeben ist → <b>Ertrag {{P}}</b>.<span class=\"why\">Warum: Genau das passiert hier: Leistung erbracht, Ertrag entsteht.</span></li>\n<li>Periodisierungskonzept: für Ausgaben ohne Bezug zu einem Verkauf, z. B. Miete. Einkommensvorwegnahme: für absehbare künftige Belastungen. Beides passt nicht.<span class=\"why\">Warum: Die Provision gehört direkt zu einer verkauften Leistung.</span></li>\n<li>„Nur Einzahlung“ ist falsch: Das EK steigt, also ist es mehr als eine Zahlung.<span class=\"why\">Warum: Eine reine Einzahlung ohne EK-Änderung wäre z. B. ein Darlehen.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Bilanz: Zahlungsmittel +{{P}}, EK +{{P}} (Ertrag); Bilanzverlängerung mit Einkommenswirkung ✓</p>\n<p class=\"merke\"><b>Merke:</b> Verkauf einer Leistung → Marktleistungsabgabekonzept. Miete, Dienstleistungen ohne Verkaufsbezug → Periodisierungskonzept.</p>","short":"Marktleistungsabgabekonzept","src":"eigene (Typ wie Übungsskript BuFü A 2.1 Teil 2)","gen":{"vars":{"P":{"min":800,"max":5000,"step":100}}},"diag":false},{"id":"bure-t305","topic":"bure-sonder","level":2,"type":"open","q":"Vermittlungsbüro, Steuersatz 10 % wie in der Vorlesung. a) Für eine Vermittlung erhält es brutto {{B}} bar. b) Es kauft Büromaterial für netto {{K}} auf Ziel, zuzüglich 10 % USt. Bestimme Netto-Ertrag, Mehrwertsteuer, Vorsteuer, Zahllast und die Einkommenswirkung. Bilde die Buchungssätze zu a) und b).","a":"<p class=\"goal\"><b>Ziel:</b> Brutto in Netto und Steuer zerlegen, beide Vorgänge buchen und zeigen, dass die Umsatzsteuer das Einkommen nicht ändert.</p>\n<ol class=\"sol-steps\">\n<li>a) Netto = {{B}} / 1,1 = <b>{{N}}</b>. MwSt = {{B}} − {{N}} = <b>{{M}}</b>.<span class=\"why\">Warum: Die 10 % beziehen sich auf den Nettobetrag: Brutto = 1,1 · Netto. Darum durch 1,1 teilen, nicht 10 % vom Brutto abziehen.</span></li>\n<li>Buchung a): <b>Zahlungsmittel {{B}} an Ertrag (Verkauf) {{N}} und Verbindlichkeiten (MwSt) {{M}}</b>.<span class=\"why\">Warum: Geld (Aktiv) steigt: Soll. Der Ertrag erhöht das EK: Haben. Die Steuer gehört dem Finanzamt, also eine Schuld (Passiv) im Haben.</span></li>\n<li>b) Vorsteuer = 10 % · {{K}} = <b>{{V}}</b>. Brutto {{K}} + {{V}} = {{KB}}.<span class=\"why\">Warum: Auf den Einkauf zahlt das Büro Steuer an den Lieferanten. Die holt es sich vom Finanzamt zurück.</span></li>\n<li>Buchung b): <b>Büromaterial {{K}} und Forderungen (VoSt) {{V}} an Verbindlichkeiten (Einkauf) {{KB}}</b>.<span class=\"why\">Warum: Büromaterial (Aktiv) und die Forderung gegen das Finanzamt (Aktiv) steigen: Soll. Die Schuld beim Lieferanten (Passiv) steigt um den Bruttobetrag: Haben.</span></li>\n<li>Zahllast = MwSt − VoSt = {{M}} − {{V}} = <b>{{Z}}</b>.<span class=\"why\">Warum: So viel überweist das Büro wirklich ans Finanzamt: kassierte Steuer minus schon gezahlte Steuer.</span></li>\n<li>Einkommen: <b>+{{N}}</b>.<span class=\"why\">Warum: Nur der Netto-Ertrag erhöht das EK. Das Büromaterial ist noch nicht verbraucht, also noch kein Aufwand. Die Umsatzsteuer läuft nur über Forderungs- und Schuldkonten.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{N}} · 1,1 = {{B}} ✓; Soll b) {{K}} + {{V}} = {{KB}} = Haben ✓</p>\n<p class=\"merke\"><b>Merke:</b> Netto aus Brutto: durch 1,1. Die Umsatzsteuer ist für das Unternehmen erfolgsneutral.</p>","short":"Netto {{N}}, MwSt {{M}}, VoSt {{V}}, Zahllast {{Z}}; Einkommen +{{N}}","src":"eigene (Typ wie Übungsskript BuFü A 2.1, mit 10 % USt)","gen":{"vars":{"N":{"min":1500,"max":6000,"step":100},"K":{"min":200,"max":1500,"step":10}},"let":{"B":"N*11/10","M":"B-N","V":"round(K/10,2)","KB":"K+V","Z":"round(M-V,2)"},"check":"isInt(V) && Z > 0"},"diag":false},{"id":"bure-t306","topic":"bure-zwecke","level":2,"type":"mc","q":"Ein Unternehmen nimmt einen Kredit auf: Rückzahlungsbetrag {{R}}, Disagio {{Dg}}, Zinsen {{z}} % pro Jahr auf den Rückzahlungsbetrag. Wie hoch ist die Einzahlung bei Auszahlung des Kredits?","options":["{{num(R-Dg)}}","{{num(R)}}","{{num(R+Dg)}}","{{num(R-Dg-Zi)}}"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Verstehen, was ein Disagio ist, und die Einzahlung sowie die Wirkung auf das Geldvermögen bestimmen.</p>\n<ol class=\"sol-steps\">\n<li>Disagio = Abschlag bei der Auszahlung. Die Bank zahlt weniger aus, als später zurückgezahlt werden muss.<span class=\"why\">Warum: Das Disagio ist eine Art vorweggenommener Zins.</span></li>\n<li>Einzahlung: {{R}} − {{Dg}} = <b>{{num(R-Dg)}}</b>.<span class=\"why\">Warum: Auf dem Konto kommt nur der Betrag nach Abzug des Disagios an.</span></li>\n<li>Geldvermögen: Zahlungsmittel +{{num(R-Dg)}}, Verbindlichkeit +{{R}} → <b>−{{Dg}}</b> (Ausgabe).<span class=\"why\">Warum: Geldvermögen = Zahlungsmittel + Forderungen − Verbindlichkeiten. Die Schuld ist größer als das erhaltene Geld.</span></li>\n<li>Zinsen pro Jahr: {{z}} % von {{R}} = <b>{{num(Zi)}}</b>.<span class=\"why\">Warum: Die Zinsen werden laut Aufgabe auf den Rückzahlungsbetrag berechnet, nicht auf die Auszahlung.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> {{num(R-Dg)}} + {{Dg}} = {{R}} = Rückzahlung ✓</p>\n<p class=\"merke\"><b>Merke:</b> Einzahlung = Rückzahlungsbetrag − Disagio. Das Disagio ist sofort eine Ausgabe, aber als Aufwand wird es in den Übungslösungen teils in einem Jahr, teils über die Laufzeit verteilt angesetzt: auf die Aufgabenstellung achten.</p>","short":"Einzahlung {{num(R-Dg)}}; Geldvermögen −{{Dg}}; Zinsen {{num(Zi)}} pro Jahr","src":"eigene (Typ wie Übungsskript BuFü A 1.3/1.4)","gen":{"vars":{"R":{"min":20000,"max":80000,"step":5000},"dp":[4,5,6,8],"z":[4,5,6]},"let":{"Dg":"R*dp/100","Zi":"R*z/100"},"check":"Zi != Dg"},"diag":false}],"formulas":[{"id":"bure-f1","name":"Intratemporale Bilanzgleichung","topic":"bure-ek","lecture":"bure-v1","tex":"\\text{VG} - \\text{FK} = \\text{EK}","what":"Eigenkapital ist der Rest: Vermögen minus Schulden an einem Stichtag.","parts":[{"sym":"\\text{VG}","name":"Vermögensgüter (Aktiva)","d":"Wert aller Vermögensgüter am Stichtag, in €.","kind":"größe","unit":"€","effect":"Mehr Vermögen → EK steigt um denselben Betrag."},{"sym":"\\text{FK}","name":"Fremdkapital","d":"Schulden gegenüber Fremden am Stichtag, in €.","kind":"größe","unit":"€","effect":"Mehr Fremdkapital → EK sinkt um denselben Betrag."},{"sym":"\\text{EK}","name":"Eigenkapital","d":"Anspruch des Eigentümers, ergibt sich als Rest, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Rest aus Vermögen minus Schulden."}],"unit":"€","ex":"Karl Gross: \\(161.500 - 2.000 = 159.500\\)"},{"id":"bure-f2","name":"Bilanz: Aktiva = Passiva","topic":"bure-ek","lecture":"bure-v1","tex":"\\text{Aktiva} = \\text{FK} + \\text{EK}","what":"Beide Bilanzseiten sind immer gleich groß.","parts":[{"sym":"\\text{Aktiva}","name":"Aktiva","d":"Summe der Vermögensgüter (Mittelverwendung), in €.","kind":"größe","unit":"€","effect":"Mehr Aktiva → FK + EK müssen um denselben Betrag größer sein."},{"sym":"\\text{FK}","name":"Fremdkapital","d":"Teil der Passiva: Mittel von Fremden, in €.","kind":"größe","unit":"€","effect":"Mehr FK bei gleichem EK → Aktiva um denselben Betrag größer."},{"sym":"\\text{EK}","name":"Eigenkapital","d":"Teil der Passiva: Mittel des Eigentümers, in €.","kind":"größe","unit":"€","effect":"Mehr EK bei gleichem FK → Aktiva um denselben Betrag größer."}],"unit":"€","ex":"\\(184.000 = 101.250 + 82.750\\)"},{"id":"bure-f3","name":"Intertemporale Bilanzgleichung","topic":"bure-zwecke","lecture":"bure-v1","tex":"B_t = B_{t-1} + Z_t - A_t","what":"Endbestand = Anfangsbestand plus Zunahmen minus Abnahmen im Zeitraum.","parts":[{"sym":"B_t","name":"Endbestand","d":"Bestand am Ende des Zeitraums t (Zahlungsmittel, Geldvermögen oder EK), in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Bestand am Ende des Zeitraums."},{"sym":"B_{t-1}","name":"Anfangsbestand","d":"Bestand am Ende der Vorperiode = Anfang von t, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → Endbestand um denselben Betrag höher."},{"sym":"Z_t","name":"Zunahmen","d":"Einzahlungen, Einnahmen bzw. Einlagen und Erträge im Zeitraum, in €.","ref":"index","kind":"größe","unit":"€","effect":"Mehr Zunahmen → Endbestand steigt um denselben Betrag."},{"sym":"A_t","name":"Abnahmen","d":"Auszahlungen, Ausgaben bzw. Entnahmen und Aufwand im Zeitraum, in €.","ref":"index","kind":"größe","unit":"€","effect":"Mehr Abnahmen → Endbestand sinkt um denselben Betrag."},{"sym":"t","name":"Zeitraum","d":"Der betrachtete Abrechnungszeitraum, z. B. das Jahr 20X1.","kind":"index","unit":"","effect":"Zählt die Zeiträume; t − 1 ist der Zeitraum davor."}],"unit":"€","ex":"Zahlungsmittel (A 2.3): \\(3.000 + 3.700 - 3.000 = 3.700\\)"},{"id":"bure-f4","name":"Eigenkapitalveränderungsrechnung","topic":"bure-ek","lecture":"bure-v1","tex":"EK_1 = EK_0 + \\text{Einl.} - \\text{Entn.} + \\text{Ertr.} - \\text{Aufw.}","what":"EK am Ende = EK am Anfang plus Transfers plus Einkommen.","parts":[{"sym":"EK_1","name":"EK am Ende","d":"Eigenkapital am Ende des Zeitraums, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Eigenkapital am Ende des Zeitraums."},{"sym":"EK_0","name":"EK am Anfang","d":"Eigenkapital am Anfang des Zeitraums, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → EK am Ende um denselben Betrag höher."},{"sym":"\\text{Einl.}","name":"Einlagen","d":"Was der Eigentümer ins Unternehmen gibt, in €.","kind":"größe","unit":"€","effect":"Mehr Einlagen → EK am Ende steigt um denselben Betrag."},{"sym":"\\text{Entn.}","name":"Entnahmen","d":"Was der Eigentümer für sich herausnimmt, in €.","kind":"größe","unit":"€","effect":"Mehr Entnahmen → EK am Ende sinkt um denselben Betrag."},{"sym":"\\text{Ertr.}","name":"Erträge","d":"Eigenkapitalmehrung durch die Tätigkeit, in €.","kind":"größe","unit":"€","effect":"Mehr Erträge → EK am Ende steigt um denselben Betrag."},{"sym":"\\text{Aufw.}","name":"Aufwand","d":"Eigenkapitalminderung durch die Tätigkeit, in €.","kind":"größe","unit":"€","effect":"Mehr Aufwand → EK am Ende sinkt um denselben Betrag."}],"unit":"€","ex":"\\(0 + 150.000 - 15.000 + 69.500 - 45.000 = 159.500\\)"},{"id":"bure-f5","name":"Einkommen (Gewinn oder Verlust)","topic":"bure-ek","lecture":"bure-v1","tex":"E = \\text{Ertr.} - \\text{Aufw.}","what":"Saldo der Einkommensrechnung: positiv Gewinn, negativ Verlust.","parts":[{"sym":"E","name":"Einkommen","d":"Gewinn (positiv) oder Verlust (negativ) des Zeitraums, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: positiv Gewinn, negativ Verlust."},{"sym":"\\text{Ertr.}","name":"Erträge","d":"Summe aller Erträge im Zeitraum, in €.","kind":"größe","unit":"€","effect":"Mehr Erträge → Einkommen steigt um denselben Betrag."},{"sym":"\\text{Aufw.}","name":"Aufwand","d":"Summe aller Aufwendungen im Zeitraum, in €.","kind":"größe","unit":"€","effect":"Mehr Aufwand → Einkommen sinkt um denselben Betrag."}],"unit":"€","ex":"\\(69.500 - 45.000 = 24.500\\)"},{"id":"bure-f6","name":"Eigenkapitaltransfer","topic":"bure-ek","lecture":"bure-v1","tex":"T = \\text{Einl.} - \\text{Entn.}","what":"Saldo der Eigenkapitaltransferrechnung: Einlagen minus Entnahmen.","parts":[{"sym":"T","name":"Transfersaldo","d":"Eigenkapitaländerung durch den Eigentümer selbst, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: EK-Änderung durch den Eigentümer selbst."},{"sym":"\\text{Einl.}","name":"Einlagen","d":"Geld oder Sachen, die der Eigentümer einbringt, in €.","kind":"größe","unit":"€","effect":"Mehr Einlagen → Transfersaldo steigt um denselben Betrag."},{"sym":"\\text{Entn.}","name":"Entnahmen","d":"Geld oder Sachen, die der Eigentümer herausnimmt, in €.","kind":"größe","unit":"€","effect":"Mehr Entnahmen → Transfersaldo sinkt um denselben Betrag."}],"unit":"€","ex":"\\(150.000 - 15.000 = 135.000\\)"},{"id":"bure-f7","name":"Geldvermögen","topic":"bure-zwecke","lecture":"bure-v1","tex":"GV = ZM + \\text{Ford.} - \\text{Verb.}","what":"Zahlungsmittel plus Forderungen minus Verbindlichkeiten.","parts":[{"sym":"GV","name":"Geldvermögen","d":"Bestand auf der geldvermögensorientierten Wertebene, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Geld plus Ansprüche minus Zahlungspflichten."},{"sym":"ZM","name":"Zahlungsmittel","d":"Bargeld und Bankguthaben, in €.","kind":"größe","unit":"€","effect":"Mehr Zahlungsmittel → Geldvermögen steigt um denselben Betrag."},{"sym":"\\text{Ford.}","name":"Forderungen","d":"Ansprüche auf künftiges Geld, in €.","kind":"größe","unit":"€","effect":"Mehr Forderungen → Geldvermögen steigt um denselben Betrag."},{"sym":"\\text{Verb.}","name":"Verbindlichkeiten","d":"Pflichten, künftig zu zahlen, in €.","kind":"größe","unit":"€","effect":"Mehr Verbindlichkeiten → Geldvermögen sinkt um denselben Betrag."}],"unit":"€","ex":"\\(2.000 + 1.000 - 500 = 2.500\\)"},{"id":"bure-f8","name":"Einzahlungsüberschuss","topic":"bure-zwecke","lecture":"bure-v1","tex":"S_Z = \\text{Einzahlungen} - \\text{Auszahlungen}","what":"Saldo der zahlungsorientierten Rechnung.","parts":[{"sym":"S_Z","name":"Zahlungssaldo","d":"Überschuss (positiv) oder Defizit (negativ) an Zahlungsmitteln, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: positiv Überschuss, negativ Defizit."},{"sym":"\\text{Einzahlungen}","name":"Einzahlungen","d":"Zahlungsmittel, die hereinkommen, in €.","kind":"größe","unit":"€","effect":"Mehr Einzahlungen → Zahlungssaldo steigt um denselben Betrag."},{"sym":"\\text{Auszahlungen}","name":"Auszahlungen","d":"Zahlungsmittel, die hinausgehen, in €.","kind":"größe","unit":"€","effect":"Mehr Auszahlungen → Zahlungssaldo sinkt um denselben Betrag."}],"unit":"€","ex":"A 1.4: \\(196.000 - 87.000 = 109.000\\)"},{"id":"bure-f9","name":"Einnahmenüberschuss","topic":"bure-zwecke","lecture":"bure-v1","tex":"S_{GV} = \\text{Einnahmen} - \\text{Ausgaben}","what":"Saldo der geldvermögensorientierten Rechnung.","parts":[{"sym":"S_{GV}","name":"Einnahme-Ausgabe-Saldo","d":"Änderung des Geldvermögens im Zeitraum, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Änderung des Geldvermögens im Zeitraum."},{"sym":"\\text{Einnahmen}","name":"Einnahmen","d":"Zunahmen des Geldvermögens (auch Forderungen), in €.","kind":"größe","unit":"€","effect":"Mehr Einnahmen → Saldo steigt um denselben Betrag."},{"sym":"\\text{Ausgaben}","name":"Ausgaben","d":"Abnahmen des Geldvermögens (auch neue Schulden), in €.","kind":"größe","unit":"€","effect":"Mehr Ausgaben → Saldo sinkt um denselben Betrag."}],"unit":"€","ex":"A 1.4: \\(156.000 - 132.000 = 24.000\\)"},{"id":"bure-f10","name":"Totalbetrachtung","topic":"bure-zwecke","lecture":"bure-v1","tex":"\\sum S_Z = \\sum E + \\sum T","what":"Über die ganze Lebensdauer: Zahlungssalden = Einkommen plus Transfers.","parts":[{"sym":"\\sum","name":"Summe über alle Jahre","d":"Werte aller Jahre der Lebensdauer addieren.","ref":"sum","kind":"operator","unit":"","effect":"Summiert die Werte aller Jahre der Lebensdauer."},{"sym":"S_Z","name":"Zahlungssaldo","d":"Einzahlungen minus Auszahlungen je Jahr, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist links: in Summe gleich Einkommen plus Transfers."},{"sym":"E","name":"Einkommen","d":"Erträge minus Aufwand je Jahr, in €.","kind":"größe","unit":"€","effect":"Mehr Einkommen insgesamt → Summe der Zahlungssalden um gleich viel höher."},{"sym":"T","name":"Transfer","d":"Einlagen minus Entnahmen je Jahr, in €.","kind":"größe","unit":"€","effect":"Mehr Transfers insgesamt → Summe der Zahlungssalden um gleich viel höher."}],"unit":"€","ex":"A 1.3: \\(-550.000 = -390.000 + (-160.000)\\)"},{"id":"bure-f11","name":"Gleichmäßige Wertminderung (Abschreibung)","topic":"bure-zwecke","lecture":"bure-v1","tex":"a = \\frac{AW}{n}","what":"Kaufpreis gleichmäßig auf die Nutzungsjahre verteilen.","parts":[{"sym":"a","name":"Wertminderung pro Jahr","d":"Aufwand je Nutzungsjahr, in € pro Jahr.","kind":"größe","unit":"€/Jahr","effect":"Ist das Ergebnis: gleicher Aufwand in jedem Nutzungsjahr."},{"sym":"\\frac{AW}{n}","name":"Bruch","d":"Anschaffungswert geteilt durch Nutzungsdauer.","ref":"frac","kind":"operator","unit":"","effect":"Teilt den Anschaffungswert durch die Nutzungsdauer."},{"sym":"AW","name":"Anschaffungswert","d":"Kaufpreis des Guts, in €.","kind":"größe","unit":"€","effect":"Höher → Abschreibung pro Jahr im selben Verhältnis höher."},{"sym":"n","name":"Nutzungsdauer","d":"Anzahl der Nutzungsjahre.","kind":"größe","unit":"Jahre","effect":"Größer → Abschreibung pro Jahr kleiner (steht im Nenner)."}],"unit":"€ pro Jahr","ex":"A 1.3: \\(\\frac{400.000}{4} = 100.000\\) pro Jahr"},{"id":"bure-f12","name":"Saldo eines Kontos","topic":"bure-konten","lecture":"bure-v2","tex":"S = \\sum \\text{Soll} - \\sum \\text{Haben}","what":"Differenz der Kontoseiten; positiv = Soll-Saldo, negativ = Haben-Saldo.","parts":[{"sym":"S","name":"Saldo","d":"Kontostand; er steht zum Ausgleich auf der kleineren Seite, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: positiv Soll-Saldo, negativ Haben-Saldo."},{"sym":"\\sum","name":"Summe","d":"Alle Beträge einer Kontoseite addieren.","ref":"sum","kind":"operator","unit":"","effect":"Summiert alle Beträge einer Kontoseite."},{"sym":"\\text{Soll}","name":"Soll-Seite","d":"Linke Kontoseite, in €.","kind":"größe","unit":"€","effect":"Mehr im Soll → Saldo steigt um denselben Betrag."},{"sym":"\\text{Haben}","name":"Haben-Seite","d":"Rechte Kontoseite, in €.","kind":"größe","unit":"€","effect":"Mehr im Haben → Saldo sinkt um denselben Betrag."}],"unit":"€","ex":"Zahlungsmittel: \\(300 - 100 = 200\\) (Soll-Saldo)"},{"id":"bure-f13","name":"Endbestand eines Aktivkontos","topic":"bure-konten","lecture":"bure-v2","tex":"EB = AB + \\text{Zug.} - \\text{Abg.}","what":"Anfangsbestand plus Zugänge (Soll) minus Abgänge (Haben).","parts":[{"sym":"EB","name":"Endbestand","d":"Saldo am Ende, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Bestand am Ende der Periode."},{"sym":"AB","name":"Anfangsbestand","d":"Steht beim Aktivkonto im Soll, in €.","kind":"größe","unit":"€","effect":"Höher → Endbestand um denselben Betrag höher."},{"sym":"\\text{Zug.}","name":"Zugänge","d":"Mehrungen, beim Aktivkonto im Soll, in €.","kind":"größe","unit":"€","effect":"Mehr Zugänge → Endbestand steigt um denselben Betrag."},{"sym":"\\text{Abg.}","name":"Abgänge","d":"Minderungen, beim Aktivkonto im Haben, in €.","kind":"größe","unit":"€","effect":"Mehr Abgänge → Endbestand sinkt um denselben Betrag."}],"unit":"€","ex":"\\(100 + 200 - 100 = 200\\)"},{"id":"bure-f14","name":"Kontrolle der doppelten Buchführung","topic":"bure-konten","lecture":"bure-v2","tex":"\\sum \\text{Soll} = \\sum \\text{Haben}","what":"Gilt für jeden Buchungssatz und für die ganze Saldenaufstellung.","parts":[{"sym":"\\sum","name":"Summe","d":"Alle Beträge addieren.","ref":"sum","kind":"operator","unit":"","effect":"Summiert alle Beträge einer Seite."},{"sym":"\\text{Soll}","name":"Soll-Beträge","d":"Alle Beträge links bzw. alle Soll-Salden, in €.","kind":"größe","unit":"€","effect":"Muss gleich der Haben-Summe sein; sonst steckt ein Buchungsfehler drin."},{"sym":"\\text{Haben}","name":"Haben-Beträge","d":"Alle Beträge rechts bzw. alle Haben-Salden, in €.","kind":"größe","unit":"€","effect":"Muss gleich der Soll-Summe sein; jede Buchung trifft beide Seiten."}],"unit":"€","ex":"Saldenaufstellung Karl Gross: \\(117.500 = 117.500\\)"},{"id":"bure-f15","name":"Buchungssatz","topic":"bure-konten","lecture":"bure-v2","tex":"\\text{Soll-Konto} \\;\\text{an}\\; \\text{Haben-Konto} \\;\\; \\text{Betrag}","what":"Erst das Konto mit Soll-Eintrag, dann „an“, dann das Haben-Konto.","parts":[{"sym":"\\text{Soll-Konto}","name":"Soll-Konto","d":"Konto, auf dem links gebucht wird.","kind":"größe","unit":"–","effect":"Wird links gebucht; steht im Buchungssatz immer zuerst."},{"sym":"\\text{an}","name":"an","d":"Trennwort zwischen Soll und Haben.","kind":"operator","unit":"","effect":"Trennt Soll-Konto und Haben-Konto im Buchungssatz."},{"sym":"\\text{Haben-Konto}","name":"Haben-Konto","d":"Konto, auf dem rechts gebucht wird.","kind":"größe","unit":"–","effect":"Wird rechts gebucht; steht im Buchungssatz nach „an“."},{"sym":"\\text{Betrag}","name":"Betrag","d":"Gleicher Betrag auf beiden Seiten, in €.","kind":"größe","unit":"€","effect":"Höher → beide Konten ändern sich um denselben Betrag."}],"unit":"","ex":"Grundstücke an Zahlungsmittel \\(60.000\\)"},{"id":"bure-f16","name":"Bruttopreis","topic":"bure-sonder","lecture":"bure-v2","tex":"P_b = P_n \\cdot (1 + s)","what":"Nettopreis plus Umsatzsteuer.","parts":[{"sym":"P_b","name":"Bruttopreis","d":"Preis mit Umsatzsteuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Preis inklusive Umsatzsteuer."},{"sym":"P_n","name":"Nettopreis","d":"Preis ohne Umsatzsteuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → Bruttopreis im selben Verhältnis höher."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Nettopreis mit (1 + s)."},{"sym":"s","name":"Steuersatz","d":"Als Dezimalzahl; in der Vorlesung 10 % = 0,1.","kind":"größe","unit":"–","effect":"Höher → mehr Steuer, Bruttopreis steigt um P_n mal den Zuwachs."}],"unit":"€","ex":"\\(100 \\cdot 1{,}1 = 110\\)"},{"id":"bure-f17","name":"Nettopreis","topic":"bure-sonder","lecture":"bure-v2","tex":"P_n = \\frac{P_b}{1 + s}","what":"Brutto durch (1 + Steuersatz).","parts":[{"sym":"P_n","name":"Nettopreis","d":"Preis ohne Umsatzsteuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Preis ohne Umsatzsteuer."},{"sym":"\\frac{P_b}{1 + s}","name":"Bruch","d":"Brutto geteilt durch (1 + Steuersatz).","ref":"frac","kind":"operator","unit":"","effect":"Teilt den Bruttopreis durch (1 + s)."},{"sym":"P_b","name":"Bruttopreis","d":"Preis mit Umsatzsteuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → Nettopreis im selben Verhältnis höher."},{"sym":"s","name":"Steuersatz","d":"Als Dezimalzahl, z. B. 0,1.","kind":"größe","unit":"–","effect":"Höher → Nettopreis kleiner (steht im Nenner)."}],"unit":"€","ex":"\\(\\frac{3.300}{1{,}1} = 3.000\\)"},{"id":"bure-f18","name":"Umsatzsteuerbetrag","topic":"bure-sonder","lecture":"bure-v2","tex":"U = P_n \\cdot s = P_b - P_n","what":"Steuer = Netto mal Steuersatz = Brutto minus Netto.","parts":[{"sym":"U","name":"Umsatzsteuer","d":"Steuerbetrag, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Steuer zwischen Netto- und Bruttopreis."},{"sym":"P_n","name":"Nettopreis","d":"Preis ohne Steuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → Steuer im selben Verhältnis höher."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Nettopreis mit dem Steuersatz."},{"sym":"s","name":"Steuersatz","d":"Als Dezimalzahl, z. B. 0,1.","kind":"größe","unit":"–","effect":"Höher → Steuer im selben Verhältnis höher."},{"sym":"P_b","name":"Bruttopreis","d":"Preis mit Steuer, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher bei gleichem Netto → Steuer um denselben Betrag höher."}],"unit":"€","ex":"\\(3.000 \\cdot 0{,}1 = 300 = 3.300 - 3.000\\)"},{"id":"bure-f19","name":"Zahllast","topic":"bure-sonder","lecture":"bure-v2","tex":"Z = \\text{MwSt} - \\text{VoSt}","what":"Eingenommene Mehrwertsteuer minus gezahlte Vorsteuer geht an den Fiskus.","parts":[{"sym":"Z","name":"Zahllast","d":"Betrag, der an den Fiskus überwiesen wird, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: an den Fiskus zu zahlen; negativ = Erstattung."},{"sym":"\\text{MwSt}","name":"Mehrwertsteuer","d":"Beim Verkauf eingenommene Umsatzsteuer (Verbindlichkeit), in €.","kind":"größe","unit":"€","effect":"Mehr Mehrwertsteuer → Zahllast steigt um denselben Betrag."},{"sym":"\\text{VoSt}","name":"Vorsteuer","d":"Beim Einkauf gezahlte Umsatzsteuer (Forderung), in €.","kind":"größe","unit":"€","effect":"Mehr Vorsteuer → Zahllast sinkt um denselben Betrag."}],"unit":"€","ex":"Folie 75: \\(7 - 5 = 2\\)"},{"id":"bure-f20","name":"Nettolohn","topic":"bure-sonder","lecture":"bure-v2","tex":"L_n = L_b - St - SV_{AN}","what":"Brutto minus Steuern minus Arbeitnehmeranteil zur Sozialversicherung.","parts":[{"sym":"L_n","name":"Nettolohn","d":"Was beim Arbeitnehmer ankommt (vor vermögenswirksamen Leistungen), in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Lohn, der beim Arbeitnehmer ankommt."},{"sym":"L_b","name":"Bruttolohn","d":"Vereinbarter Lohn vor Abzügen, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher bei gleichen Abzügen → Nettolohn um denselben Betrag höher."},{"sym":"St","name":"Steuern","d":"Lohnsteuer, Soli, Kirchensteuer, in €.","kind":"größe","unit":"€","effect":"Mehr Steuern → Nettolohn sinkt um denselben Betrag."},{"sym":"SV_{AN}","name":"Sozialversicherung AN","d":"Arbeitnehmeranteil zur Sozialversicherung, in €.","ref":"index","kind":"größe","unit":"€","effect":"Mehr AN-Sozialversicherung → Nettolohn sinkt um denselben Betrag."}],"unit":"€","ex":"\\(2.817 - 568{,}86 - 587{,}32 = 1.660{,}82\\)"},{"id":"bure-f21","name":"Arbeitgeberanteil Sozialversicherung (Folie 66)","topic":"bure-sonder","lecture":"bure-v2","tex":"SV_{AG} = SV_{AN} - 0{,}009 \\cdot L_b","what":"Der AG-Anteil ist um 0,9 % des Bruttos kleiner als der AN-Anteil.","parts":[{"sym":"SV_{AG}","name":"Sozialversicherung AG","d":"Arbeitgeberanteil zur Sozialversicherung, in €.","ref":"index","kind":"größe","unit":"€","effect":"Ist das Ergebnis: AG-Anteil, 0,9 % des Bruttos unter dem AN-Anteil."},{"sym":"SV_{AN}","name":"Sozialversicherung AN","d":"Arbeitnehmeranteil, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → AG-Anteil um denselben Betrag höher."},{"sym":"0{,}009","name":"0,9 %","d":"0,9 Prozent als Dezimalzahl.","kind":"konstante","unit":"–","effect":"Fester Satz: 0,9 % des Bruttolohns werden abgezogen."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Satz 0,009 mit dem Bruttolohn."},{"sym":"L_b","name":"Bruttolohn","d":"Lohn vor Abzügen, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher bei gleichem AN-Anteil → AG-Anteil sinkt um 0,9 % davon."}],"unit":"€","ex":"\\(587{,}32 - 0{,}009 \\cdot 2.817 = 561{,}97\\)"},{"id":"bure-f22","name":"Personalausgaben des Arbeitgebers","topic":"bure-sonder","lecture":"bure-v2","tex":"P = L_b + SV_{AG} + UV","what":"Brutto plus Arbeitgeberanteil plus Unfallversicherung.","parts":[{"sym":"P","name":"Personalausgaben","d":"Alles, was der Arbeitgeber für die Stelle zahlt, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: alles, was der Arbeitgeber für die Stelle zahlt."},{"sym":"L_b","name":"Bruttolohn","d":"Lohn vor Abzügen, in €.","ref":"index","kind":"größe","unit":"€","effect":"Mehr Bruttolohn → Personalausgaben steigt um denselben Betrag."},{"sym":"SV_{AG}","name":"Sozialversicherung AG","d":"Arbeitgeberanteil, in €.","ref":"index","kind":"größe","unit":"€","effect":"Mehr AG-Anteil → Personalausgaben steigt um denselben Betrag."},{"sym":"UV","name":"Unfallversicherung","d":"Beitrag zur Berufsgenossenschaft, in €.","kind":"größe","unit":"€","effect":"Mehr Unfallversicherung → Personalausgaben steigt um denselben Betrag."}],"unit":"€","ex":"\\(2.817 + 561{,}97 + 20 = 3.398{,}97\\)"},{"id":"bure-f23","name":"Zahlung mit Skonto","topic":"bure-sonder","lecture":"bure-v2","tex":"Z = R \\cdot (1 - s_k)","what":"Rechnungsbetrag minus Skonto.","parts":[{"sym":"Z","name":"Zahlbetrag","d":"Was bei Zahlung in der Skontofrist überwiesen wird, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Rechnungsbetrag abzüglich Skonto."},{"sym":"R","name":"Rechnungsbetrag","d":"Betrag laut Rechnung, in €.","kind":"größe","unit":"€","effect":"Höher → Zahlbetrag im selben Verhältnis höher."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Rechnungsbetrag mit (1 − s_k)."},{"sym":"s_k","name":"Skontosatz","d":"Als Dezimalzahl, 2 % = 0,02.","ref":"index","kind":"größe","unit":"–","effect":"Höher → Zahlbetrag kleiner (um R mal s_k)."}],"unit":"€","ex":"\\(2.000 \\cdot 0{,}98 = 1.960\\)"},{"id":"bure-f24","name":"Einkommen nach UKV","topic":"bure-ukv","lecture":"bure-v2","tex":"E = UE - UA + sE - sA","what":"Umsatzertrag minus Umsatzaufwand der verkauften Menge, plus Sonstiges.","parts":[{"sym":"E","name":"Einkommen","d":"Gewinn oder Verlust, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Gewinn (positiv) oder Verlust (negativ)."},{"sym":"UE","name":"Umsatzertrag","d":"Erlös aus dem Verkauf, in €.","kind":"größe","unit":"€","effect":"Mehr Umsatzertrag → Einkommen steigt um denselben Betrag."},{"sym":"UA","name":"Umsatzaufwand","d":"Herstellungsausgaben der verkauften Menge, in €.","kind":"größe","unit":"€","effect":"Mehr Umsatzaufwand → Einkommen sinkt um denselben Betrag."},{"sym":"sE","name":"sonstiger Ertrag","d":"Erträge ohne Bezug zum Absatz, in €.","kind":"größe","unit":"€","effect":"Mehr sonstiger Ertrag → Einkommen steigt um denselben Betrag."},{"sym":"sA","name":"sonstiger Aufwand","d":"Aufwand ohne Bezug zur Herstellung, in €.","kind":"größe","unit":"€","effect":"Mehr sonstiger Aufwand → Einkommen sinkt um denselben Betrag."}],"unit":"€","ex":"\\(7.500 - 5.000 = 2.500\\)"},{"id":"bure-f25","name":"Einkommen nach GKV","topic":"bure-ukv","lecture":"bure-v2","tex":"E = UE + LM - LMi - HA + sE - sA","what":"Alle Herstellungsausgaben als Aufwand, Bestandsänderung als Korrektur.","parts":[{"sym":"E","name":"Einkommen","d":"Gewinn oder Verlust, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Gewinn (positiv) oder Verlust (negativ)."},{"sym":"UE","name":"Umsatzertrag","d":"Erlös aus dem Verkauf, in €.","kind":"größe","unit":"€","effect":"Mehr Umsatzertrag → Einkommen steigt um denselben Betrag."},{"sym":"LM","name":"Lagermehrung","d":"Wert der zusätzlich eingelagerten Erzeugnisse, in €.","kind":"größe","unit":"€","effect":"Mehr Lagermehrung → Einkommen steigt um denselben Betrag."},{"sym":"LMi","name":"Lagerminderung","d":"Wert der aus dem Lager verkauften Altbestände, in €.","kind":"größe","unit":"€","effect":"Mehr Lagerminderung → Einkommen sinkt um denselben Betrag."},{"sym":"HA","name":"Herstellungsausgaben","d":"Alle Herstellungsausgaben der Periode, nach Arten, in €.","kind":"größe","unit":"€","effect":"Mehr Herstellungsausgaben → Einkommen sinkt um denselben Betrag."},{"sym":"sE","name":"sonstiger Ertrag","d":"Erträge ohne Bezug zum Absatz, in €.","kind":"größe","unit":"€","effect":"Mehr sonstiger Ertrag → Einkommen steigt um denselben Betrag."},{"sym":"sA","name":"sonstiger Aufwand","d":"Aufwand ohne Bezug zur Herstellung, in €.","kind":"größe","unit":"€","effect":"Mehr sonstiger Aufwand → Einkommen sinkt um denselben Betrag."}],"unit":"€","ex":"\\(6.000 + 1.000 - 5.000 = 2.000\\)"},{"id":"bure-f26","name":"Umsatzaufwand","topic":"bure-ukv","lecture":"bure-v2","tex":"UA = \\frac{x_v}{x_h} \\cdot HA","what":"Verkaufter Anteil mal Herstellungsausgaben im Lager.","parts":[{"sym":"UA","name":"Umsatzaufwand","d":"Aufwand für die verkaufte Menge, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Aufwand für die verkaufte Menge."},{"sym":"\\frac{x_v}{x_h}","name":"Bruch","d":"Verkaufter Anteil der hergestellten Menge.","ref":"frac","kind":"operator","unit":"","effect":"Bildet den verkauften Anteil der hergestellten Menge."},{"sym":"x_v","name":"verkaufte Menge","d":"Stückzahl, die verkauft wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Mehr verkauft → Umsatzaufwand steigt im selben Verhältnis."},{"sym":"x_h","name":"hergestellte Menge","d":"Stückzahl, die hergestellt wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Größer → Umsatzaufwand kleiner (steht im Nenner)."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Anteil mit den Herstellungsausgaben."},{"sym":"HA","name":"Herstellungsausgaben","d":"Was ins Lager ging (je nach Zuordnungsprinzip), in €.","kind":"größe","unit":"€","effect":"Höher → Umsatzaufwand im selben Verhältnis höher."}],"unit":"€","ex":"\\(\\frac{80}{100} \\cdot 5.000 = 4.000\\)"},{"id":"bure-f27","name":"Lagermehrung (GKV)","topic":"bure-ukv","lecture":"bure-v2","tex":"LM = \\frac{x_h - x_v}{x_h} \\cdot HA","what":"Nicht verkaufter Anteil mal Herstellungsausgaben.","parts":[{"sym":"LM","name":"Lagermehrung","d":"Korrektur am Jahresende beim GKV, in €.","kind":"größe","unit":"€","effect":"Ist das Ergebnis: Wert der Menge, die im Lager bleibt."},{"sym":"\\frac{x_h - x_v}{x_h}","name":"Bruch","d":"Anteil, der im Lager bleibt.","ref":"frac","kind":"operator","unit":"","effect":"Bildet den Anteil der Menge, der im Lager bleibt."},{"sym":"x_h","name":"hergestellte Menge","d":"Stückzahl, die hergestellt wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Größer bei gleichem Verkauf → größerer Lageranteil, LM steigt."},{"sym":"x_v","name":"verkaufte Menge","d":"Stückzahl, die verkauft wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Mehr verkauft → weniger im Lager, Lagermehrung sinkt."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Lageranteil mit den Herstellungsausgaben."},{"sym":"HA","name":"Herstellungsausgaben","d":"Zugeordnete Herstellungsausgaben, in €.","kind":"größe","unit":"€","effect":"Höher → Lagermehrung im selben Verhältnis höher."}],"unit":"€","ex":"\\(\\frac{100 - 80}{100} \\cdot 5.000 = 1.000\\)"},{"id":"bure-f28","name":"Final- minus Marginalprinzip","topic":"bure-konzepte","lecture":"bure-v1","tex":"E_F - E_M = \\frac{x_h - x_v}{x_h} \\cdot HA_{ind}","what":"Bei Lagermehrung steckt dieser Teil der indirekten Ausgaben beim Finalprinzip noch im Lager.","parts":[{"sym":"E_F","name":"Einkommen Finalprinzip","d":"Direkte und indirekte Ausgaben gehen ins Lager, in €.","ref":"index","kind":"größe","unit":"€","effect":"Größer → Unterschied E_F − E_M wächst um denselben Betrag."},{"sym":"E_M","name":"Einkommen Marginalprinzip","d":"Nur direkte Ausgaben gehen ins Lager, in €.","ref":"index","kind":"größe","unit":"€","effect":"Größer → Unterschied E_F − E_M sinkt um denselben Betrag."},{"sym":"\\frac{x_h - x_v}{x_h}","name":"Bruch","d":"Anteil der Menge, der im Lager bleibt.","ref":"frac","kind":"operator","unit":"","effect":"Bildet den Anteil der Menge, der im Lager bleibt."},{"sym":"x_h","name":"hergestellte Menge","d":"Stückzahl, die hergestellt wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Größer bei gleichem Verkauf → Unterschied E_F − E_M wächst."},{"sym":"x_v","name":"verkaufte Menge","d":"Stückzahl, die verkauft wurde.","ref":"index","kind":"größe","unit":"Stück","effect":"Mehr verkauft → Unterschied E_F − E_M wird kleiner."},{"sym":"\\cdot","name":"mal","d":"Multiplikation.","ref":"cdot","kind":"operator","unit":"","effect":"Multipliziert den Lageranteil mit den indirekten Ausgaben."},{"sym":"HA_{ind}","name":"indirekte Herstellungsausgaben","d":"Z. B. Hallenlicht, in €.","ref":"index","kind":"größe","unit":"€","effect":"Höher → Unterschied E_F − E_M im selben Verhältnis größer."}],"unit":"€","ex":"Ü 10: \\(\\frac{1.000 - 800}{1.000} \\cdot 3.000 = 600\\)"}]};